INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13242, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施以", "is_correct": true, "explanation": "施以 shīyǐ：对某人或某物施加行为或影响，是正确答案。"}, {"text": "十亿", "is_correct": false, "explanation": "十亿 shíyì 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是数字“十亿”。"}, {"text": "十一", "is_correct": false, "explanation": "十一 shíyī 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yī（第一声）与 yǐ（第三声），意思是数字“十一”。"}, {"text": "诗意", "is_correct": false, "explanation": "诗意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“诗的意境”。"}, {"text": "石椅", "is_correct": false, "explanation": "石椅 shíyǐ 与 施以 shīyǐ 第一个音节声调不同：shí（第二声）与 shī（第一声），意思是“石头做的椅子”。"}], "explanations": {"施以": "施以 shīyǐ：对某人或某物施加行为或影响，是正确答案。", "十亿": "十亿 shíyì 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是数字“十亿”。", "十一": "十一 shíyī 与 施以 shīyǐ 声调不同：shí（第二声）与 shī（第一声），yī（第一声）与 yǐ（第三声），意思是数字“十一”。", "诗意": "诗意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“诗的意境”。", "石椅": "石椅 shíyǐ 与 施以 shīyǐ 第一个音节声调不同：shí（第二声）与 shī（第一声），意思是“石头做的椅子”。"}, "sentence_index": null, "correct_answer": "施以"}, "level_3": {"options": [{"text": "接受", "is_correct": false, "explanation": "配价：“接受”的主语应是承受者，这里主语是“部分国家”，不能说“国家接受刑事处罚”。"}, {"text": "施以", "is_correct": true, "explanation": "施以：对违规行为施加处罚，与“对……”搭配，符合句意。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”的宾语是礼物或财物，不能与“刑事处罚”搭配。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指得到好处或乐趣，与“刑事处罚”的惩罚含义相反。"}], "explanations": {"接受": "配价：“接受”的主语应是承受者，这里主语是“部分国家”，不能说“国家接受刑事处罚”。", "施以": "施以：对违规行为施加处罚，与“对……”搭配，符合句意。", "赠送": "搭配：“赠送”的宾语是礼物或财物，不能与“刑事处罚”搭配。", "享受": "语义：“享受”指得到好处或乐趣，与“刑事处罚”的惩罚含义相反。"}, "sentence_index": 0, "correct_answer": "施以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "立法机关施以新的法律。", "explanation": "这里应该用〈颁布〉。施以是对人或事物施加行为，法律是颁布的，不说“施以法律”。"}, {"text": "学校施以一次期末晚会。", "explanation": "这里应该用〈举办〉。“施以”的宾语是针对人的行为，晚会是要举办的活动，应说“学校举办一次期末晚会”。"}, {"text": "我对老师施以感谢。", "explanation": "这里应该用〈表示〉。施以的宾语是援手、惩戒等具体行为，感谢是态度，要说“表示感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13242, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "施以", "is_correct": true, "explanation": "施以 shīyǐ：对某人或某物施加行为或影响，是正确答案。"}, {"text": "示意", "is_correct": false, "explanation": "示意 shìyì 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是“用动作或表情表达意思”。"}, {"text": "事宜", "is_correct": false, "explanation": "事宜 shìyí 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yí（第二声）与 yǐ（第三声），意思是“具体的事情和安排”。"}, {"text": "失意", "is_correct": false, "explanation": "失意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“不得志、情绪低落”。"}, {"text": "时宜", "is_correct": false, "explanation": "时宜 shíyí 与 施以 shīyǐ 两个音节声调都不同，意思是“适合当时的情况”。"}], "explanations": {"施以": "施以 shīyǐ：对某人或某物施加行为或影响，是正确答案。", "示意": "示意 shìyì 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yì（第四声）与 yǐ（第三声），意思是“用动作或表情表达意思”。", "事宜": "事宜 shìyí 与 施以 shīyǐ 两个音节声调都不同：shì（第四声）与 shī（第一声），yí（第二声）与 yǐ（第三声），意思是“具体的事情和安排”。", "失意": "失意 shīyì 与 施以 shīyǐ 第二个音节声调不同：yì（第四声）与 yǐ（第三声），意思是“不得志、情绪低落”。", "时宜": "时宜 shíyí 与 施以 shīyǐ 两个音节声调都不同，意思是“适合当时的情况”。"}, "sentence_index": null, "correct_answer": "施以"}, "level_3": {"options": [{"text": "摆脱", "is_correct": false, "explanation": "搭配：“摆脱”的宾语是困境或束缚，不能与“援手”搭配，句意不通。"}, {"text": "施以", "is_correct": true, "explanation": "施以：向灾区给予援助，与“援手”搭配，符合句意。"}, {"text": "获得", "is_correct": false, "explanation": "语义：“获得”指接受，句中“很多人”是施予援助的一方，与句意相反。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”用于费用、财物，不说“收取援手”。"}], "explanations": {"摆脱": "搭配：“摆脱”的宾语是困境或束缚，不能与“援手”搭配，句意不通。", "施以": "施以：向灾区给予援助，与“援手”搭配，符合句意。", "获得": "语义：“获得”指接受，句中“很多人”是施予援助的一方，与句意相反。", "收取": "搭配：“收取”用于费用、财物，不说“收取援手”。"}, "sentence_index": 6, "correct_answer": "施以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对朋友施以快乐。", "explanation": "这里应该用〈带来〉。施以是对人施加行为，快乐是感受，要说“给朋友带来快乐”。"}, {"text": "他对朋友施以邀请。", "explanation": "这里应该用〈发出〉。施以的宾语是行为或援助，邀请是要发出的东西，要说“向朋友发出邀请”。"}, {"text": "他对朋友施以麻烦。", "explanation": "这里应该用〈制造〉。麻烦是制造出来的，施以用于加于人的行为或援助，要说“给朋友制造麻烦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师对迟到的学生施以一只批评。", "corrected_sentence": "老师对迟到的学生施以一次批评。", "error_description": "量词错误：「只」多用于动物或成对的东西，「批评」应用「次」，「一只批评」应改为「一次批评」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练对队员施以两只训练。", "corrected_sentence": "教练对队员施以两次训练。", "error_description": "错误：「训练」作动作量词应用「次」，「只」用于动物或成对的东西，不能用于「训练」。正确：应写作「教练对队员施以两次训练」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "反义：“奖励”与“处罚”意思相反，一个给予好处，一个给予惩罚。"}, {"text": "照顾", "is_correct": false, "explanation": "无反义关系：“照顾”是关心、护理，与“处罚”不构成反义。"}, {"text": "检查", "is_correct": false, "explanation": "无反义关系：“检查”是查看核实，与“处罚”不是对立关系。"}, {"text": "参观", "is_correct": false, "explanation": "无反义关系：“参观”是观看、访问，与“处罚”不构成反义。"}], "correct_answer": "奖励", "explanations": {"奖励": "反义：“奖励”与“处罚”意思相反，一个给予好处，一个给予惩罚。", "照顾": "无反义关系：“照顾”是关心、护理，与“处罚”不构成反义。", "检查": "无反义关系：“检查”是查看核实，与“处罚”不是对立关系。", "参观": "无反义关系：“参观”是观看、访问，与“处罚”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "反义：“奖励”与“处罚”意思相反，一个给予好处，一个给予惩罚。"}, {"text": "帮助", "is_correct": false, "explanation": "无反义关系：“帮助”是给予支持，与“处罚”不对立。"}, {"text": "陪伴", "is_correct": false, "explanation": "无反义关系：“陪伴”是伴随相处，与“处罚”不构成反义。"}, {"text": "欢迎", "is_correct": false, "explanation": "无反义关系：“欢迎”是表示接纳的态度，与“处罚”不构成反义。"}], "correct_answer": "奖励", "explanations": {"奖励": "反义：“奖励”与“处罚”意思相反，一个给予好处，一个给予惩罚。", "帮助": "无反义关系：“帮助”是给予支持，与“处罚”不对立。", "陪伴": "无反义关系：“陪伴”是伴随相处，与“处罚”不构成反义。", "欢迎": "无反义关系：“欢迎”是表示接纳的态度，与“处罚”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对违反法律或规则的人给予惩罚。", "primary_collocate": null, "pronunciation": "chǔ fá", "ipa": "tʂʰu˨˩˦ fa˧˥", "syllable_count": 2, "sentences": [{"text": "老师处罚了迟到的学生。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会处罚违反规定的员工。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察处罚了乱停车的司机。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车打电话，交警要处罚你。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校不会处罚说真话的孩子。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他违反了交通规则，警察处罚过他。", "target_word": "处罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店卖过期食品，政府应该处罚它。", "target_word": "处罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判处罚了故意犯规的球员。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律怎么处罚随地扔垃圾的人？", "target_word": "处罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按规定处罚了打架的学生。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "处罚了", "label": "体标"}, {"form": "处罚过", "label": "体标"}, {"form": "行政处罚", "label": "复合"}, {"form": "處罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对违反法律或规则的人给予惩罚（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），指对违反法律或规则的人给予惩罚。"}, {"text": "出发", "is_correct": false, "explanation": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。"}, {"text": "除法", "is_correct": false, "explanation": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。"}, {"text": "触法", "is_correct": false, "explanation": "chù fǎ（触法）与 chǔ fá 两个音节的声调都不同，意思是触犯法律。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），指对违反法律或规则的人给予惩罚。", "出发": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。", "除法": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。", "触法": "chù fǎ（触法）与 chǔ fá 两个音节的声调都不同，意思是触犯法律。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指对迟到这类违规行为给予惩罚，与句意相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“迟到”这种过错相矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后面接活动或集体，不能直接接“学生”这样的人。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是为好事道喜，不能用于迟到的学生。"}], "explanations": {"处罚": "正确：“处罚”指对迟到这类违规行为给予惩罚，与句意相符。", "表扬": "语义：“表扬”是称赞，与“迟到”这种过错相矛盾。", "参加": "搭配：“参加”后面接活动或集体，不能直接接“学生”这样的人。", "祝贺": "语义：“祝贺”是为好事道喜，不能用于迟到的学生。"}, "sentence_index": 0, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他处罚了那座旧房子。", "explanation": "这里应该用〈拆除〉。“处罚”针对违规的人，不能用于房子，这句要说“拆除了那座旧房子”。"}, {"text": "这件事由经理处罚。", "explanation": "这里应该用〈处理〉。“处罚”的对象是违规的人，不能用来指一件事。"}, {"text": "老师处罚了我的作文。", "explanation": "这里应该用〈批评〉。“处罚”针对违规的人，作文不能成为处罚的对象，这里应说批评作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），指对违反法律或规则的人给予惩罚。"}, {"text": "触发", "is_correct": false, "explanation": "chù fā（触发）与 chǔ fá 两个音节的声调都不同，意思是引起、引发。"}, {"text": "出发", "is_correct": false, "explanation": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。"}, {"text": "厨房", "is_correct": false, "explanation": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。"}, {"text": "处方", "is_correct": false, "explanation": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），指对违反法律或规则的人给予惩罚。", "触发": "chù fā（触发）与 chǔ fá 两个音节的声调都不同，意思是引起、引发。", "出发": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。", "厨房": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。", "处方": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指对卖过期食品这种违规行为给予惩罚，与“应该”的判断相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示接纳和喜爱，与商店卖过期食品的过错相反。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”表示同意，与“政府应该”的处理判断相矛盾。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”用于子女或家人，不能用于商店。"}], "explanations": {"处罚": "正确：“处罚”指对卖过期食品这种违规行为给予惩罚，与“应该”的判断相符。", "欢迎": "语义：“欢迎”表示接纳和喜爱，与商店卖过期食品的过错相反。", "批准": "语义：“批准”表示同意，与“政府应该”的处理判断相矛盾。", "抚养": "搭配：“抚养”用于子女或家人，不能用于商店。"}, "sentence_index": 6, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真学习，成绩很好，老师处罚了他。", "explanation": "这里应该用〈表扬〉。“处罚”是给予惩罚，用于违规的人；学习认真、成绩好应该受到表扬，不能用“处罚”。"}, {"text": "消防员处罚了被困的人。", "explanation": "这里应该用〈救助〉。“处罚”只针对违规的人，被困的人没有违规，不能用“处罚”。"}, {"text": "这件事要处罚责任。", "explanation": "这里应该用〈追究〉。“处罚”是对人的制裁，“责任”不能被处罚，应说“追究责任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校处罚地很严厉。", "corrected_sentence": "学校处罚得很严厉。", "error_description": "错误：程度补语的标记用了“地”，应为“得”。“地”用于状语，“处罚”后接补语“很严厉”要用“得”。正确应为“处罚得很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们按章程处罚地那名学生。", "corrected_sentence": "他们按章程处罚了那名学生。", "error_description": "错误：动词“处罚”后的体标应为“了”，却用了结构助词“地”。正确应为“按章程处罚了那名学生”，“了”紧跟动词，表示动作完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "反义：“放任”指任其自由、不加限制，与“约束”（限制）相对。"}, {"text": "参观", "is_correct": false, "explanation": "无反义关系：“参观”是到某地观看，与“约束”不对立。"}, {"text": "陪伴", "is_correct": false, "explanation": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。"}, {"text": "欢迎", "is_correct": false, "explanation": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}], "correct_answer": "放任", "explanations": {"放任": "反义：“放任”指任其自由、不加限制，与“约束”（限制）相对。", "参观": "无反义关系：“参观”是到某地观看，与“约束”不对立。", "陪伴": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。", "欢迎": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "反义：“放任”指任其自由、不加限制，与“约束”（限制）相对。"}, {"text": "帮助", "is_correct": false, "explanation": "无反义关系：“帮助”是给予支持，与“约束”不对立。"}, {"text": "尊重", "is_correct": false, "explanation": "无反义关系：“尊重”是敬重，与“约束”不构成反义。"}, {"text": "表扬", "is_correct": false, "explanation": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}], "correct_answer": "放任", "explanations": {"放任": "反义：“放任”指任其自由、不加限制，与“约束”（限制）相对。", "帮助": "无反义关系：“帮助”是给予支持，与“约束”不对立。", "尊重": "无反义关系：“尊重”是敬重，与“约束”不构成反义。", "表扬": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过规定、条件等加以限制或束缚，使人不超出范围。", "primary_collocate": null, "pronunciation": "yuē shù", "ipa": "ɥe˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "法律约束每一个人。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司的规定约束着员工的行为。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要规则来约束。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这份合同约束双方。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "校规约束不了他。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网络也需要规定来约束。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些条件约束了我们的选择。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家用法律约束政府的权力。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小区规定约束居民养狗的数量。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有规则约束，比赛会很乱。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "约束了", "label": "体标"}, {"form": "约束着", "label": "体标"}, {"form": "约束力", "label": "复合"}, {"form": "約束", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用规定、条件限制人，使其不超出范围（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指通过规定限制人，使其不超出范围，与句意相符。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指对不起别人的期望，用在法律上不合句意。"}, {"text": "收养", "is_correct": false, "explanation": "搭配：“收养”用于收留孩子或动物，不能用于“每一个人”。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，不能用来说法律的作用，与句意不符。"}], "explanations": {"约束": "正确：“约束”指通过规定限制人，使其不超出范围，与句意相符。", "辜负": "语义：“辜负”指对不起别人的期望，用在法律上不合句意。", "收养": "搭配：“收养”用于收留孩子或动物，不能用于“每一个人”。", "赞美": "语义：“赞美”是称赞，不能用来说法律的作用，与句意不符。"}, "sentence_index": 0, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同约束了双方的成绩。", "explanation": "这里应该用〈评定〉。“约束”是限制人的行为或范围，不能用于成绩；这里的意思是评定双方的成绩。"}, {"text": "大家约束了胜利。", "explanation": "这里应该用〈庆祝〉。“约束”用于限制行为，不能用来指对胜利表示喜悦。"}, {"text": "孩子们约束了一首歌。", "explanation": "这里应该用〈唱〉。“约束”是限制人的行为或范围，不能用于歌曲，这句要说“唱了一首歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指用条件限制，使其不超出范围，与“这些条件”的主语相符。"}, {"text": "实现", "is_correct": false, "explanation": "搭配：“实现”接的是愿望、目标，与“选择”搭配不当。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”是表达美好的祝愿，条件不能去祝福选择。"}, {"text": "通知", "is_correct": false, "explanation": "语义：“通知”是告知信息，条件不能用来通知选择。"}], "explanations": {"约束": "正确：“约束”指用条件限制，使其不超出范围，与“这些条件”的主语相符。", "实现": "搭配：“实现”接的是愿望、目标，与“选择”搭配不当。", "祝福": "语义：“祝福”是表达美好的祝愿，条件不能去祝福选择。", "通知": "语义：“通知”是告知信息，条件不能用来通知选择。"}, "sentence_index": 6, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈约束了一锅汤。", "explanation": "这里应该用〈熬〉。“约束”是限制人的行为或范围，不能用于烹煮食物；这句的意思是熬了一锅汤。"}, {"text": "春天约束了这座城市。", "explanation": "这里应该用〈装扮〉。“约束”是限制人的行为或范围，不能用于装饰城市；春天装扮城市应说“装扮”。"}, {"text": "学校约束了那堆旧书。", "explanation": "这里应该用〈整理〉。“约束”是限制人的行为或范围，不能用于整理书籍；这句要说“整理那堆旧书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "规则约束地每位选手的行为。", "corrected_sentence": "规则约束着每位选手的行为。", "error_description": "错误：动词“约束”后应接体标“着”，却用了结构助词“地”。正确应为“约束着每位选手的行为”，“着”紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同约束地很严格。", "corrected_sentence": "这份合同约束得很严格。", "error_description": "错误：程度补语的标记用了“地”，应为“得”。“约束”后接“很严格”作补语时要用“得”，“地”只用于状语。正确应为“约束得很严格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指选择或决定的方向、倾向。", "primary_collocate": null, "pronunciation": "qǔ xiàng", "ipa": "tɕʰy˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，非洲大陆已有十余国实施不同程度的塑料袋禁令，部分国家甚至对违规生产或进口行为施以刑事处罚，反映出环境政策在资源约束型社会中的刚性取向。", "target_word": "取向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现在年轻人的消费取向变了。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人的取向都不一样。", "target_word": "取向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的取向很明显，喜欢安静的工作。", "target_word": "取向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该了解学生的兴趣取向。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府的取向会影响市场。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的取向偏向年轻读者。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他选择工作时，更看重自己的价值取向。", "target_word": "取向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的取向不同，很难选出一部电影。", "target_word": "取向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从调查可以看出顾客的取向。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种取向", "label": "量词"}, {"form": "价值取向", "label": "复合"}, {"form": "消费取向", "label": "复合"}], "register": "中性", "sense_fingerprint": "选择或决定所倾向的方向（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数量", "is_correct": false, "explanation": "搭配：“刚性”修饰政策的约束力或方向，不能修饰“数量”，“刚性数量”不成立。"}, {"text": "取向", "is_correct": true, "explanation": "取向：指政策选择的倾向或方向，“刚性取向”即偏重强制约束的政策方向，句中正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与政策的约束性无关，放入句中读不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”只用于人，不能说政策的性格，句意不合理。"}], "explanations": {"数量": "搭配：“刚性”修饰政策的约束力或方向，不能修饰“数量”，“刚性数量”不成立。", "取向": "取向：指政策选择的倾向或方向，“刚性取向”即偏重强制约束的政策方向，句中正确。", "颜色": "语义：“颜色”指色彩，与政策的约束性无关，放入句中读不通。", "性格": "语义：“性格”只用于人，不能说政策的性格，句意不合理。"}, "sentence_index": 0, "correct_answer": "取向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的取向很好，南北通透，冬天也很暖和。", "explanation": "这里应该用〈朝向〉。取向指人对事物的选择或倾向，房屋朝向的方位要用〈朝向〉。"}, {"text": "这条路的取向很明显，不会走错。", "explanation": "这里应该用〈方向〉。取向指人的选择或倾向，道路延伸的方向要用〈方向〉。"}, {"text": "这座山的取向很明显，从东到西一眼就能看出来。", "explanation": "这里应该用〈走向〉。取向指人的选择或倾向，山脉的延伸方向要用〈走向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "页数", "is_correct": false, "explanation": "搭配：“偏向”用于倾向、立场，不能与“页数”搭配，“页数偏向”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，与书的读者定位无关，句子不通。"}, {"text": "取向", "is_correct": true, "explanation": "取向：指书籍内容或定位所倾向的对象，“取向偏向年轻读者”即定位面向年轻人，句中正确。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：“厚度”指厚薄，与读者对象无关，放入句中读不通。"}], "explanations": {"页数": "搭配：“偏向”用于倾向、立场，不能与“页数”搭配，“页数偏向”不成立。", "重量": "语义：“重量”指轻重，与书的读者定位无关，句子不通。", "取向": "取向：指书籍内容或定位所倾向的对象，“取向偏向年轻读者”即定位面向年轻人，句中正确。", "厚度": "语义：“厚度”指厚薄，与读者对象无关，放入句中读不通。"}, "sentence_index": 6, "correct_answer": "取向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的取向很大，能坐下二百人。", "explanation": "这里应该用〈规模〉。取向指选择或倾向的方向，不能表示场地大小，这句要说“规模很大”。"}, {"text": "他从小立下远大的取向，想成为科学家。", "explanation": "这里应该用〈志向〉。取向指选择或倾向，立下的远大理想和奋斗目标要用〈志向〉。"}, {"text": "这条河的取向很清楚，一路从北往南流。", "explanation": "这里应该用〈流向〉。取向指人的选择或倾向，河水的流动方向要用〈流向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的取向得很清楚，只买国产货。", "corrected_sentence": "她的取向很清楚，只买国产货。", "error_description": "助词错误：“得”是补语标记，只能接在动词或形容词后；“取向”是名词作主语，后面直接接“很清楚”，不能加“得”。正确说法是「她的取向很清楚」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一只新取向，越来越注重健康。", "corrected_sentence": "她有一种新取向，越来越注重健康。", "error_description": "量词错误：“取向”是抽象名词，应用量词“种”；“只”用于动物或成对事物中的一个，不能用于“取向”。正确说法是「一种新取向」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
