INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指北美洲的区域，主要包括美国和加拿大。", "primary_collocate": null, "pronunciation": "běi měi dì qū", "ipa": "pei˨˩˦ mei˨˩˦ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "反观北美地区，政策路径呈现联邦与地方分化的格局。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "北美地区冬天很冷，常常下大雪。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区有美国和加拿大两个大国。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去北美地区工作几年。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区的人大多说英语。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在北美地区卖得很好。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北美地区住了十年。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区的秋天，树叶会变红。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年有很多学生去北美地区留学。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北美地区的城市，街道都很宽。", "target_word": "北美地区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北美地區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "北美洲这一地理区域，含美国、加拿大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北美地区", "is_correct": true, "explanation": "北美地区指北美洲的区域，主要包括美国、加拿大等联邦制国家，与“联邦与地方分化”的语境相符。"}, {"text": "北京市", "is_correct": false, "explanation": "语义：北京是中国的直辖市，不实行联邦制，放入句中与“联邦与地方分化”的语境不符。"}, {"text": "江南地区", "is_correct": false, "explanation": "语义：江南是中国南方的地理区域，没有联邦与地方分化的格局，放入句中句意不通。"}, {"text": "老家", "is_correct": false, "explanation": "语域：“老家”是口语，与“反观”“格局”等书面语不协调，也不指联邦制地区。"}], "explanations": {"北美地区": "北美地区指北美洲的区域，主要包括美国、加拿大等联邦制国家，与“联邦与地方分化”的语境相符。", "北京市": "语义：北京是中国的直辖市，不实行联邦制，放入句中与“联邦与地方分化”的语境不符。", "江南地区": "语义：江南是中国南方的地理区域，没有联邦与地方分化的格局，放入句中句意不通。", "老家": "语域：“老家”是口语，与“反观”“格局”等书面语不协调，也不指联邦制地区。"}, "sentence_index": 0, "correct_answer": "北美地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北美地区是世界上第三大洲。", "explanation": "这里应该用〈北美洲〉。“北美地区”是区域概念，不是大洲，说“第三大洲”要用“北美洲”。"}, {"text": "他是北美地区的总统。", "explanation": "这里应该用〈美国〉。北美地区包含多个国家，没有统一的总统，指一国元首要用“美国”。"}, {"text": "我家门口有一只北美地区。", "explanation": "量词用错：“只”多用于动物，不能用来计量“北美地区”这样的地理区域，应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北美地区", "is_correct": true, "explanation": "北美地区是一个可以居住的地理区域，“住了十年”需要地点，符合句意。"}, {"text": "北美人", "is_correct": false, "explanation": "语义：“北美人”指人，不能作“住”的处所，句意不通。"}, {"text": "北美天气", "is_correct": false, "explanation": "搭配：“住在”后要接地点，“天气”不能作居住的处所。"}, {"text": "北美语言", "is_correct": false, "explanation": "语义：“语言”不是地方，不能作“住了十年”的处所。"}], "explanations": {"北美地区": "北美地区是一个可以居住的地理区域，“住了十年”需要地点，符合句意。", "北美人": "语义：“北美人”指人，不能作“住”的处所，句意不通。", "北美天气": "搭配：“住在”后要接地点，“天气”不能作居住的处所。", "北美语言": "语义：“语言”不是地方，不能作“住了十年”的处所。"}, "sentence_index": 6, "correct_answer": "北美地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北美地区总理昨天访问了中国。", "explanation": "这里应该用〈加拿大〉。北美地区是地理区域，没有总理，“总理”属于国家。"}, {"text": "北美地区的首都很大，人口很多。", "explanation": "这里应该用〈墨西哥〉。北美地区没有首都，只有国家才有首都。"}, {"text": "北美地区的成员国很多。", "explanation": "这里应该用〈欧盟〉。北美地区是地理概念，不是组织，没有成员国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的产品在一北美地区很受欢迎。", "corrected_sentence": "这家公司的产品在北美地区很受欢迎。", "error_description": "数量词错误：「北美地区」前加了数词「一」却没有量词，应删去「一」。正确说法是「这家公司的产品在北美地区很受欢迎」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友北美地区生活了五年。", "corrected_sentence": "我的朋友在北美地区生活了五年。", "error_description": "缺少介词：“北美地区”作处所要用“在”引出，应说“我的朋友在北美地区生活了五年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
