INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指餐厅将做好的饭菜送到顾客指定地点的服务或食品。", "primary_collocate": null, "pronunciation": "wài mài", "ipa": "uai˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "周末懒得出门，就在手机上订个外卖吧。", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太累了，我不想做饭，点了一份外卖。", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外卖送来的时候，饭菜还热着。", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的外卖很好吃，价格也不贵。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，很多人在家里点外卖。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今天中午想点什么外卖？", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份外卖半小时就送到了。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上都叫外卖，很少自己做饭。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆也做外卖，不用在店里吃。", "target_word": "外卖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我吃过这家的外卖，味道很不错。", "target_word": "外卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "外卖员", "label": "复合"}, {"form": "外卖平台", "label": "复合"}], "register": "口语", "sense_fingerprint": "餐厅做好饭菜后送到顾客指定地点的服务或食品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外卖", "is_correct": true, "explanation": "外卖：餐厅送到顾客处的饭菜，作“订”的宾语，句意通顺。"}, {"text": "外汇", "is_correct": false, "explanation": "语义：“外汇”指货币兑换，不能被“订”，句意不通。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“婚礼”不是可在手机上订购的餐饮服务，句意不通。"}, {"text": "外语", "is_correct": false, "explanation": "语义：“外语”指语言，不能被“订”，句意不通。"}], "explanations": {"外卖": "外卖：餐厅送到顾客处的饭菜，作“订”的宾语，句意通顺。", "外汇": "语义：“外汇”指货币兑换，不能被“订”，句意不通。", "婚礼": "搭配：“婚礼”不是可在手机上订购的餐饮服务，句意不通。", "外语": "语义：“外语”指语言，不能被“订”，句意不通。"}, "sentence_index": 0, "correct_answer": "外卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今晚去外卖吃饭，环境很好。", "explanation": "这里应该用〈餐厅〉。外卖指送到家的饭菜，不是可以前往的地方，去吃饭要说餐厅。"}, {"text": "我点了一只外卖，很快就送来了。", "explanation": "这里应该用〈份〉。外卖按份计数，〈只〉用于动物或成对的东西。"}, {"text": "我在网上买的衣服，外卖已经送来了。", "explanation": "这里应该用〈快递〉。快递指寄来的包裹，外卖只指送到家的饭菜或送餐服务，不能指衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外卖", "is_correct": true, "explanation": "外卖：送到顾客处的饭菜，与“这份”和“送到”搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”无法被“送到”，句意不通。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“讲座”不能说“送到”，动词与对象搭配不当。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是抽象情感，无法“半小时就送到”。"}], "explanations": {"外卖": "外卖：送到顾客处的饭菜，与“这份”和“送到”搭配，句意通顺。", "天气": "语义：“天气”无法被“送到”，句意不通。", "讲座": "搭配：“讲座”不能说“送到”，动词与对象搭配不当。", "友谊": "语义：“友谊”是抽象情感，无法“半小时就送到”。"}, "sentence_index": 6, "correct_answer": "外卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本外卖教我做了三道家常菜。", "explanation": "这里应该用〈食谱〉。外卖指送到家的饭菜或服务，不是教人做菜的书。"}, {"text": "我请了一位外卖来家里做饭。", "explanation": "这里应该用〈厨师〉。外卖指饭菜或服务，不指人；送餐的人应说〈外卖员〉。"}, {"text": "这门外卖很有用，我学到了很多。", "explanation": "这里应该用〈课程〉。外卖不是可以学习的课程，它指送到家的饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我点了一条外卖，我们一起吃。", "corrected_sentence": "妈妈给我点了一份外卖，我们一起吃。", "error_description": "量词错误：“外卖”按份计数，应说“一份外卖”，“条”用于长条形的东西，不能说“一条外卖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前吃过很多张外卖，都很方便。", "corrected_sentence": "我以前吃过很多份外卖，都很方便。", "error_description": "量词错误：“外卖”按份计数，应说“很多份外卖”，“张”用于纸张、票据等扁平的东西，不能说“很多张外卖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自上而下", "is_correct": true, "explanation": "自上而下：从高层往低层推进，与“自下而上”的顺序方向相反，是本义的反义词。"}, {"text": "迅速", "is_correct": false, "explanation": "与“自下而上”无反义关系，“迅速”指速度快。"}, {"text": "复杂", "is_correct": false, "explanation": "与“自下而上”无反义关系，“复杂”指事物繁多或不简单。"}, {"text": "温和", "is_correct": false, "explanation": "与“自下而上”无反义关系，“温和”指性情或力度平和。"}], "correct_answer": "自上而下", "explanations": {"自上而下": "自上而下：从高层往低层推进，与“自下而上”的顺序方向相反，是本义的反义词。", "迅速": "与“自下而上”无反义关系，“迅速”指速度快。", "复杂": "与“自下而上”无反义关系，“复杂”指事物繁多或不简单。", "温和": "与“自下而上”无反义关系，“温和”指性情或力度平和。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自上而下", "is_correct": true, "explanation": "自上而下：从高层往低层推进，与“自下而上”的顺序方向相反，是本义的反义词。"}, {"text": "艰难", "is_correct": false, "explanation": "与“自下而上”无反义关系，“艰难”指困难。"}, {"text": "清晰", "is_correct": false, "explanation": "与“自下而上”无反义关系，“清晰”指明白、不模糊。"}, {"text": "悠闲", "is_correct": false, "explanation": "与“自下而上”无反义关系，“悠闲”指从容不迫。"}], "correct_answer": "自上而下", "explanations": {"自上而下": "自上而下：从高层往低层推进，与“自下而上”的顺序方向相反，是本义的反义词。", "艰难": "与“自下而上”无反义关系，“艰难”指困难。", "清晰": "与“自下而上”无反义关系，“清晰”指明白、不模糊。", "悠闲": "与“自下而上”无反义关系，“悠闲”指从容不迫。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从下面向上面；指一种从低层到高层的顺序或发展方式。", "primary_collocate": null, "pronunciation": "zì xià ér shàng", "ipa": "tsɹ̩˥˩ ɕia˥˩ ɚ˧˥ ʂɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种自下而上的监管创新虽推动局部减排，却导致法规碎片化与跨区域执法难题。", "target_word": "自下而上", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的改革是自下而上进行的。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的想法常常自下而上地传到领导那里。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用自下而上的办法收集老师的意见。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划是自下而上制定的，先问员工。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自下而上的管理方式让员工更有参与感。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目是自下而上发展起来的。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民自下而上提出了新的办法。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种自下而上的做法很受欢迎。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们自下而上地讨论，先小组，再全班。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "从低层到高层逐级推进的顺序或发展方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自下而上", "is_correct": true, "explanation": "自下而上：从低层逐级向上推进，修饰“监管创新”，句意通顺。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的风趣，不能修饰“监管创新”。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容人的态度，与“监管创新”不相容。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的情感态度，与“监管创新”搭配不当。"}], "explanations": {"自下而上": "自下而上：从低层逐级向上推进，修饰“监管创新”，句意通顺。", "幽默": "语义：“幽默”形容人的风趣，不能修饰“监管创新”。", "冷淡": "语义：“冷淡”形容人的态度，与“监管创新”不相容。", "热情": "搭配：“热情”形容人的情感态度，与“监管创新”搭配不当。"}, "sentence_index": 0, "correct_answer": "自下而上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们自下而上地排队进场，秩序很好。", "explanation": "这里应该用〈依次〉。依次说先后顺序，“自下而上”强调从低层到高层的层级推进，不用于排队进场。"}, {"text": "领导自下而上地布置工作，员工很不习惯。", "explanation": "这里应该用〈自上而下〉。布置工作是上级向下级下达，与“自下而上”从低层到高层的方向相反。"}, {"text": "老板自下而上地决定裁员，大家都很意外。", "explanation": "这里应该用〈自上而下〉。裁员由管理层作出并向下宣布，与“自下而上”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自下而上", "is_correct": true, "explanation": "自下而上：从基层逐级发展，修饰“发展起来”，句意通顺。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容人的大方，不能修饰“发展”。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：“亲切”形容人的态度，与“发展起来”搭配不当。"}, {"text": "豪迈", "is_correct": false, "explanation": "语义：“豪迈”形容人的气概，无法修饰项目的发展。"}], "explanations": {"自下而上": "自下而上：从基层逐级发展，修饰“发展起来”，句意通顺。", "慷慨": "语义：“慷慨”形容人的大方，不能修饰“发展”。", "亲切": "搭配：“亲切”形容人的态度，与“发展起来”搭配不当。", "豪迈": "语义：“豪迈”形容人的气概，无法修饰项目的发展。"}, "sentence_index": 6, "correct_answer": "自下而上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长自下而上地宣布了新的校规。", "explanation": "这里应该用〈自上而下〉。宣布校规是由上往下传达，与“自下而上”的方向相反。"}, {"text": "我们的复习是自下而上进行的，先复习难题，再复习基础。", "explanation": "这里应该用〈自上而下〉。先复习难题、再复习基础，是从高层往低层的次序，与“自下而上”方向相反。"}, {"text": "这份通知是自下而上一级一级传到基层的。", "explanation": "这里应该用〈自上而下〉。一级级传到基层是由上往下，与“自下而上”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项规划自下而上的征求了意见。", "corrected_sentence": "这项规划自下而上地征求了意见。", "error_description": "助词错误：“自下而上”修饰动词“征求”作状语，应用“地”。用“的”会变成定语，后接“了”则不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区的活动自下而上的组织了。", "corrected_sentence": "这个社区的活动自下而上地组织了。", "error_description": "助词错误：“自下而上”修饰动词“组织”作状语，应用“地”。用“的”后接“组织了”，成了名词性短语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
