INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体破裂后形成的小块或小片。", "primary_collocate": null, "pronunciation": "suì piàn", "ipa": "suei˥˩ pʰiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "孩子不小心踩到了地上的一块碎片，脚被扎破了。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有很多玻璃碎片，请小心。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子把杯子摔成了碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手捡起地上的碎片。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打碎的花瓶变成了许多碎片。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块碎片很锋利，别用手摸。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把碎片扫进了垃圾桶。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一些古代陶器的碎片。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机掉下来，到处都是碎片。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这些碎片放在盒子里。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "玻璃碎片", "label": "复合"}, {"form": "碎片化", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体破裂后形成的小块或小片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "碎片：物体破裂后形成的小块，作“踩到”的宾语，句意通顺。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：“色彩”指颜色，不是可以踩到的实物，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“花朵”的量词是“朵”，不能说“一块花朵”，句意不通。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“电线”的量词是“根”，不能说“一块电线”，句意不通。"}], "explanations": {"碎片": "碎片：物体破裂后形成的小块，作“踩到”的宾语，句意通顺。", "色彩": "语义：“色彩”指颜色，不是可以踩到的实物，句意不通。", "花朵": "搭配：“花朵”的量词是“朵”，不能说“一块花朵”，句意不通。", "电线": "搭配：“电线”的量词是“根”，不能说“一块电线”，句意不通。"}, "sentence_index": 0, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玻璃摔碎后，地上留下了一只碎片。", "explanation": "量词误用：「只」指动物或成对的东西，与碎片这种小块不搭，这里应该用〈块〉。"}, {"text": "这包药已经磨成了细细的碎片，撒在饭上很方便。", "explanation": "近义词误用：这里应该用〈粉末〉。碎片指破裂后的小块或小片，磨成细末的东西要说「粉末」。"}, {"text": "蒲公英的碎片飘满了草地，一阵风吹过就散开了。", "explanation": "近义词误用：这里应该用〈绒毛〉。碎片指破裂后的硬小块，蒲公英轻软的绒毛不能说成碎片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "正确。碎片是破裂后的小块，可以用扫帚扫进垃圾桶。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能用扫帚扫进垃圾桶，句子读不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「扫」与「钢琴」不搭配，钢琴体积太大，不能扫进垃圾桶。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水是连续的液体，不能用扫帚扫进垃圾桶，句子不成立。"}], "explanations": {"碎片": "正确。碎片是破裂后的小块，可以用扫帚扫进垃圾桶。", "空气": "语义：空气是无形的气体，不能用扫帚扫进垃圾桶，句子读不通。", "钢琴": "搭配：「扫」与「钢琴」不搭配，钢琴体积太大，不能扫进垃圾桶。", "河水": "语义：河水是连续的液体，不能用扫帚扫进垃圾桶，句子不成立。"}, "sentence_index": 6, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个完好的花瓶没有摔坏，人们却把它叫作碎片。", "explanation": "这里应该用〈花瓶〉。碎片指破裂后的小块，完好无损的花瓶不能称为碎片。"}, {"text": "天空中飘着许多碎片，像下雪一样。", "explanation": "这里应该用〈雪花〉。碎片指破裂的小块，雪花不是破碎之物，不能称为碎片。"}, {"text": "妈妈把面团揉成了一块碎片，准备包饺子。", "explanation": "这里应该用〈面团〉。碎片是破裂后的小块，揉好的面团不是碎片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在厨房地上捡到一只玻璃碎片。", "corrected_sentence": "我在厨房地上捡到一块玻璃碎片。", "error_description": "量词误用：「只」用于动物或成对的东西，「碎片」的量词应为「块」或「片」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把很多只玻璃碎片扫走了。", "corrected_sentence": "工人把很多块玻璃碎片扫走了。", "error_description": "量词误用：“只”用于动物或成对的东西，不能计量“碎片”，应说“一块碎片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
