INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13258, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物一步步向前发展或变化的，不是突然发生的。", "primary_collocate": null, "pronunciation": "jiàn jìn", "ipa": "tɕjɛn˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "然而，此类地方实践常成为后续全国性立法的试验模板，体现政策演化的渐进逻辑。", "target_word": "渐进", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种变化是渐进的，不是一下子发生的。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习外语是一个渐进的过程，不能着急。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司选择了渐进的改革方式，一步一步来。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，经济要渐进地恢复，不能太快。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病情有了渐进的好转，医生很放心。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想用渐进的办法，慢慢改变旧规定。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渐进的调整比突然的改变更容易让人接受。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用渐进的方法教孩子，先学字，再学句子。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格上涨是渐进的，每个月只高一点点。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "渐进式", "label": "复合"}, {"form": "渐进性", "label": "复合"}, {"form": "漸進", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物发展或变化一步步推进的（渐进的过程、渐进的改革）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01edaae3-9fb1-4797-a818-53b09db41e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13258, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进（jiàn jìn）：一步步向前发展或变化，是正确答案。"}, {"text": "监禁", "is_correct": false, "explanation": "监禁（jiān jìn）第一个音节为第一声，与渐进的 jiàn（第四声）声调不同，意思是关押。"}, {"text": "坚劲", "is_correct": false, "explanation": "坚劲（jiān jìn）：笔力或力量刚健有力，第一声，与渐进的 jiàn（第四声）声调不同，意义也不同。"}, {"text": "坚禁", "is_correct": false, "explanation": "坚禁（jiān jìn）：坚决禁止，第一声，与渐进的 jiàn（第四声）声调不同。"}], "explanations": {"渐进": "渐进（jiàn jìn）：一步步向前发展或变化，是正确答案。", "监禁": "监禁（jiān jìn）第一个音节为第一声，与渐进的 jiàn（第四声）声调不同，意思是关押。", "坚劲": "坚劲（jiān jìn）：笔力或力量刚健有力，第一声，与渐进的 jiàn（第四声）声调不同，意义也不同。", "坚禁": "坚禁（jiān jìn）：坚决禁止，第一声，与渐进的 jiàn（第四声）声调不同。"}, "sentence_index": null, "correct_answer": "渐进"}, "level_3": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进：修饰“逻辑”，指一步步推进的逻辑，与“政策演化”相合，句意正确。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“政策演化”的意思相反，句意矛盾。"}, {"text": "急速", "is_correct": false, "explanation": "语义：“急速”与“渐进”的意思相反，与“政策演化”的逐步过程不合。"}, {"text": "美观", "is_correct": false, "explanation": "搭配：“美观”说外形，不能修饰“逻辑”。"}], "explanations": {"渐进": "渐进：修饰“逻辑”，指一步步推进的逻辑，与“政策演化”相合，句意正确。", "静止": "语义：“静止”与“政策演化”的意思相反，句意矛盾。", "急速": "语义：“急速”与“渐进”的意思相反，与“政策演化”的逐步过程不合。", "美观": "搭配：“美观”说外形，不能修饰“逻辑”。"}, "sentence_index": 0, "correct_answer": "渐进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一场渐进的爆炸让大家都吓了一跳。", "explanation": "这里应该用〈突然〉。渐进指一点一点地变化，爆炸是一下子发生的，不能用“渐进的”修饰。"}, {"text": "一声渐进的枪响，把大家都吓醒了。", "explanation": "这里应该用〈突然〉。枪响是瞬间发生的，不能用“渐进的”来描述。"}, {"text": "他眼前一道渐进的闪光，吓得他闭上了眼睛。", "explanation": "这里应该用〈忽然〉。闪光是瞬间出现的，不能说“渐进的闪光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进：修饰“办法”，指一步步推进的办法，与“慢慢改变”搭配，句意正确。"}, {"text": "激烈", "is_correct": false, "explanation": "语义：“激烈”与“慢慢改变”的节奏相反，句意矛盾。"}, {"text": "高昂", "is_correct": false, "explanation": "搭配：“高昂”说价格或代价，不能修饰“办法”。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”与“慢慢改变”的节奏相反，句意矛盾。"}], "explanations": {"渐进": "渐进：修饰“办法”，指一步步推进的办法，与“慢慢改变”搭配，句意正确。", "激烈": "语义：“激烈”与“慢慢改变”的节奏相反，句意矛盾。", "高昂": "搭配：“高昂”说价格或代价，不能修饰“办法”。", "粗暴": "语义：“粗暴”与“慢慢改变”的节奏相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "渐进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挨了一个渐进的耳光。", "explanation": "这里应该用〈一记〉。渐进指一步步地变化，耳光是瞬间挨上的，不能说“渐进的耳光”。"}, {"text": "一道渐进的闪电划过夜空。", "explanation": "这里应该用〈一闪〉。渐进指逐步变化，闪电是瞬间的，不能说“渐进的闪电”。"}, {"text": "他一个渐进的箭步跳过了那道墙。", "explanation": "这里应该用〈一跃〉。渐进指逐步变化，跳过墙是一下子完成的，不能用“渐进的箭步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们渐进的改变了生活习惯。", "corrected_sentence": "他们渐进地改变了生活习惯。", "error_description": "的地用错：“渐进”修饰动词“改变”，作状语要用“地”，应说“渐进地改变”，用“的”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种变化是渐进地，我们很难察觉。", "corrected_sentence": "这种变化是渐进的，我们很难察觉。", "error_description": "的地用错：作谓语时要用“的”，“是渐进地”不通，应说“是渐进的”，表示变化一步步发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
