INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个国家在国际社会中的整体印象和声誉。", "primary_collocate": null, "pronunciation": "guó jì xíng xiàng", "ipa": "kuo˧˥ tɕi˥˩ ɕiŋ˧˥ ɕiɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "国际形象", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "良好的国际形象有助于国家发展。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一直在努力提升国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次丑闻损害了政府的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境能够改善国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际形象关系到一个国家的声誉。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大型体育赛事是展示国际形象的机会。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部门要维护好国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望通过援助塑造积极的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际形象不好，投资者就会犹豫。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "國際形象", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个国家在国际社会中的整体印象和声誉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指国家在国际社会中的整体印象，与前文“国家治理能力”并列，句意通顺。"}, {"text": "国际象棋", "is_correct": false, "explanation": "语义：“国际象棋”是棋类游戏，不能作为“国家治理能力”的象征性场域，句意不通。"}, {"text": "国际航班", "is_correct": false, "explanation": "搭配：“象征性场域”不能与“航班”这类具体交通事物搭配。"}, {"text": "个人烦恼", "is_correct": false, "explanation": "语义：“个人烦恼”是个人的心理困扰，与“国家治理能力”这样的宏观概念并列不协调。"}], "explanations": {"国际形象": "“国际形象”指国家在国际社会中的整体印象，与前文“国家治理能力”并列，句意通顺。", "国际象棋": "语义：“国际象棋”是棋类游戏，不能作为“国家治理能力”的象征性场域，句意不通。", "国际航班": "搭配：“象征性场域”不能与“航班”这类具体交通事物搭配。", "个人烦恼": "语义：“个人烦恼”是个人的心理困扰，与“国家治理能力”这样的宏观概念并列不协调。"}, "sentence_index": 0, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国的国际形象越来越广泛。", "explanation": "这里应该用〈国际影响〉。“广泛”形容范围，形象一般不用“广泛”形容，应说“国际影响越来越广泛”。"}, {"text": "政府努力维护一座良好的国际形象。", "explanation": "这里应该用〈个〉。“形象”是抽象名词，计量用“个”，“座”用于山、桥、楼房等大型固定物。"}, {"text": "两国的国际形象一直很密切。", "explanation": "这里应该用〈国际关系〉。“密切”形容关系，不能用来形容形象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指别国人对一个国家的印象，“展示国际形象的机会”符合句意。"}, {"text": "国际汇率", "is_correct": false, "explanation": "搭配：“汇率”是金融数据，不能作为“展示”的机会内容，句意不通。"}, {"text": "国际身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不用于说国家的形象。"}, {"text": "国际口味", "is_correct": false, "explanation": "搭配：“展示”一般不与“口味”搭配，“展示国际口味”不通。"}], "explanations": {"国际形象": "“国际形象”指别国人对一个国家的印象，“展示国际形象的机会”符合句意。", "国际汇率": "搭配：“汇率”是金融数据，不能作为“展示”的机会内容，句意不通。", "国际身材": "体貌：“身材”指人的体型，不用于说国家的形象。", "国际口味": "搭配：“展示”一般不与“口味”搭配，“展示国际口味”不通。"}, "sentence_index": 6, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的国际形象十分动荡。", "explanation": "这里应该用〈国际局势〉。“动荡”形容局势、社会的不稳定，形象不会“动荡”。"}, {"text": "两国之间的国际形象非常激烈。", "explanation": "这里应该用〈国际争端〉。“激烈”形容争论、冲突，形象不说“激烈”。"}, {"text": "这个国家的国际形象越来越重。", "explanation": "这里应该用〈国际分量〉。“重”形容影响力、分量，形象不说“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛让这个国家的国际形像大大提升了。", "corrected_sentence": "这次比赛让这个国家的国际形象大大提升了。", "error_description": "错误：“形像”。正确：“形象”。“形象”的“象”不能写成“像”，应为“国际形象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该努力塑造一只良好的国际形象。", "corrected_sentence": "我们应该努力塑造一个良好的国际形象。", "error_description": "错误：“一只国际形象”。正确：“一个国际形象”。“形象”是抽象名词，用量词“个”；“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物具有代表、体现某种抽象意义或性质的特点。", "primary_collocate": null, "pronunciation": "xiàng zhēng xìng", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "象征性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "象征性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥具有很强的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸽的象征性大家都明白，它代表和平。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画最有象征性的地方是那棵树。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在婚礼上有特别的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗的象征性比它的价格重要得多。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕像的象征性很明显，它代表勇气。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，这个仪式的象征性很大。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙对中国人来说有很深的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "象征性的", "label": "复合"}, {"form": "象徵性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物代表某种抽象意义的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性”指事物代表抽象意义，“场域”在此指代表国家治理与国际形象的抽象含义，语义吻合。"}, {"text": "实用性", "is_correct": false, "explanation": "语义：“实用性”指有实际用处，与句中“代表国家治理能力与国际形象”的抽象意义不符。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：“季节性”指随季节变化，句中讲的是政策的抽象意义，与时令无关。"}, {"text": "时效性", "is_correct": false, "explanation": "搭配：“时效性”多修饰信息、政策的有效期，不修饰“场域”这类空间概念。"}], "explanations": {"象征性": "“象征性”指事物代表抽象意义，“场域”在此指代表国家治理与国际形象的抽象含义，语义吻合。", "实用性": "语义：“实用性”指有实际用处，与句中“代表国家治理能力与国际形象”的抽象意义不符。", "季节性": "语义：“季节性”指随季节变化，句中讲的是政策的抽象意义，与时令无关。", "时效性": "搭配：“时效性”多修饰信息、政策的有效期，不修饰“场域”这类空间概念。"}, "sentence_index": 0, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次选出的样本很有象征性，能反映整个城市的情况。", "explanation": "这里应该用〈代表性〉。“象征性”指代表抽象意义，“反映整体情况”要用“代表性”。"}, {"text": "这种农具的象征性很强，农民都愿意买。", "explanation": "这里应该用〈实用性〉。“象征性”指代表抽象意义，农具好不好用要看实用性，不能这样用。"}, {"text": "这台仪器的象征性很高，测量结果非常可靠。", "explanation": "这里应该用〈精确性〉。仪器的好坏看精确程度，“象征性”说的是代表意义，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性”作主语中心语，说国旗代表的抽象意义，与句意“比价格重要”相符。"}, {"text": "放射性", "is_correct": false, "explanation": "语义：“放射性”指物质释放射线的性质，与国旗无关。"}, {"text": "精密性", "is_correct": false, "explanation": "语义：“精密性”指测量或制造的精确程度，不能用来衡量国旗的象征意义。"}, {"text": "流动性", "is_correct": false, "explanation": "搭配：“流动性”多用于资金、人口，不修饰国旗这类物件。"}], "explanations": {"象征性": "“象征性”作主语中心语，说国旗代表的抽象意义，与句意“比价格重要”相符。", "放射性": "语义：“放射性”指物质释放射线的性质，与国旗无关。", "精密性": "语义：“精密性”指测量或制造的精确程度，不能用来衡量国旗的象征意义。", "流动性": "搭配：“流动性”多用于资金、人口，不修饰国旗这类物件。"}, "sentence_index": 6, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种车的象征性很好，油耗很低。", "explanation": "这里应该用〈经济性〉。“象征性”指代表抽象意义，油耗低说明的是经济性，不能这样用。"}, {"text": "这款软件的象征性很强，很少出问题。", "explanation": "这里应该用〈稳定性〉。“象征性”指代表抽象意义，软件很少出问题说明的是稳定性，不能这样用。"}, {"text": "这块布料的象征性很好，穿很久都不坏。", "explanation": "这里应该用〈耐用性〉。“象征性”指代表抽象意义，穿很久不坏说明的是耐用性，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座塔地象征性很强，代表着城市的历史。", "corrected_sentence": "这座塔的象征性很强，代表着城市的历史。", "error_description": "错误：结构助词用错。“这座塔”作定语修饰“象征性”，中间应用“的”，应说“这座塔的象征性很强”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这面旗帜的象征性地很强，代表着民族的团结。", "corrected_sentence": "这面旗帜的象征性很强，代表着民族的团结。", "error_description": "“地”错误：此处“象征性”是名词，作“的”字短语的中心语，后面不能加“地”（“象征性地”只作状语修饰动词，如“象征性地抗议”）。应去掉“地”，为“这面旗帜的象征性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
