INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13261, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向公众强烈表达某种要求或主张。", "primary_collocate": null, "pronunciation": "hū yù", "ipa": "xu˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "呼吁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家呼吁大家少用一次性塑料袋。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长呼吁市民在节日期间注意安全。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生呼吁大家养成洗手的习惯。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多学者呼吁政府加强对环境的保护。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红十字会呼吁社会各界为灾区捐款。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长曾多次呼吁家长关心孩子的心理健康。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上呼吁各国共同应对气候变化。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就呼吁过提高教师的工资。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方呼吁司机不要酒后开车。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吁了", "label": "完成体"}, {"form": "呼吁过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "向公众强烈表达要求或主张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吁", "is_correct": true, "explanation": "语境正确：“呼吁”表示向各方提出强烈主张，与“多次……缔结协议”相合。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”与后文“旨在建立跨国监管协调机制”的目的相反，句子读起来不通。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”与后文“遏制塑料污染”的目的相反，多次阻止缔结协议不符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“多次……缔结协议”的主动推动相反，也与“旨在建立监管机制”的目的矛盾。"}], "explanations": {"呼吁": "语境正确：“呼吁”表示向各方提出强烈主张，与“多次……缔结协议”相合。", "禁止": "语义：“禁止”与后文“旨在建立跨国监管协调机制”的目的相反，句子读起来不通。", "阻止": "语义：“阻止”与后文“遏制塑料污染”的目的相反，多次阻止缔结协议不符合语境。", "拒绝": "语义：“拒绝”与“多次……缔结协议”的主动推动相反，也与“旨在建立监管机制”的目的矛盾。"}, "sentence_index": 0, "correct_answer": "呼吁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他呼吁我马上还钱。", "explanation": "这里应该用〈催〉。呼吁是面向公众的号召，对某个人催促还款要用“催”。"}, {"text": "妈妈呼吁我早点睡觉。", "explanation": "这里应该用〈叮嘱〉。呼吁用于向公众或多数人发出号召，家长对孩子的嘱咐要用“叮嘱”。"}, {"text": "孩子在夜里呼吁妈妈。", "explanation": "这里应该用〈呼唤〉。呼吁的对象是公众或多数人，孩子在夜里叫妈妈要用“呼唤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吁", "is_correct": true, "explanation": "语境正确：“呼吁”表示恳切地劝请家长关注，与“关心孩子的心理健康”相合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与校长重视学生心理健康的语境相反，句子不符合常理。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”家长关心孩子，与后文的正面内容冲突，句子读起来不通。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”的宾语多指错误行为，“批评家长关心孩子”把正常的关心当作过错，语义不通。"}], "explanations": {"呼吁": "语境正确：“呼吁”表示恳切地劝请家长关注，与“关心孩子的心理健康”相合。", "嘲笑": "语义：“嘲笑”与校长重视学生心理健康的语境相反，句子不符合常理。", "责怪": "语义：“责怪”家长关心孩子，与后文的正面内容冲突，句子读起来不通。", "批评": "配价：“批评”的宾语多指错误行为，“批评家长关心孩子”把正常的关心当作过错，语义不通。"}, "sentence_index": 6, "correct_answer": "呼吁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我呼吁你不要离开我。", "explanation": "这里应该用〈恳求〉。呼吁面向公众，对某个人表达恳切的请求要用“恳求”。"}, {"text": "我呼吁你早点休息。", "explanation": "这里应该用〈劝〉。呼吁是向公众或多数人发出号召，对身边的一个人提出建议要用“劝”。"}, {"text": "队长呼吁队员向我敬礼。", "explanation": "这里应该用〈命令〉。呼吁是劝请和号召，没有强制意味；要求下级执行的指令应说“命令”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府向市民的呼吁节约用水。", "corrected_sentence": "政府向市民呼吁节约用水。", "error_description": "错误：“呼吁”前多加了“的”，“市民的呼吁”变成名词短语，后面的“节约用水”没有谓语。正确：应说“政府向市民呼吁节约用水”，“呼吁”直接作动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长呼吁给司机遵守交通规则。", "corrected_sentence": "市长呼吁司机遵守交通规则。", "error_description": "错误：“呼吁”后直接带对象，对象前不能加“给”。正确：应说“市长呼吁司机遵守交通规则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
