INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由若干人组成的、负责处理特定事务或做出决策的集体组织。", "primary_collocate": null, "pronunciation": "wěi yuán huì", "ipa": "weɪ²¹⁴ ɥɛn³⁵ xweɪ⁵¹", "syllable_count": 3, "sentences": [{"text": "委员会今天开会，讨论明年的预算。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该委员会负责审核这个项目的安全标准。", "target_word": "委员会", "complexity_tier": "T3", "furigana": "gāi wěi yuán huì fù zé shěn hé zhè ge xiàng mù de ān quán biāo zhǔn", "sentence_source": "generated"}, {"text": "这个委员会由九位专家组成。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会一致同意了这个计划。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府成立了一个新的委员会。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选她当委员会的主席。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会没有通过这份报告。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会下个月将公布调查结果。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的委员会每年开两次会。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要先交给委员会讨论。", "target_word": "委员会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个委员会", "label": "量词（个）"}, {"form": "教育委员会", "label": "复合词"}, {"form": "委員會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "由若干成员组成、负责处理特定事务或决策的正式组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委员会", "is_correct": true, "explanation": "“开会”“讨论明年的预算”需要有决策职能的集体组织，“委员会”与语境相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能开会、讨论预算，与句中集体决策的语境不符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食品，没有决策能力，无法讨论明年的预算。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“公园”一般不作为开会、讨论预算的主体，与“讨论明年的预算”不搭。"}], "explanations": {"委员会": "“开会”“讨论明年的预算”需要有决策职能的集体组织，“委员会”与语境相符。", "小猫": "语义：小猫是动物，不能开会、讨论预算，与句中集体决策的语境不符。", "面包": "语义：面包是食品，没有决策能力，无法讨论明年的预算。", "公园": "搭配：“公园”一般不作为开会、讨论预算的主体，与“讨论明年的预算”不搭。"}, "sentence_index": 0, "correct_answer": "委员会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的排球委员会今天赢了比赛。", "explanation": "这里应该用〈球队〉。委员会是负责处理事务、做决定的组织，不参加比赛；参赛的集体应说〈球队〉。"}, {"text": "我每天早上都去委员会刷牙。", "explanation": "委员会是组织，不是场所，不能去那里刷牙；这里应说〈洗手间〉。"}, {"text": "我们委员会每天早上七点一起上课。", "explanation": "这里应该用〈班级〉。委员会是为处理事务、做决定而设的组织，不是每天一起上课的集体，上课的集体应说〈班级〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委员会", "is_correct": true, "explanation": "“没有通过这份报告”需要有决定权的机构作主语，“委员会”与语境相符。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，没有审议、表决的能力，不能“通过报告”。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“通过……报告”要求有决定权的主体，“铅笔”无法构成这一搭配。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能审议或批准报告，与语境不符。"}], "explanations": {"委员会": "“没有通过这份报告”需要有决定权的机构作主语，“委员会”与语境相符。", "香蕉": "语义：香蕉是水果，没有审议、表决的能力，不能“通过报告”。", "铅笔": "搭配：“通过……报告”要求有决定权的主体，“铅笔”无法构成这一搭配。", "太阳": "语义：太阳是天体，不能审议或批准报告，与语境不符。"}, "sentence_index": 6, "correct_answer": "委员会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班的委员会，每天准时参加活动。", "explanation": "这里应该用〈委员〉。委员会指集体组织，一个人应说“委员”。"}, {"text": "我想吃一个委员会。", "explanation": "委员会是组织，不是食物，不能吃；想吃东西应说〈点心〉。"}, {"text": "我们班的委员会今天生病了，请了假。", "explanation": "委员会是组织，不会生病，把它当成人来写是误用；这里应说〈某位成员〉生病了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只委员会由五个人组成，负责管理学校的食堂。", "corrected_sentence": "这个委员会由五个人组成，负责管理学校的食堂。", "error_description": "量词错误：“委员会”是组织，量词应用“个”，“只”用于动物等，应说“这个委员会”，不能说“这只委员会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个委员会们每个月开一次会。", "corrected_sentence": "这个委员会每个月开一次会。", "error_description": "复数标记误用：“委员会”指组织，不能加“们”，且与“这个”冲突，应说“这个委员会每个月开一次会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
