INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13275, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物由一个阶段逐渐发展而转入另一个阶段。", "primary_collocate": null, "pronunciation": "guò dù", "ipa": "kwo˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "该进程试图平衡各国差异，兼顾工业化国家的技术优势与发展中经济体的过渡需求，力图构建公平而有效的全球治理体系。", "target_word": "过渡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气从冬天慢慢过渡到春天。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子从幼儿园过渡到小学，需要时间。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司正在从旧系统过渡到新系统。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用了半年才从旧制度过渡到新制度。", "target_word": "过渡", "complexity_tier": "T3", "furigana": "tā men yòng le bàn nián cái cóng jiù zhì dù guò dù dào xīn zhì dù.", "sentence_source": "generated"}, {"text": "这座城市已经过渡到了新阶段。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天过去后，天气会过渡到夏天。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要帮助新生过渡到大学生活。", "target_word": "过渡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家从战争状态逐渐过渡到和平。", "target_word": "过渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队用一段轻音乐从快歌过渡到慢歌。", "target_word": "过渡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过渡了", "label": "完成体"}, {"form": "过渡期", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物从一个阶段逐步转入另一个阶段，常说“从……过渡到……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过渡", "is_correct": true, "explanation": "过渡：由一个阶段逐渐转入另一个阶段。此处修饰“需求”，指转型阶段的需要，与句意相合。"}, {"text": "垄断", "is_correct": false, "explanation": "搭配：“垄断”与“需求”不搭配，“发展中经济体的垄断需求”说不通。"}, {"text": "通缉", "is_correct": false, "explanation": "语义：“通缉”指通过公开追捕嫌疑人，与经济体的发展需求无关。"}, {"text": "隔离", "is_correct": false, "explanation": "搭配：“隔离”多用于人或病毒的分开，不能修饰“需求”，此处不合。"}], "explanations": {"过渡": "过渡：由一个阶段逐渐转入另一个阶段。此处修饰“需求”，指转型阶段的需要，与句意相合。", "垄断": "搭配：“垄断”与“需求”不搭配，“发展中经济体的垄断需求”说不通。", "通缉": "语义：“通缉”指通过公开追捕嫌疑人，与经济体的发展需求无关。", "隔离": "搭配：“隔离”多用于人或病毒的分开，不能修饰“需求”，此处不合。"}, "sentence_index": 0, "correct_answer": "过渡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔钱已经过渡到海外账户。", "explanation": "这里应该用〈转入〉。过渡指事物自身逐渐进入另一阶段，钱款转到账户要说“转入”。"}, {"text": "这批货物已经过渡到北京。", "explanation": "这里应该用〈转运〉。过渡指事物自身逐渐进入另一阶段，货物运送要说“转运”。"}, {"text": "这座城市的人口已经过渡到一千万。", "explanation": "这里应该用〈增长〉。过渡指事物由一个阶段转入另一个阶段，人口数量的增加要说“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过渡", "is_correct": true, "explanation": "过渡：逐渐从一个阶段转入另一个阶段，正合“春天过去后”的渐进变化。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”后接数量，不接季节，“天气会增加到夏天”说不通。"}, {"text": "蔓延", "is_correct": false, "explanation": "语义：“蔓延”指坏的事物扩散开来，不用于季节的更替。"}, {"text": "攀升", "is_correct": false, "explanation": "语义：“攀升”指数值或价格上升，不能用来描述季节的转换。"}], "explanations": {"过渡": "过渡：逐渐从一个阶段转入另一个阶段，正合“春天过去后”的渐进变化。", "增加": "搭配：“增加”后接数量，不接季节，“天气会增加到夏天”说不通。", "蔓延": "语义：“蔓延”指坏的事物扩散开来，不用于季节的更替。", "攀升": "语义：“攀升”指数值或价格上升，不能用来描述季节的转换。"}, "sentence_index": 6, "correct_answer": "过渡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视可以直接过渡到体育频道。", "explanation": "这里应该用〈切换〉。过渡强调逐渐进入另一阶段，换台是瞬间的位置变化，不能说“过渡”。"}, {"text": "这个细胞很快过渡成了两个。", "explanation": "这里应该用〈分裂〉。过渡指事物逐渐进入另一阶段，细胞一分为二要说“分裂”。"}, {"text": "油价过渡到了每桶一百美元。", "explanation": "这里应该用〈攀升〉。过渡强调逐渐转入另一种状态，油价数值的上升应说“攀升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小镇正从农业过渡服务业。", "corrected_sentence": "这座小镇正从农业过渡到服务业。", "error_description": "错误：“过渡”后漏掉了“到”。正确应为“过渡到……”，“到”引出转入的新阶段，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校正在从传统教学过渡到了项目式学习。", "corrected_sentence": "这所学校正在从传统教学过渡到项目式学习。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示完成的“了”同用。应删去“了”，说“正在从传统教学过渡到项目式学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
