INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指竭力谋求、争取。", "primary_collocate": null, "pronunciation": "lì tú", "ipa": "li˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "该进程试图平衡各国差异，兼顾工业化国家的技术优势与发展中经济体的过渡需求，力图构建公平而有效的全球治理体系。", "target_word": "力图", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司力图在明年打开国外市场。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他力图说服大家接受新计划。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府力图降低物价，让人民生活得更好。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队力图在下半场追平比分。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他力图掩盖自己的错误，却越说越乱。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家力图用简单的话讲清复杂的道理。", "target_word": "力图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校力图为学生提供更好的学习环境。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员力图找出问题的原因。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他力图保持冷静，但声音还是发抖。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "竭力谋求做成某事，后接动词短语，多用于书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力图", "is_correct": true, "explanation": "力图：竭力谋求，此处引出“构建……体系”这一目标。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与前文“试图平衡”及下文“构建”的意图正相反。"}, {"text": "阻挠", "is_correct": false, "explanation": "语义：“阻挠”与“构建公平而有效的体系”的目标相反，也与“试图平衡”冲突。"}, {"text": "瞎搞", "is_correct": false, "explanation": "语域：“瞎搞”是口语贬义词，与这句书面语的表述不协调。"}], "explanations": {"力图": "力图：竭力谋求，此处引出“构建……体系”这一目标。", "拒绝": "语义：“拒绝”与前文“试图平衡”及下文“构建”的意图正相反。", "阻挠": "语义：“阻挠”与“构建公平而有效的体系”的目标相反，也与“试图平衡”冲突。", "瞎搞": "语域：“瞎搞”是口语贬义词，与这句书面语的表述不协调。"}, "sentence_index": 0, "correct_answer": "力图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他力图觉得很累。", "explanation": "这里应该用〈感到〉。力图表示有意识地竭力去做，“觉得很累”是自然的感受，不能主动去力图。"}, {"text": "由于伤病，他力图退出了比赛。", "explanation": "这里应该用〈不得不〉。力图指主动竭力去做，而“退出比赛”是被伤病所迫，不能用“力图”。"}, {"text": "这台机器力图自己修好了故障。", "explanation": "这里应该用〈自行〉。力图表示有意识地竭力去做，机器没有意图；故障是自行恢复的，应说“自行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力图", "is_correct": true, "explanation": "力图：竭力想做，此处表示作家努力去做的事。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与“讲清”的目的正相反，两者不能连用。"}, {"text": "误导", "is_correct": false, "explanation": "语义：“误导”会让人产生错误认识，与“讲清复杂的道理”的目的相反。"}, {"text": "忽悠", "is_correct": false, "explanation": "语域：“忽悠”是口语，意为欺骗，与“讲清复杂的道理”冲突，也不适合书面语境。"}], "explanations": {"力图": "力图：竭力想做，此处表示作家努力去做的事。", "隐瞒": "语义：“隐瞒”与“讲清”的目的正相反，两者不能连用。", "误导": "语义：“误导”会让人产生错误认识，与“讲清复杂的道理”的目的相反。", "忽悠": "语域：“忽悠”是口语，意为欺骗，与“讲清复杂的道理”冲突，也不适合书面语境。"}, "sentence_index": 6, "correct_answer": "力图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他力图摔断了腿。", "explanation": "这里应该用〈不小心〉。力图表示主动竭力去做，摔断腿是意外，不能用“力图”。"}, {"text": "他力图每天都下雨。", "explanation": "这里应该用〈盼望〉。力图指主动竭力去做，天气不由人控制，只能说“盼望”。"}, {"text": "他力图一觉醒来就长高了。", "explanation": "这里应该用〈希望〉。力图指有意识地竭力去做，身高增长不能靠努力达到，只能说“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们力图了在明年把成本降下来。", "corrected_sentence": "我们力图在明年把成本降下来。", "error_description": "错误：“力图”后不能加“了”。正确应为“力图在明年……”，“力图”是动词，表示竭力去做，不带动态助词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院力图着为病人减少等待时间。", "corrected_sentence": "这家医院力图为病人减少等待时间。", "error_description": "错误：“力图”后多了“着”。正确应为“力图为……”，“着”表示动作的持续，不能接在“力图”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
