INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业链是指从原材料供应、生产加工到销售服务等各个环节相互连接、协同运作的产业体系。", "primary_collocate": null, "pronunciation": "chǎn yè liàn", "ipa": "ʈʂʰan˨˩˦ je˥˩ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "生物降解材料的研发突破、循环经济产业链的重构、消费者行为的心理引导，均构成政策有效性的支撑要素。", "target_word": "产业链", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个地区正在完善新能源汽车产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芯片产业链涉及设计、制造和封装等环节。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望延长本地农产品的产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情使全球产业链受到了很大影响。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司位于产业链的上游。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的工厂已经融入了全球产业链。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业链上下游企业需要紧密合作。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业链一旦断裂，工厂就无法生产。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家建议加强产业链的安全管理。", "target_word": "产业链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "各环节相互连接的产业体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产业链", "is_correct": true, "explanation": "正确。“产业链”指从原料到销售各环节相互连接的产业体系，能与“重构”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是经济体系，无法被“重构”，与“循环经济”也不相配。"}, {"text": "小日子", "is_correct": false, "explanation": "语域：“小日子”是口语说法，与这句书面语的论述语气不一致。"}, {"text": "伙食", "is_correct": false, "explanation": "搭配：“伙食”可以“改善”，但不说“循环经济伙食的重构”，与“重构”不搭配。"}], "explanations": {"产业链": "正确。“产业链”指从原料到销售各环节相互连接的产业体系，能与“重构”搭配，符合句意。", "天气": "语义：“天气”不是经济体系，无法被“重构”，与“循环经济”也不相配。", "小日子": "语域：“小日子”是口语说法，与这句书面语的论述语气不一致。", "伙食": "搭配：“伙食”可以“改善”，但不说“循环经济伙食的重构”，与“重构”不搭配。"}, "sentence_index": 0, "correct_answer": "产业链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年买了一条产业链，用来锁大门。", "explanation": "这里误用了〈铁链〉的意思。产业链指产业体系，不是能用来锁门的实物链条。"}, {"text": "这个产业链需要三个人同时完成。", "explanation": "这里应该用〈工序〉。产业链是产业体系，不是可以由几个人“完成”的一项具体操作。"}, {"text": "这种有机物的分子里有一条产业链，结构很稳定。", "explanation": "这里误用了化学中〈碳链〉的意思，指分子中原子连成的链状结构。产业链指产业体系，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产业链", "is_correct": true, "explanation": "正确。“全球产业链”指全球范围内相互连接的产业体系，工厂可以“融入”它，符合句意。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：“亲戚”是人际关系，不能与“全球”组成可以“融入”的对象，句子不通。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：“粉笔”是文具，不能被工厂“融入”，与“全球”搭配也说不通。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：“融入”一般用于体系、群体或环境，不说“融入全球饭馆”，与“融入”搭配不当。"}], "explanations": {"产业链": "正确。“全球产业链”指全球范围内相互连接的产业体系，工厂可以“融入”它，符合句意。", "亲戚": "语义：“亲戚”是人际关系，不能与“全球”组成可以“融入”的对象，句子不通。", "粉笔": "语义：“粉笔”是文具，不能被工厂“融入”，与“全球”搭配也说不通。", "饭馆": "搭配：“融入”一般用于体系、群体或环境，不说“融入全球饭馆”，与“融入”搭配不当。"}, "sentence_index": 6, "correct_answer": "产业链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把这个问题交给了产业链去讨论。", "explanation": "这里应该用〈部门〉。产业链是企业之间的连接关系，不能作为有职责的机构去讨论问题。"}, {"text": "这家公司的产业链比去年高了三米。", "explanation": "这里误用了〈高度〉的意思。产业链的大小指企业数量和环节，不能用“高”来计量，“高”只用于人或建筑的高度。"}, {"text": "这家餐厅的产业链很好吃。", "explanation": "这里应该用〈菜〉。产业链指产业体系，不能用“好吃”来形容，“好吃”只用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座产业链从原料到销售都连在一起。", "corrected_sentence": "这条产业链从原料到销售都连在一起。", "error_description": "错误形式：“座产业链”；正确形式：“条产业链”。产业链是链条类事物，量词应为“条”，“座”只用于山、桥、楼等大型建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂已经融入了这座产业链。", "corrected_sentence": "工厂已经融入了这条产业链。", "error_description": "错误形式：“这座产业链”；正确形式：“这条产业链”。产业链的量词应为“条”，“座”用于大型建筑或山桥等固定物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
