INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据事物发展规律预先料到将来。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "可以预见，未来立法将更强调全生命周期管理，从原料提取、产品设计到废弃物回收，形成闭环控制体系。", "target_word": "预见", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家预见到明年的房价会下降。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经验丰富的医生能预见病情的发展。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家根据数据预见了气候的变化。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就预见到这家公司会遇到困难。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能准确预见十年后的世界。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经济学家成功预见了那次危机。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据人口的变化，我们可以预见学校会不够用。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领导者要能预见未来的风险。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有预见这场大雨会下这么久。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预见到", "label": "结果补语"}, {"form": "预见了", "label": "体标"}, {"form": "预见性", "label": "派生"}], "register": "书面", "sense_fingerprint": "根据规律预先料到将来的发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指根据规律预先料到将来。"}, {"text": "物件", "is_correct": false, "explanation": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），意思是物品。"}, {"text": "预检", "is_correct": false, "explanation": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。"}, {"text": "去见", "is_correct": false, "explanation": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。"}, {"text": "玉笺", "is_correct": false, "explanation": "玉笺 yùjiān 与 yùjiàn 第二音节声调不同（第一声 / 第四声），意思是书信用的精美笺纸。"}], "explanations": {"预见": "正确：预见 yùjiàn，指根据规律预先料到将来。", "物件": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），意思是物品。", "预检": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。", "去见": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。", "玉笺": "玉笺 yùjiān 与 yùjiàn 第二音节声调不同（第一声 / 第四声），意思是书信用的精美笺纸。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「可以预见，未来立法将更强调……」中，预见表示事先料到未来的发展，与句意相合。"}, {"text": "回顾", "is_correct": false, "explanation": "语义：回顾指向过去看，与句中‘未来立法’的语境冲突。"}, {"text": "追忆", "is_correct": false, "explanation": "语义：追忆指回想已经发生的事，与句中展望未来的语境矛盾。"}, {"text": "瞅", "is_correct": false, "explanation": "语域：瞅是口语，与这段书面的政策论述语域不合。"}], "explanations": {"预见": "正确：「可以预见，未来立法将更强调……」中，预见表示事先料到未来的发展，与句意相合。", "回顾": "语义：回顾指向过去看，与句中‘未来立法’的语境冲突。", "追忆": "语义：追忆指回想已经发生的事，与句中展望未来的语境矛盾。", "瞅": "语域：瞅是口语，与这段书面的政策论述语域不合。"}, "sentence_index": 0, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里预见了一锅汤。", "explanation": "这里应该用〈煮〉。预见指事先料到将来，不指动手烹煮食物。"}, {"text": "哥伦布在海上预见了一群海豚。", "explanation": "这里应该用〈发现〉。预见指事先料到将来，不指眼前看见海中的动物。"}, {"text": "我在街上预见了老朋友。", "explanation": "这里应该用〈看见〉。预见是事先推测将来，不能用于眼前见到的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指根据规律预先料到将来。"}, {"text": "意见", "is_correct": false, "explanation": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。"}, {"text": "拒见", "is_correct": false, "explanation": "拒见 jùjiàn 与 yùjiàn 声母不同（j / 零声母），意思是拒绝接见。"}, {"text": "续建", "is_correct": false, "explanation": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。"}], "explanations": {"预见": "正确：预见 yùjiàn，指根据规律预先料到将来。", "意见": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。", "拒见": "拒见 jùjiàn 与 yùjiàn 声母不同（j / 零声母），意思是拒绝接见。", "续建": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「这位经济学家成功预见了那次危机」中，预见表示事先料到危机，与‘成功’相合。"}, {"text": "亲历", "is_correct": false, "explanation": "搭配：‘成功’说做成的事，‘亲历’指亲身经历，二者不搭，句中不说‘成功亲历危机’。"}, {"text": "撰写", "is_correct": false, "explanation": "配价：‘撰写’要求文字作品作宾语，不能带‘危机’这样的事件作宾语。"}, {"text": "清点", "is_correct": false, "explanation": "搭配：‘清点’用于物品或人数，不用于‘危机’。"}], "explanations": {"预见": "正确：「这位经济学家成功预见了那次危机」中，预见表示事先料到危机，与‘成功’相合。", "亲历": "搭配：‘成功’说做成的事，‘亲历’指亲身经历，二者不搭，句中不说‘成功亲历危机’。", "撰写": "配价：‘撰写’要求文字作品作宾语，不能带‘危机’这样的事件作宾语。", "清点": "搭配：‘清点’用于物品或人数，不用于‘危机’。"}, "sentence_index": 6, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在屋里预见了一张床。", "explanation": "这里应该用〈看见〉。预见指事先料到将来，不指眼前看到家具。"}, {"text": "周末我预见了老师。", "explanation": "这里应该用〈拜访〉。预见不能表示去看望人；去看望要说‘拜访’。"}, {"text": "科学家在实验室里预见了一块石头。", "explanation": "这里应该用〈分析〉。预见指事先料到将来，不指对实物做检测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能预见了市场的变化。", "corrected_sentence": "他能预见市场的变化。", "error_description": "了错误：‘能’表示能力或可能，后面的动词不带‘了’。‘能预见了’与可能义冲突，正确应为‘他能预见市场的变化’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家提前预见了到风险。", "corrected_sentence": "专家提前预见到了风险。", "error_description": "补语位置错误：结果补语‘到’应紧接动词‘预见’，‘了’放在补语之后。‘预见了到’是错的，正确应为‘预见到了风险’。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
