INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种自动控制方式，系统根据输出结果自动调整输入，使输出保持在设定目标。", "primary_collocate": null, "pronunciation": "bì huán kòng zhì", "ipa": "pi⁵¹ xwan³⁵ kʰʊŋ⁵¹ ʈʂʐ̩⁵¹", "syllable_count": 4, "sentences": [{"text": "电机转速的稳定依赖闭环控制：传感器持续采集实际转速，控制器据此修正输入。", "target_word": "闭环控制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "空调用闭环控制来保持房间的温度。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制能根据结果自动调整输入。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器使用了闭环控制，不需要人看着。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的机器人靠闭环控制保持速度稳定。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制会不断检查输出的结果，再做调整。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的自动驾驶也用到闭环控制。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度太高时，闭环控制会让机器自动降温。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在学习闭环控制的基本方法。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了闭环控制，水箱里的水位不会太高。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭环控制系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "根据输出结果自动调整输入的控制方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。句中“传感器持续采集实际转速，控制器据此修正输入”描述的正是根据输出结果自动调整输入的控制方式。"}, {"text": "开环控制", "is_correct": false, "explanation": "语义：“开环控制”不利用输出反馈，与句中“传感器采集实际转速”这一反馈环节相矛盾。"}, {"text": "齿轮传动", "is_correct": false, "explanation": "语义：“齿轮传动”是传递动力的机械方式，不是根据输出调节输入的控制方式，与“控制器修正输入”不符。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：“温度计”是测量温度的工具，不能作为“转速稳定”所依赖的控制方式，与句意不符。"}], "explanations": {"闭环控制": "正确。句中“传感器持续采集实际转速，控制器据此修正输入”描述的正是根据输出结果自动调整输入的控制方式。", "开环控制": "语义：“开环控制”不利用输出反馈，与句中“传感器采集实际转速”这一反馈环节相矛盾。", "齿轮传动": "语义：“齿轮传动”是传递动力的机械方式，不是根据输出调节输入的控制方式，与“控制器修正输入”不符。", "温度计": "语义：“温度计”是测量温度的工具，不能作为“转速稳定”所依赖的控制方式，与句意不符。"}, "sentence_index": 0, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给了我很多闭环控制，帮助我提高了成绩。", "explanation": "这里应该用〈反馈〉。闭环控制是一种技术上的控制方式，指系统根据输出调整输入，不能用来指老师对学生的意见。"}, {"text": "这台机器装了一个闭环控制，可以检测温度。", "explanation": "这里应该用〈传感器〉。闭环控制是控制方式，不是能检测温度的硬件装置。"}, {"text": "这个程序用了一种闭环控制来识别图片。", "explanation": "这里应该用〈算法〉。闭环控制是调节输入的控制方式，不是识别图像的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。汽车的自动驾驶依靠闭环控制来调节方向和速度，句子通顺。"}, {"text": "人工驾驶", "is_correct": false, "explanation": "语义：“人工驾驶”与句中的“自动驾驶”相对，说“自动驾驶也用到人工驾驶”自相矛盾。"}, {"text": "马车", "is_correct": false, "explanation": "语义：“马车”是古老的交通工具，与“汽车的自动驾驶”所指的现代技术不符。"}, {"text": "蒸汽机", "is_correct": false, "explanation": "搭配：“蒸汽机”不是现代汽车自动驾驶使用的技术，“也用到蒸汽机”搭配不当。"}], "explanations": {"闭环控制": "正确。汽车的自动驾驶依靠闭环控制来调节方向和速度，句子通顺。", "人工驾驶": "语义：“人工驾驶”与句中的“自动驾驶”相对，说“自动驾驶也用到人工驾驶”自相矛盾。", "马车": "语义：“马车”是古老的交通工具，与“汽车的自动驾驶”所指的现代技术不符。", "蒸汽机": "搭配：“蒸汽机”不是现代汽车自动驾驶使用的技术，“也用到蒸汽机”搭配不当。"}, "sentence_index": 6, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师设计了一只闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。闭环控制是抽象的控制方式，〈只〉多用于动物，不能用于它。"}, {"text": "工程师设计了一把闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。〈把〉多用于有柄的器具，闭环控制不是器具，不能用〈把〉计量。"}, {"text": "工程师设计了一台闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。〈台〉用于机器设备，闭环控制是控制方法，不是设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂把闭环控制来稳定机器的速度。", "corrected_sentence": "工厂用闭环控制来稳定机器的速度。", "error_description": "错误形式：“把闭环控制来稳定”用“把”引出对象，但后面没有合适的动词结构；正确形式：“用闭环控制来稳定”。“闭环控制”作为工具，应用“用”引出，“把”字句不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台冰箱用了一台闭环控制来保持温度。", "corrected_sentence": "这台冰箱用了一种闭环控制来保持温度。", "error_description": "量词错了。“闭环控制”是抽象的控制方式，应该用量词“种”，不能用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
