INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了确定是否符合要求而仔细查看。", "primary_collocate": null, "pronunciation": "jiǎn yàn", "ipa": "tɕjɛn˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "全球趋势正从单一禁令转向系统治理，塑料污染的应对也因此成为检验现代国家制度韧性的重要试金石。", "target_word": "检验", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人用仪器检验产品的质量。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要检验他的血液。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实践是检验真理的唯一标准。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批牛奶要先检验，再上市。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们检验了这座桥的安全性。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项新技术还需要时间检验。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天都检验水的质量。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要检验每个学生的作业。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用考试检验学生学得怎么样。", "target_word": "检验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检验了", "label": "完成体"}, {"form": "检验过", "label": "经历体"}, {"form": "检验检验", "label": "重叠"}], "register": "书面", "sense_fingerprint": "仔细查看以确定是否符合要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3029008e-9b1c-4965-998f-79cba7433aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮用", "is_correct": false, "explanation": "搭配：「饮用」的对象是饮料、水等，不能说饮用「制度韧性」。"}, {"text": "检验", "is_correct": true, "explanation": "检验：为确定是否符合要求而仔细查看，与「检验……制度韧性」的语境相符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：「装饰」指美化外观，与用来测试制度韧性的句意不符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：「烹饪」只用于食材，不能说烹饪「制度韧性」。"}], "explanations": {"饮用": "搭配：「饮用」的对象是饮料、水等，不能说饮用「制度韧性」。", "检验": "检验：为确定是否符合要求而仔细查看，与「检验……制度韧性」的语境相符。", "装饰": "语义：「装饰」指美化外观，与用来测试制度韧性的句意不符。", "烹饪": "搭配：「烹饪」只用于食材，不能说烹饪「制度韧性」。"}, "sentence_index": 0, "correct_answer": "检验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天文学家每晚检验星空。", "explanation": "这里应该用〈观察〉。检验指为确定是否合格而仔细查看产品、样品等，观察星空等自然现象要用〈观察〉。"}, {"text": "我们昨晚检验了一场比赛。", "explanation": "这里应该用〈观看〉。检验指为确定是否符合要求而仔细查看，看比赛要用〈观看〉，不能用检验。"}, {"text": "游客在湖边检验风景。", "explanation": "这里应该用〈欣赏〉。检验用于查看是否符合要求，欣赏风景要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "搭配：「品尝」的对象是食物，不能用于「新技术」。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：「熨烫」用于衣物等织物，不能熨「新技术」。"}, {"text": "检验", "is_correct": true, "explanation": "检验：确定新技术是否可靠、是否符合要求需要时间，句意相符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：「拍照」指拍摄图片，与新技术需要时间确认的意思无关。"}], "explanations": {"品尝": "搭配：「品尝」的对象是食物，不能用于「新技术」。", "熨烫": "搭配：「熨烫」用于衣物等织物，不能熨「新技术」。", "检验": "检验：确定新技术是否可靠、是否符合要求需要时间，句意相符。", "拍照": "语义：「拍照」指拍摄图片，与新技术需要时间确认的意思无关。"}, "sentence_index": 6, "correct_answer": "检验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者检验了这位作家。", "explanation": "这里应该用〈访问〉。检验指对物品、材料进行查看核验，采访人物要用〈访问〉。"}, {"text": "社会学家检验了城市里的青年。", "explanation": "这里应该用〈调查〉。检验针对产品、样品的质量，研究人群和社会现象要用〈调查〉。"}, {"text": "我们暑假检验了西湖。", "explanation": "这里应该用〈游览〉。检验用于核对是否符合要求，游览景点要用〈游览〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "质检员从没检验了这批零件。", "corrected_sentence": "质检员从没检验过这批零件。", "error_description": "错误：「从没」表示从未有过的经历，应与经历体「过」搭配，不能用完成体「了」。应说「从没检验过这批零件」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在检验了这批货物。", "corrected_sentence": "工人们正在检验这批货物。", "error_description": "错误：「正在」表示动作正在进行，不能与完成体「了」同用。应去掉「了」，说「正在检验这批货物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
