INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻用来检验事物或人好坏、真假的标准或方法。", "primary_collocate": null, "pronunciation": "shì jīn shí", "ipa": "ʂɻ̩˥˩ tɕin˥ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "全球趋势正从单一禁令转向系统治理，塑料污染的应对也因此成为检验现代国家制度韧性的重要试金石。", "target_word": "试金石", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "困难是检验朋友的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛是他的一块试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间是爱情最好的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场考试是学生能力的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危难时刻是人品的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新产品能卖多少，市场就是试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实践是检验想法的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个任务是新经理的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次合作成了两家公司的一块试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "比喻检验好坏真假的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3029008e-9b1c-4965-998f-79cba7433aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试金石", "is_correct": true, "explanation": "正确：“试金石”指检验标准，与句中的“检验”呼应，符合句意。"}, {"text": "绊脚石", "is_correct": false, "explanation": "语义：绊脚石指阻碍，与“检验……韧性”的作用相反。"}, {"text": "摆设", "is_correct": false, "explanation": "语义：摆设只起装饰作用，与“重要”和“检验”相矛盾。"}, {"text": "调味料", "is_correct": false, "explanation": "搭配：“调味料”用于食物，不能用来检验国家制度的韧性。"}], "explanations": {"试金石": "正确：“试金石”指检验标准，与句中的“检验”呼应，符合句意。", "绊脚石": "语义：绊脚石指阻碍，与“检验……韧性”的作用相反。", "摆设": "语义：摆设只起装饰作用，与“重要”和“检验”相矛盾。", "调味料": "搭配：“调味料”用于食物，不能用来检验国家制度的韧性。"}, "sentence_index": 0, "correct_answer": "试金石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用试金石削铅笔。", "explanation": "这里应该用〈小刀〉。“试金石”指检验好坏真假的标准，或用来辨别金子成色的石头，都不能用来削铅笔。"}, {"text": "妈妈用试金石包了饺子。", "explanation": "这里应该用〈面皮〉。“试金石”指检验标准或辨金的石头，不能用来包饺子。"}, {"text": "他的试金石很甜。", "explanation": "这里应该用〈水果〉。“试金石”是石头或检验标准，不会有甜味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试金石", "is_correct": true, "explanation": "正确：“试金石”指衡量好坏的标准，与“能卖多少”的检验含义吻合。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能用来衡量销量，与“能卖多少”的检验含义不符。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：饲料是喂养动物的东西，不能用来衡量产品的销量。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动器材，无法检验产品的销量，句意不通。"}], "explanations": {"试金石": "正确：“试金石”指衡量好坏的标准，与“能卖多少”的检验含义吻合。", "玩具": "语义：玩具不能用来衡量销量，与“能卖多少”的检验含义不符。", "饲料": "语义：饲料是喂养动物的东西，不能用来衡量产品的销量。", "篮球": "语义：篮球是运动器材，无法检验产品的销量，句意不通。"}, "sentence_index": 6, "correct_answer": "试金石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次合作成了两家公司的一只试金石。", "explanation": "这里应该用〈块〉（一块试金石）。“试金石”是石头类名词，“只”用于动物等，不用于它。"}, {"text": "这次合作成了两家公司的一把试金石。", "explanation": "这里应该用〈块〉（一块试金石）。“把”用于有柄的器具，不用于“试金石”。"}, {"text": "这次合作成了两家公司的一条试金石。", "explanation": "这里应该用〈块〉（一块试金石）。“条”用于细长的东西，不用于“试金石”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛是检验他实力的一只试金石。", "corrected_sentence": "这次比赛是检验他实力的一块试金石。", "error_description": "量词错误：“试金石”指检验标准，量词用“块”（一块试金石）；“只”用于动物等，不能用于“试金石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项改革成了城市治理的试金石们。", "corrected_sentence": "这项改革成了城市治理的试金石。", "error_description": "词尾错误：“们”只用于指人，“试金石”是事物，不能加“们”。应说“城市治理的试金石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
