INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指清洁、无污染的水，适合饮用或使用。", "primary_collocate": null, "pronunciation": "gān jìng shuǐ", "ipa": "kan˥ tɕiŋ˥˩ ʂweɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "水用多了，有些地方的人就没有干净水喝。", "target_word": "干净水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "孩子们每天都需要干净水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子以前没有干净水，现在有了。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一杯干净水，谢谢。", "target_word": "干净水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医院里用干净水洗手。", "target_word": "干净水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的泉水是很好的干净水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在路上带了一壶干净水。", "target_word": "干净水", "complexity_tier": "T3", "furigana": "wǒ men zài lù shàng dài le yì hú gān jìng shuǐ", "sentence_source": "generated"}, {"text": "没有干净水，人很容易生病。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器能把河水变成干净水。", "target_word": "干净水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友要喝干净水，不要喝河里的水。", "target_word": "干净水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "干净水：清洁无污染、可饮用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f2b21f7-48af-4f3b-85cd-c9621453e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海水", "is_correct": false, "explanation": "语义：海水是咸的，不能饮用，与“没有……喝”的语境矛盾。"}, {"text": "干净水", "is_correct": true, "explanation": "正确：指清洁、可以饮用的水，符合“没有……喝”的语境。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“喝”不能搭配“墨水”，墨水不能饮用。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板是固体，不是可以喝的液体，句意不通。"}], "explanations": {"海水": "语义：海水是咸的，不能饮用，与“没有……喝”的语境矛盾。", "干净水": "正确：指清洁、可以饮用的水，符合“没有……喝”的语境。", "墨水": "搭配：“喝”不能搭配“墨水”，墨水不能饮用。", "地板": "语义：地板是固体，不是可以喝的液体，句意不通。"}, "sentence_index": 0, "correct_answer": "干净水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶干净水颜色发黄，看起来很脏。", "explanation": "这里误用了词义。“干净水”指清洁、无污染、可以饮用的水，这里却把它当成了“不干净、不能喝的水”来用。"}, {"text": "这杯干净水里有很多脏东西，不能喝。", "explanation": "这里误用了词义。“干净水”指清洁、无污染的水，这里却把它当成了“含杂质、不干净的水”来用。"}, {"text": "请给我一杯干净水，水里漂着很多垃圾，谢谢。", "explanation": "这里误用了词义。“干净水”指清洁、无污染的水，这里却说水里漂着很多垃圾，与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“壶”装的是液体，“石头”不能用“一壶”装着带在路上。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是液体，装在壶里带在路上没有意义，句意不通。"}, {"text": "干净水", "is_correct": true, "explanation": "正确：指清洁、可以饮用的水，适合装在壶里带在路上喝。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板是固体，不能装进壶里，与“带了一壶”的语境矛盾。"}], "explanations": {"石头": "搭配：“壶”装的是液体，“石头”不能用“一壶”装着带在路上。", "沙子": "语义：沙子不是液体，装在壶里带在路上没有意义，句意不通。", "干净水": "正确：指清洁、可以饮用的水，适合装在壶里带在路上喝。", "地板": "语义：地板是固体，不能装进壶里，与“带了一壶”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "干净水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干净水里有很多泥沙和脏东西，小朋友最好多喝。", "explanation": "这里误用了词义。“干净水”指清洁、无污染的水，这里却把它当成了“含杂质、不干净的水”来用。"}, {"text": "这杯干净水里有很多细菌，小朋友喝了会生病。", "explanation": "这里误用了词义。“干净水”指无污染、可以安全饮用的水，这里却把它当成了“含病菌、会致病的水”来用。"}, {"text": "小朋友不能喝干净水，只能喝脏水。", "explanation": "这里误用了词义。“干净水”就是可以喝的水，这里却把它当成了“不适合喝的水”来用，与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只干净水。", "corrected_sentence": "我买了一瓶干净水。", "error_description": "量词错误：“干净水”是液体，应用“瓶”量，不能说“一只干净水”。正确说法是“一瓶干净水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在路上带了一干净水。", "corrected_sentence": "我们在路上带了一瓶干净水。", "error_description": "量词缺失：“一”后面要有量词，应说“一瓶干净水”，不能说“一干净水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变干净", "is_correct": true, "explanation": "反义：“变脏”指变得不干净，“变干净”指由脏变得清洁，二者相对。"}, {"text": "增大", "is_correct": false, "explanation": "无关：“增大”指数量或体积变大，与清洁程度无关。"}, {"text": "变长", "is_correct": false, "explanation": "无关：“变长”指长度增加，与清洁程度无关。"}, {"text": "生锈", "is_correct": false, "explanation": "无关：“生锈”指金属表面被氧化，不是清洁程度的对立面。"}], "correct_answer": "变干净", "explanations": {"变干净": "反义：“变脏”指变得不干净，“变干净”指由脏变得清洁，二者相对。", "增大": "无关：“增大”指数量或体积变大，与清洁程度无关。", "变长": "无关：“变长”指长度增加，与清洁程度无关。", "生锈": "无关：“生锈”指金属表面被氧化，不是清洁程度的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变干净", "is_correct": true, "explanation": "反义：“变脏”指变得不干净，“变干净”指由脏变得清洁，二者相对。"}, {"text": "放大", "is_correct": false, "explanation": "无关：“放大”指使物体变大或图像变大，与清洁程度无关。"}, {"text": "膨胀", "is_correct": false, "explanation": "无关：“膨胀”指体积因受热或受压变大，与清洁程度不相关。"}, {"text": "烧焦", "is_correct": false, "explanation": "无关：“烧焦”指被火烤黑，不是“变脏”的反义。"}], "correct_answer": "变干净", "explanations": {"变干净": "反义：“变脏”指变得不干净，“变干净”指由脏变得清洁，二者相对。", "放大": "无关：“放大”指使物体变大或图像变大，与清洁程度无关。", "膨胀": "无关：“膨胀”指体积因受热或受压变大，与清洁程度不相关。", "烧焦": "无关：“烧焦”指被火烤黑，不是“变脏”的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物（衣物、器具、水、河流等）沾上污垢，不再清洁。", "primary_collocate": null, "pronunciation": "biàn zāng", "ipa": "pjɛn˥˩ tsɑŋ˥", "syllable_count": 2, "sentences": [{"text": "工厂做衣服时，也让水变脏。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "白衬衫很容易变脏。", "target_word": "变脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨后，我的新鞋变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水为什么会变脏呢？", "target_word": "变脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子玩了一天，衣服都变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白墙上有很多手印，已经变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地板每天都要擦，不然会变脏。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里的水排出来，河会慢慢变脏。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心点，别让新书包变脏。", "target_word": "变脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有油，白布马上变脏了。", "target_word": "变脏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变脏了", "label": "体标"}, {"form": "变脏过", "label": "体标"}], "register": "中性", "sense_fingerprint": "变脏：事物（衣物、器具、水体等）沾上污垢，不再清洁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f2b21f7-48af-4f3b-85cd-c9621453e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "语义：水不会生锈，与“工厂做衣服时”的语境不符。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“水”不能“开花”，搭配不当。"}, {"text": "变脏", "is_correct": true, "explanation": "正确：指东西变得不干净，符合“工厂做衣服时，也让水……”的语境。"}, {"text": "变干净", "is_correct": false, "explanation": "语义：句中讲的是水被弄脏，“变干净”与之相反。"}], "explanations": {"生锈": "语义：水不会生锈，与“工厂做衣服时”的语境不符。", "开花": "搭配：“水”不能“开花”，搭配不当。", "变脏": "正确：指东西变得不干净，符合“工厂做衣服时，也让水……”的语境。", "变干净": "语义：句中讲的是水被弄脏，“变干净”与之相反。"}, "sentence_index": 0, "correct_answer": "变脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资变脏了，比上个月少了很多。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，不能用于工资这类抽象的东西，这里却把它当成了“数量减少”的意思来用。"}, {"text": "这次考试的成绩变脏了，我很难过。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，不能用于成绩，这里却把它当成了“成绩变差”的意思来用。"}, {"text": "这个计划变脏了，大家都不同意。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，计划不会沾上污垢，这里却把它当成了“计划出了问题”的意思来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "搭配：地板不会“唱歌”，搭配不当。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：地板不会结冰，与“每天都要擦”的语境不符。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：地板冒烟与“每天擦”的日常语境矛盾，句意不通。"}, {"text": "变脏", "is_correct": true, "explanation": "正确：指东西变得不干净，符合“每天都要擦，不然会……”的语境。"}], "explanations": {"唱歌": "搭配：地板不会“唱歌”，搭配不当。", "结冰": "语义：地板不会结冰，与“每天都要擦”的语境不符。", "冒烟": "语义：地板冒烟与“每天擦”的日常语境矛盾，句意不通。", "变脏": "正确：指东西变得不干净，符合“每天都要擦，不然会……”的语境。"}, "sentence_index": 6, "correct_answer": "变脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段友谊变脏了，两个人很久不说话。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，不能用于友谊，这里却把它当成了“关系变坏”的意思来用。"}, {"text": "这家店的价格变脏了，便宜了很多。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，不能用于价格，这里却把它当成了“降价”的意思来用。"}, {"text": "我的感冒变脏了，已经好了三天。", "explanation": "这里误用了词义。“变脏”指物体表面沾上污垢，不能用于病，这里却把它当成了“病情好转”的意思来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张白纸放在桌上一会儿就很变脏了。", "corrected_sentence": "这张白纸放在桌上一会儿就变脏了。", "error_description": "副词位置错误：“很”修饰形容词，不能修饰动词“变脏”，应说“就变脏了”，不说“就很变脏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地板不擦会就变脏。", "corrected_sentence": "地板不擦就会变脏。", "error_description": "副词位置错误：“就”和“会”的顺序颠倒，应说“就会变脏”，不能说“会就变脏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
