INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13292, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体表面有尘土、污渍等不洁净的物质，也用于形容人的行为或话语粗俗、下流。", "primary_collocate": null, "pronunciation": "zāng", "ipa": "tsɑŋ˥", "syllable_count": 1, "sentences": [{"text": "工厂做衣服时，也让水变脏。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "脏水流到河里，鱼也会死。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "工厂做衣服时，也会把脏水流到河里。", "target_word": "脏", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他的手太脏了，先洗手再吃饭。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路下雨以后又湿又脏。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服掉在地上，变脏了。", "target_word": "脏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间很脏，到处都是灰。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白衬衫很容易脏，要常洗。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他嘴很脏，总说难听的话。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子有点脏，换一个吧。", "target_word": "脏", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "脏脏的", "label": "重叠"}, {"form": "髒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体表面有污渍不洁净，也指言行粗俗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f3bb72-e6b9-4d54-bc89-55e59a88509c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13292, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。脏指物体不干净，有污垢。"}, {"text": "张", "is_correct": false, "explanation": "zh 与 z 声母不同，声调相同，意思是量词“张”，用于纸、桌子等。"}, {"text": "桑", "is_correct": false, "explanation": "s 与 z 声母不同，声调相同，意思是桑树。"}, {"text": "葬", "is_correct": false, "explanation": "zàng（第四声）与 zāng（第一声）声调不同，意思是埋葬。"}, {"text": "仓", "is_correct": false, "explanation": "c 与 z 声母不同，声调相同，意思是仓库。"}], "explanations": {"脏": "正确。脏指物体不干净，有污垢。", "张": "zh 与 z 声母不同，声调相同，意思是量词“张”，用于纸、桌子等。", "桑": "s 与 z 声母不同，声调相同，意思是桑树。", "葬": "zàng（第四声）与 zāng（第一声）声调不同，意思是埋葬。", "仓": "c 与 z 声母不同，声调相同，意思是仓库。"}, "sentence_index": null, "correct_answer": "脏"}, "level_3": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。句中指水被污染，变得不干净。"}, {"text": "甜", "is_correct": false, "explanation": "语义：工厂废水不会变甜，“让水变甜”与句意不符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖描述人或动物的体形，不能用来形容水。"}, {"text": "圆", "is_correct": false, "explanation": "语义：水不会变成“圆”的样子，与句意不符。"}], "explanations": {"脏": "正确。句中指水被污染，变得不干净。", "甜": "语义：工厂废水不会变甜，“让水变甜”与句意不符。", "胖": "体貌：胖描述人或动物的体形，不能用来形容水。", "圆": "语义：水不会变成“圆”的样子，与句意不符。"}, "sentence_index": 0, "correct_answer": "脏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很脏，老师很生气。", "explanation": "“脏”只用于说物体的污垢或人的言行粗俗，考试成绩这种抽象结果应说“差”，不能用“脏”。"}, {"text": "这盏灯的亮度很脏。", "explanation": "“脏”不表示光线的明暗，亮度应说“亮”或“暗”，不能用“脏”。"}, {"text": "这辆车的速度很脏。", "explanation": "“脏”不能形容速度，速度应说“快”或“慢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脏", "is_correct": true, "explanation": "正确。句中指房间不干净，到处都是灰。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”与后句“到处都是灰”矛盾，句意不通。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”是形状，不能用来形容房间的卫生状况。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦描述人或动物的体形，不能用于房间。"}], "explanations": {"脏": "正确。句中指房间不干净，到处都是灰。", "干净": "语义：“干净”与后句“到处都是灰”矛盾，句意不通。", "圆": "语义：“圆”是形状，不能用来形容房间的卫生状况。", "瘦": "体貌：瘦描述人或动物的体形，不能用于房间。"}, "sentence_index": 6, "correct_answer": "脏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的心情很脏，不想说话。", "explanation": "“脏”不能描述心情，心情应说“糟”或“好”，不能用“脏”。"}, {"text": "我们的距离很脏，要走很久。", "explanation": "“脏”不能形容距离，距离应说“远”或“近”。"}, {"text": "这个时间很脏，大家都在忙。", "explanation": "“脏”不能形容时间，时间紧张应说“紧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服脏太了，要马上洗。", "corrected_sentence": "这件衣服太脏了，要马上洗。", "error_description": "语序错误：程度副词“太”应放在形容词前，应说“太脏了”，不能说“脏太了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "衣服脏变了，要洗一洗。", "corrected_sentence": "衣服变脏了，要洗一洗。", "error_description": "补语语序错误：“变脏了”是动补结构，“变”在前，不能说“脏变了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
