INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生活在水中，用腮呼吸，有鳞和鳍的脊椎动物。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "脏水流到河里，鱼也会死。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "河里有很多鱼，孩子们看得很开心。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼用腮呼吸，所以离不开水。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼身上有鳞，摸起来很滑。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的身体很长，尾巴是红色的。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水太冷了，鱼都游到深水里去了。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼离开水以后，很快就会死。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里的鱼比河里的鱼大得多。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼的背上有鳍，帮它在水里游。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变脏了，湖里的鱼越来越少。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "金鱼", "label": "复合"}, {"form": "鱼肉", "label": "复合"}, {"form": "魚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鱼：生活在水中、用腮呼吸、有鳞和鳍的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水中、用腮呼吸的动物。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。"}, {"text": "预", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。"}, {"text": "无", "is_correct": false, "explanation": "wú 与 yú 韵母不同（u 与 ü），意思是没有。"}], "explanations": {"鱼": "正确。鱼：生活在水中、用腮呼吸的动物。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。", "预": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。", "无": "wú 与 yú 韵母不同（u 与 ü），意思是没有。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能用“会死”来形容。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。鱼生活在水中，水脏了鱼就会死。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有生命，“也会死”不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有生命，不会“死”。"}], "explanations": {"石头": "语义：石头没有生命，不能用“会死”来形容。", "鱼": "正确。鱼生活在水中，水脏了鱼就会死。", "房子": "语义：房子没有生命，“也会死”不通。", "桌子": "语义：桌子没有生命，不会“死”。"}, "sentence_index": 0, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是鱼，每天早上很早就出海。", "explanation": "这里应该用〈渔夫〉。鱼指水里的动物，以捕鱼为业的人要用渔夫，二者同音但不能互换。"}, {"text": "这本书鱼期不还，要罚款。", "explanation": "这里应该用〈逾〉。“逾期”指超过期限，与鱼同音；“鱼期”不成词。"}, {"text": "这个月结束后，我还有一点鱼钱。", "explanation": "这里应该用〈余〉。余表示“剩下”，与鱼同音但意思不同，应说“余钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13295, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水中、用腮呼吸的动物。"}, {"text": "育", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是培育。"}, {"text": "浴", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。"}, {"text": "芋", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。"}, {"text": "局", "is_correct": false, "explanation": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}], "explanations": {"鱼": "正确。鱼：生活在水中、用腮呼吸的动物。", "育": "yù（第四声）与 yú（第二声）声调不同，意思是培育。", "浴": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。", "芋": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。", "局": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有生命，离开水不会“死”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“离开水”一般说需要水的生物，书不与之搭配。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。鱼用腮呼吸，离开水就无法呼吸，很快会死。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机没有生命，不能说“会死”。"}], "explanations": {"椅子": "语义：椅子没有生命，离开水不会“死”。", "书": "搭配：“离开水”一般说需要水的生物，书不与之搭配。", "鱼": "正确。鱼用腮呼吸，离开水就无法呼吸，很快会死。", "手机": "语义：手机没有生命，不能说“会死”。"}, "sentence_index": 6, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本鱼，回家做汤。", "explanation": "这里应该用〈条〉。鱼用“条”计量，“本”用于书、本子等。"}, {"text": "河里游着一朵鱼。", "explanation": "这里应该用〈条〉。“朵”用于花、云等，不用于鱼。"}, {"text": "桌子上放着一棵鱼。", "explanation": "这里应该用〈条〉。“棵”用于树、菜等植物，不用于鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天钓了两鱼条，回家做汤。", "corrected_sentence": "我昨天钓了两条鱼，回家做汤。", "error_description": "语序错误：量词“条”应放在“鱼”前面，应说“两条鱼”，不能说“两鱼条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在湖边钓到了一个鱼。", "corrected_sentence": "孩子们在湖边钓到了一条鱼。", "error_description": "量词错误：“鱼”应用“条”计量，“个”不能用于鱼，应说“一条鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
