INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指商品或服务吸引消费者购买的特性或优势。", "primary_collocate": null, "pronunciation": "mǎi diǎn", "ipa": "mai˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家餐厅的买点是菜好吃，环境也安静。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的最大买点是电池用得久。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便宜是这家店的买点，所以客人很多。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的买点是不怕热，也不怕摔。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问我们：这个东西的买点是什么？", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对很多人来说，好看就是衣服的买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的买点是故事有意思，字也大。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的买点是省油，价钱也不高。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王写出了这个商品的三个买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告没有说清楚房子的买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "買點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买点：商品吸引消费者购买的特性或优势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买点", "is_correct": true, "explanation": "正确：“买点”指吸引消费者购买的优势，“菜好吃，环境也安静”正是餐厅的优势。"}, {"text": "缺点", "is_correct": false, "explanation": "语义：“缺点”与“菜好吃，环境也安静”所说的优势相矛盾。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指位置，不能用来说“是菜好吃”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能与“是菜好吃，环境也安静”搭配，句意不通。"}], "explanations": {"买点": "正确：“买点”指吸引消费者购买的优势，“菜好吃，环境也安静”正是餐厅的优势。", "缺点": "语义：“缺点”与“菜好吃，环境也安静”所说的优势相矛盾。", "地址": "语义：“地址”指位置，不能用来说“是菜好吃”。", "价格": "搭配：“价格”不能与“是菜好吃，环境也安静”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的买点是很诚实，大家都愿意跟他合作。", "explanation": "这里应该用〈优点〉。买点只指商品或服务吸引人购买的地方，不用来说人的品质。"}, {"text": "这个电脑有三只买点，屏幕很亮。", "explanation": "这里应该用〈个〉。“只”用于动物等，买点要用“个”计量。"}, {"text": "这个手机的买点是公司能赚很多钱。", "explanation": "这里应该用〈卖点〉。买点是顾客想买的理由，卖点是商家宣传的特色；“公司能赚很多钱”站在商家角度，不是顾客想买的理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封面", "is_correct": false, "explanation": "语义：“封面”指书的外壳，与“故事有意思，字也大”所说的内容无关，句子不通。"}, {"text": "买点", "is_correct": true, "explanation": "正确。买点指吸引人购买的优势，这里说这本书的故事有意思、字也大。"}, {"text": "页数", "is_correct": false, "explanation": "搭配：“页数”指书的张数，不能说“是故事有意思，字也大”，搭配不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”说的是岁数，与句中对书的评价不相容。"}], "explanations": {"封面": "语义：“封面”指书的外壳，与“故事有意思，字也大”所说的内容无关，句子不通。", "买点": "正确。买点指吸引人购买的优势，这里说这本书的故事有意思、字也大。", "页数": "搭配：“页数”指书的张数，不能说“是故事有意思，字也大”，搭配不通。", "年龄": "语义：“年龄”说的是岁数，与句中对书的评价不相容。"}, "sentence_index": 6, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房子的买点是离地铁太远，交通不方便。", "explanation": "这里应该用〈缺点〉。买点指吸引人购买的优势，“离地铁太远”是缺点，不能叫买点。"}, {"text": "这套房子有三片买点。", "explanation": "这里应该用〈个〉。“片”用于叶子、面包等薄片状的东西，买点要用“个”计量。"}, {"text": "这家房产中介有一朵买点。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，不用于买点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水壶有两条买点，价钱不高。", "corrected_sentence": "这个水壶有两个买点，价钱不高。", "error_description": "量词错误：“买点”应用“个”计量，“条”用于细长的东西，不能用于买点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电视买点是屏幕大，声音也好。", "corrected_sentence": "这台电视的买点是屏幕大，声音也好。", "error_description": "结构助词错误：定语“这台电视”与中心语“买点”之间要用“的”连接，应说“电视的买点”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用钱物。"}, {"text": "赚取", "is_correct": false, "explanation": "赚取：指获得钱财，与“省”的节约义没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱取得物品，与“省”的节约义不构成反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "增加：指数量变多，与“省”的节约义没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用钱物。", "赚取": "赚取：指获得钱财，与“省”的节约义没有反义关系。", "购买": "购买：指花钱取得物品，与“省”的节约义不构成反义关系。", "增加": "增加：指数量变多，与“省”的节约义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用钱物。"}, {"text": "生产", "is_correct": false, "explanation": "生产：指制造物品，与“省”的节约义没有反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大：指范围或规模变大，与“省”的节约义没有反义关系。"}, {"text": "出售", "is_correct": false, "explanation": "出售：指把东西卖掉，与“省”的节约义没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用钱物。", "生产": "生产：指制造物品，与“省”的节约义没有反义关系。", "扩大": "扩大：指范围或规模变大，与“省”的节约义没有反义关系。", "出售": "出售：指把东西卖掉，与“省”的节约义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "节约，不浪费；如省钱、省时间。", "primary_collocate": null, "pronunciation": "shěng", "ipa": "ʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "坐地铁上班可以省钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走这条路能省不少时间。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们关灯出门，是为了省电。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会省，每个月都存一点钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把吃饭的钱省下来买了一本书。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少洗一次车，也能省很多水。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家做饭比在外面吃饭省钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每次买东西都会先比价，这样能省不少钱。", "target_word": "省", "complexity_tier": "T3", "furigana": "wǒ měi cì mǎi dōng xi dōu huì xiān bǐ jià, zhè yàng néng shěng bù shǎo qián.", "sentence_source": "generated"}, {"text": "为了省时间，我们坐出租车去机场。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他省了很久，终于买了新手机。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省了", "label": "体标"}, {"form": "省着", "label": "体标"}, {"form": "省省", "label": "重叠"}, {"form": "省钱", "label": "复合"}, {"form": "省电", "label": "复合"}], "register": "中性", "sense_fingerprint": "省：节约，不浪费钱、时间等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：节约，不浪费钱或时间。"}, {"text": "生", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。"}, {"text": "声", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。"}, {"text": "圣", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“神圣”。"}, {"text": "婶", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。"}, {"text": "审", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。"}], "explanations": {"省": "省（shěng）：节约，不浪费钱或时间。", "生": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。", "声": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。", "剩": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。", "圣": "shèng（第四声）与 shěng（第三声）声调不同，意思是“神圣”。", "婶": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。", "审": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示节约钱财，“坐地铁上班可以省钱”符合句意。"}, {"text": "赔", "is_correct": false, "explanation": "语义：“赔钱”指亏本、损失钱财，与“坐地铁上班可以……钱”要表达的节省相反。"}, {"text": "亏", "is_correct": false, "explanation": "语义：“亏钱”指蚀本，句中是在说坐地铁带来的好处，两者意思相反。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借钱”是向别人借入钱财，与“坐地铁上班”能省钱的语境不合。"}], "explanations": {"省": "“省”表示节约钱财，“坐地铁上班可以省钱”符合句意。", "赔": "语义：“赔钱”指亏本、损失钱财，与“坐地铁上班可以……钱”要表达的节省相反。", "亏": "语义：“亏钱”指蚀本，句中是在说坐地铁带来的好处，两者意思相反。", "借": "语义：“借钱”是向别人借入钱财，与“坐地铁上班”能省钱的语境不合。"}, "sentence_index": 0, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年这个小镇的人口省了很多。", "explanation": "这里应该用〈减少〉。“省”表示节约、少用钱物或时间，人口的下降不能说“省”。"}, {"text": "这家店的菜价省了很多。", "explanation": "这里应该用〈降低〉。“省”指节约、少用钱物，价格的下降要说“降低”或“下降”。"}, {"text": "他这个月想省三公斤。", "explanation": "这里应该用〈减〉。“省”指节约、少用钱物，体重的减少要说“减”或“减掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：节约，不浪费钱或时间。"}, {"text": "胜", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“胜利”。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。"}, {"text": "盛", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛”。"}], "explanations": {"省": "省（shěng）：节约，不浪费钱或时间。", "胜": "shèng（第四声）与 shěng（第三声）声调不同，意思是“胜利”。", "绳": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。", "盛": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示节约钱财，“在家做饭比在外面吃饭省钱”符合句意。"}, {"text": "减", "is_correct": false, "explanation": "搭配：“减”不直接带“钱”作宾语，此处应说“省钱”，且“减钱”说法不通。"}, {"text": "增", "is_correct": false, "explanation": "搭配：“增”与“钱”不搭，“增钱”不通，且与句中比较节省的意思相反。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花钱”指耗费钱财，与“在家做饭比在外面吃饭更省钱”的意思相反。"}], "explanations": {"省": "“省”表示节约钱财，“在家做饭比在外面吃饭省钱”符合句意。", "减": "搭配：“减”不直接带“钱”作宾语，此处应说“省钱”，且“减钱”说法不通。", "增": "搭配：“增”与“钱”不搭，“增钱”不通，且与句中比较节省的意思相反。", "花": "语义：“花钱”指耗费钱财，与“在家做饭比在外面吃饭更省钱”的意思相反。"}, "sentence_index": 6, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这样做可以省家里的负担。", "explanation": "这里应该用〈减轻〉。“省”用于可以节约的钱、水、电等，“负担”的减轻要说“减轻”。"}, {"text": "这次改革让城市的范围省了一半。", "explanation": "这里应该用〈缩小〉。“省”用于可以节约的钱、水、电等，范围的缩小要说“缩小”。"}, {"text": "他每个月都省一点经验。", "explanation": "这里应该用〈积累〉。“省”指节约、不浪费，经验是靠实践积累的，不能“省”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每个月都省上一笔钱，准备买房。", "corrected_sentence": "他每个月都省下一笔钱，准备买房。", "error_description": "错误：“省上”。正确：“省下”。“省下”表示节省后留下来，“上”不能作“省”的结果补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她省钱着，给家里买了一台新冰箱。", "corrected_sentence": "她省着钱，给家里买了一台新冰箱。", "error_description": "错误：“省钱着”。正确：“省着钱”。“着”是动态助词，应紧跟动词“省”，表示动作持续，不能放在宾语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指江河中流动的水体。", "primary_collocate": null, "pronunciation": "hé shuǐ", "ipa": "xɤ˧˥ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "春天到了，河水慢慢变暖了。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天大雨，河水涨得很高。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从山上流下来，流得很快。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，孩子们跳进河水里玩。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很清，能看见水里的小鱼。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，河水都结冰了。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把脏水倒进河里，河水变黑了。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水往东流，最后流进大海。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的河水很干净，现在不能直接喝了。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着河水，想起了小时候的事。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "江河中流动的水体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河水", "is_correct": true, "explanation": "正确：河水是河里流动的水，春天会慢慢变暖。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不会因“春天到了”而变暖，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会变暖，句意不通。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：雪一般说“融化”，不说“变暖”。"}], "explanations": {"河水": "正确：河水是河里流动的水，春天会慢慢变暖。", "字典": "语义：字典不会因“春天到了”而变暖，句意不通。", "作业": "语义：作业不会变暖，句意不通。", "雪": "搭配：雪一般说“融化”，不说“变暖”。"}, "sentence_index": 0, "correct_answer": "河水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河水很长，流过了好几个省。", "explanation": "这里应该用〈河流〉。“河水”指河里流动的水，说河的长度、流经的地方要用“河流”或“河”。"}, {"text": "这个湖的河水很深，里面有很多鱼。", "explanation": "这里应该用〈湖水〉。湖里的水不是河里的水，应说湖水。"}, {"text": "我们在山上的泉边打了一桶河水，喝起来很甜。", "explanation": "这里应该用〈泉水〉。从泉边打的水应说泉水，河水指江河中的水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": true, "explanation": "正确：脏水倒进河里，河水会变黑，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板本身是黑色的，“变黑”说不通，句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会因为河里倒了脏水而变黑。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“变黑”用于颜色或物体，价格不能说变黑。"}], "explanations": {"河水": "正确：脏水倒进河里，河水会变黑，符合句意。", "黑板": "语义：黑板本身是黑色的，“变黑”说不通，句意不通。", "太阳": "语义：太阳不会因为河里倒了脏水而变黑。", "价格": "搭配：“变黑”用于颜色或物体，价格不能说变黑。"}, "sentence_index": 6, "correct_answer": "河水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在海边玩，脚踩进的河水很凉。", "explanation": "这里应该用〈海水〉。海边的水是海水，河水指江河中的水。"}, {"text": "下了一夜大雨，院子里积了很多河水。", "explanation": "这里应该用〈雨水〉。雨后积的水应说雨水，河水指江河中的水。"}, {"text": "早上我从井里打了一桶河水做饭。", "explanation": "这里应该用〈井水〉。从井里打的水应说井水，河水指江河中的水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们用桶舀了一条河水，想拿去浇花。", "corrected_sentence": "孩子们用桶舀了一桶河水，想拿去浇花。", "error_description": "量词错误：“河水”的量词应用“桶”，“条”用于河流（一条河），不能用于河水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢很清得河水，常去那里玩。", "corrected_sentence": "我喜欢很清的河水，常去那里玩。", "error_description": "结构助词错误：修饰语“很清”与“河水”之间应用“的”，不能用“得”，写作“很清的河水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
