INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示动作或状态持续进行，没有中断。", "primary_collocate": null, "pronunciation": "bù tíng", "ipa": "pu˥˩ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大家不停地买新衣服，这就是消费主义。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "雨下了一整天，到现在还在不停地下。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭个不停，妈妈只好抱着他。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手不停地发抖。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话不停地响，可是没有人接。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边走一边不停地看手机。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗见到主人，尾巴不停地摇。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不停地咳嗽，应该去医院看看。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们不停地练习，终于唱好了这首歌。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的风不停地吹着，我睡不着。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不停地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "副词，修饰动作，表示持续进行、不间断，常带“地”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停（bù tíng）是副词，表示动作或状态持续不间断。"}, {"text": "不听", "is_correct": false, "explanation": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。"}, {"text": "不疼", "is_correct": false, "explanation": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。"}, {"text": "不提", "is_correct": false, "explanation": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}], "explanations": {"不停": "不停（bù tíng）是副词，表示动作或状态持续不间断。", "不听": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。", "不疼": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。", "不提": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}, "sentence_index": null, "correct_answer": "不停"}, "level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：表示买新衣服持续不断，与“这就是消费主义”所说的过度购买相符。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“大家”是群体，“独自”指一个人单独做，与句子的主语冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“这就是消费主义”所说的频繁购买矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”多用于突发的动作或发现，不能修饰持续进行的购买。"}], "explanations": {"不停": "不停：表示买新衣服持续不断，与“这就是消费主义”所说的过度购买相符。", "独自": "语义：“大家”是群体，“独自”指一个人单独做，与句子的主语冲突。", "偶尔": "语义：“偶尔”表示间或发生，与“这就是消费主义”所说的频繁购买矛盾。", "猛然": "搭配：“猛然”多用于突发的动作或发现，不能修饰持续进行的购买。"}, "sentence_index": 0, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数字不停地等于五。", "explanation": "这里误用了“不停”。“不停地”描述动作或变化持续不断地进行，而这里说的是固定不变的数量关系，不会持续发生，因此不能用“不停地”修饰。"}, {"text": "他不停地参加了一次面试，结果很顺利。", "explanation": "“不停”表示动作接连不断地进行，而“参加一次面试”只发生一次，二者矛盾，这里不能用“不停”修饰。"}, {"text": "他不停地赢得了这场比赛，大家都很激动。", "explanation": "“赢得比赛”是一次完成的结果，不是能够持续不停进行的动作，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：表示尾巴持续摆动，与“小狗见到主人”时的兴奋相符。"}, {"text": "懒洋洋", "is_correct": false, "explanation": "语义：“懒洋洋”形容懒散、没有精神，与小狗见到主人时的兴奋不协调。"}, {"text": "冷冷", "is_correct": false, "explanation": "语义：“冷冷”形容态度冷淡，与见到主人时的亲热相冲突。"}, {"text": "一动不动", "is_correct": false, "explanation": "语义：“一动不动”指完全静止，与“尾巴……地摇”的动作直接矛盾。"}], "explanations": {"不停": "不停：表示尾巴持续摆动，与“小狗见到主人”时的兴奋相符。", "懒洋洋": "语义：“懒洋洋”形容懒散、没有精神，与小狗见到主人时的兴奋不协调。", "冷冷": "语义：“冷冷”形容态度冷淡，与见到主人时的亲热相冲突。", "一动不动": "语义：“一动不动”指完全静止，与“尾巴……地摇”的动作直接矛盾。"}, "sentence_index": 6, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一听到敲门声，他不停地跳了起来，去开门。", "explanation": "这里应该用〈立刻〉。“立刻”表示听到声音后马上做出的一次反应，“不停”强调持续不断，用在这里语义不通。"}, {"text": "风不停地停了下来，房间里一下子安静了。", "explanation": "这里“不停”的持续义与表示中断、停止的动作相冲突，不能用来修饰停止的动作。"}, {"text": "他不停地拿到了奖学金。", "explanation": "“拿到奖学金”是一次性的结果，不能持续不停地发生，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子不停得喊妈妈，声音越来越大。", "corrected_sentence": "孩子不停地喊妈妈，声音越来越大。", "error_description": "“不停地”中的“地”写成了“得”。作状语修饰动词时应用“地”；“得”用于动词或形容词之后引出补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈喊的不停，孩子才回家。", "corrected_sentence": "妈妈喊个不停，孩子才回家。", "error_description": "“个不停”是固定格式，中间的“个”不能换成“的”。应说“喊个不停”，不能说“喊的不停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指路线或过程的长短相反。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与长没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚指物体的厚度，与长不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指路线或过程的长短相反。", "快": "快指速度，与长没有反义关系。", "厚": "厚指物体的厚度，与长不构成反义。", "亮": "亮指光线，与长没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指路线或过程的长短相反。"}, {"text": "宽", "is_correct": false, "explanation": "宽指宽度，与长不构成反义，宽的反义是窄。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与长没有反义关系。"}, {"text": "暖", "is_correct": false, "explanation": "暖指温度，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指路线或过程的长短相反。", "宽": "宽指宽度，与长不构成反义，宽的反义是窄。", "轻": "轻指重量，与长没有反义关系。", "暖": "暖指温度，与长没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示路线或过程的环节多，距离远", "primary_collocate": null, "pronunciation": "cháng", "ipa": "ʈʂʰaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "供应链越长，用的水越多。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "从农场到餐桌的路线很长，要经过很多人。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条生产线太长，出问题的地方也多。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食物运输的链条越长，价格就越贵。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回家的路线太长了，我想换一条近的。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "审批的过程太长了，大家都等得着急。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线不长，走路半小时就到。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手续太多，办事的过程变得很长。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货物要坐船又坐火车，路线长，花的时间也多。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间的流程越长，出错的机会越多。", "target_word": "长", "complexity_tier": "T3", "furigana": "zhōng jiān de liú chéng yuè cháng, chū cuò de jī huì yuè duō.", "sentence_source": "generated"}], "morphological_forms": [{"form": "長", "label": "繁体"}, {"form": "长长的", "label": "重叠"}], "register": "通用", "sense_fingerprint": "形容词，读 cháng，指路线、链条、过程环节多、跨度大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是路线或过程的环节多、距离远。"}, {"text": "唱", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。"}, {"text": "场", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是场地。"}, {"text": "成", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。"}, {"text": "昌", "is_correct": false, "explanation": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}], "explanations": {"长": "cháng，意思是路线或过程的环节多、距离远。", "唱": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。", "厂": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。", "场": "chǎng（第三声）与 cháng（第二声）声调不同，意思是场地。", "成": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。", "昌": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说链条的环节多、跨度大，与“越……越”句式和句意相符。"}, {"text": "快", "is_correct": false, "explanation": "语义：快指速度，供应链的长短不能用快来说。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”与“供应链”不搭配，句子读来不通。"}, {"text": "亮", "is_correct": false, "explanation": "体貌：亮形容光线或外观，与供应链的长度无关。"}], "explanations": {"长": "长：说链条的环节多、跨度大，与“越……越”句式和句意相符。", "快": "语义：快指速度，供应链的长短不能用快来说。", "硬": "搭配：“硬”与“供应链”不搭配，句子读来不通。", "亮": "体貌：亮形容光线或外观，与供应链的长度无关。"}, "sentence_index": 0, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的工人很长，需要再招一些。", "explanation": "这里应该用〈多〉。长说路线或过程的长度、环节多，人数要用多。"}, {"text": "他的个子很长，站在人群里很显眼。", "explanation": "这里应该用〈高〉。长用于路线、距离和过程，人的身高要用高。"}, {"text": "我家离学校很长，每天要走很久。", "explanation": "这里应该用〈远〉。“离……”之后要说“很远”，不说“离……很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是路线或过程的环节多、距离远。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 cháng 韵母不同（an／ang），意思是蝉。"}, {"text": "潮", "is_correct": false, "explanation": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。"}, {"text": "缠", "is_correct": false, "explanation": "chán 与 cháng 韵母不同（an／ang），意思是缠绕。"}], "explanations": {"长": "cháng，意思是路线或过程的环节多、距离远。", "蝉": "chán 与 cháng 韵母不同（an／ang），意思是蝉。", "潮": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。", "虫": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。", "缠": "chán 与 cháng 韵母不同（an／ang），意思是缠绕。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说路线的距离远，与“不长，走路半小时就到”的句意相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：路线不说高矮，“高”与“路线”不搭配。"}, {"text": "深", "is_correct": false, "explanation": "语义：深指竖向的深度，路线不能用深来形容。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：厚形容物体的厚薄，路线没有厚度。"}], "explanations": {"长": "长：说路线的距离远，与“不长，走路半小时就到”的句意相符。", "高": "搭配：路线不说高矮，“高”与“路线”不搭配。", "深": "语义：深指竖向的深度，路线不能用深来形容。", "厚": "体貌：厚形容物体的厚薄，路线没有厚度。"}, "sentence_index": 6, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的速度很长，一小时只能开二十公里。", "explanation": "这里应该用〈快〉。速度的快慢要用“快”，“长”不能形容速度。"}, {"text": "这种水果的价格很长，我买不起。", "explanation": "这里应该用〈贵〉。价格的高低用“贵”来说，“长”不能形容价格。"}, {"text": "这个国家的面积很长。", "explanation": "这里应该用〈大〉。长说线状的距离或环节多，面积和规模要用大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运输路线长越，成本越高。", "corrected_sentence": "运输路线越长，成本越高。", "error_description": "错误：“长越”，应为“越长”。“越……越……”结构中，“越”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路线比那条长得，走路要多半个小时。", "corrected_sentence": "这条路线比那条长，走路要多半个小时。", "error_description": "错误：“长得”，应为“长”。“得”引出补语，这里没有补语，应去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“节约”构成反义，与“省水”的意思相对。"}, {"text": "锻炼", "is_correct": false, "explanation": "锻炼与“省水”没有反义关系，锻炼指身体活动。"}, {"text": "准备", "is_correct": false, "explanation": "准备与“省水”没有反义关系，指事先安排。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏与“省水”没有反义关系，指喜爱并赞赏。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“节约”构成反义，与“省水”的意思相对。", "锻炼": "锻炼与“省水”没有反义关系，锻炼指身体活动。", "准备": "准备与“省水”没有反义关系，指事先安排。", "欣赏": "欣赏与“省水”没有反义关系，指喜爱并赞赏。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“节约”构成反义，与“省水”的意思相对。"}, {"text": "思考", "is_correct": false, "explanation": "思考与“省水”没有反义关系，指用脑想问题。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行与“省水”没有反义关系，指外出游览。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与“省水”没有反义关系，指交换意见。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“节约”构成反义，与“省水”的意思相对。", "思考": "思考与“省水”没有反义关系，指用脑想问题。", "旅行": "旅行与“省水”没有反义关系，指外出游览。", "讨论": "讨论与“省水”没有反义关系，指交换意见。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "省水指节约用水，减少水的消耗。", "primary_collocate": null, "pronunciation": "shěng shuǐ", "ipa": "ʂɤŋ˨˩ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "我们少买一点衣服，就可以省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "洗手的时候关上水龙头，也是在省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天缺水，城里的人都要学会省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用淘米水浇花，既省水又方便。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校告诉学生们，每天都要省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新马桶能省水，一年能省不少钱。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水很贵的地方，大家都很注意省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省水，爸爸让我们一周洗两次衣服。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，刷牙时关水龙头就是省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱的时候，政府号召大家省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省水", "label": "原形"}], "register": "中性", "sense_fingerprint": "节约用水，减少水的消耗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省水", "is_correct": true, "explanation": "省水（shěng shuǐ）：节约用水，减少水的消耗。"}, {"text": "生水", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，生水指没有煮开的水。"}, {"text": "圣水", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，圣水指被视为神圣的水。"}, {"text": "上水", "is_correct": false, "explanation": "shàng（第四声）与 shěng（第三声）韵母与声调都不同，上水指供给的水。"}, {"text": "深水", "is_correct": false, "explanation": "shēn（第一声）与 shěng（第三声）韵母与声调都不同，深水指很深的水。"}], "explanations": {"省水": "省水（shěng shuǐ）：节约用水，减少水的消耗。", "生水": "shēng（第一声）与 shěng（第三声）声调不同，生水指没有煮开的水。", "圣水": "shèng（第四声）与 shěng（第三声）声调不同，圣水指被视为神圣的水。", "上水": "shàng（第四声）与 shěng（第三声）韵母与声调都不同，上水指供给的水。", "深水": "shēn（第一声）与 shěng（第三声）韵母与声调都不同，深水指很深的水。"}, "sentence_index": null, "correct_answer": "省水"}, "level_3": {"options": [{"text": "省水", "is_correct": true, "explanation": "省水：节约用水，与“少买衣服”的节约意思一致。"}, {"text": "浪费水", "is_correct": false, "explanation": "语义：“浪费水”与“少买衣服”的节约意思相反。"}, {"text": "花钱", "is_correct": false, "explanation": "语义：少买衣服应是节约钱，不说“花钱”。"}, {"text": "买水", "is_correct": false, "explanation": "语义：“买水”与少买衣服无关，句意不通。"}], "explanations": {"省水": "省水：节约用水，与“少买衣服”的节约意思一致。", "浪费水": "语义：“浪费水”与“少买衣服”的节约意思相反。", "花钱": "语义：少买衣服应是节约钱，不说“花钱”。", "买水": "语义：“买水”与少买衣服无关，句意不通。"}, "sentence_index": 0, "correct_answer": "省水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样买菜可以省水，又方便。", "explanation": "这里应该用〈省钱〉。省水指节约用水，省钱指节约花费；买菜省的是钱，不是水。"}, {"text": "用节能灯可以省水，也不伤眼。", "explanation": "这里应该用〈省电〉。省水指节约用水，节能灯节约的是电。"}, {"text": "这样排队可以省水，不用等很久。", "explanation": "这里应该用〈省时间〉。省水指节约用水，排队节省的是时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省水", "is_correct": true, "explanation": "省水：节约用水，与“水很贵”的语境相符。"}, {"text": "多用水", "is_correct": false, "explanation": "语义：“多用水”与“水很贵”的语境相反。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡与注意节水的语境无关。"}, {"text": "费钱", "is_correct": false, "explanation": "搭配：“注意”后不接“费钱”这类表示花费的词。"}], "explanations": {"省水": "省水：节约用水，与“水很贵”的语境相符。", "多用水": "语义：“多用水”与“水很贵”的语境相反。", "洗澡": "语义：洗澡与注意节水的语境无关。", "费钱": "搭配：“注意”后不接“费钱”这类表示花费的词。"}, "sentence_index": 6, "correct_answer": "省水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车很省水，大家都很喜欢。", "explanation": "这里应该用〈省油〉。省水指节约用水，汽车节约的是油。"}, {"text": "这台新冰箱很省水，家里人都很喜欢。", "explanation": "这里应该用〈省电〉。省水指节约用水，冰箱节约的是电，不是水。"}, {"text": "这把剪刀很省水，剪布很轻松。", "explanation": "这里应该用〈省力〉。省水指节约用水，剪刀让人少费力气，要说省力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今年省了一个水。", "corrected_sentence": "我们今年省了一点水。", "error_description": "量词误用：“水”是物质名词，不能用“个”，应说“一点水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没有省水过。", "corrected_sentence": "我从来没有省过水。", "error_description": "语序错误：体标“过”应紧跟动词，说“省过水”，不说“省水过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
