INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用洗衣液或洗衣粉和水来清洁衣服。", "primary_collocate": null, "pronunciation": "xǐ yī fu", "ipa": "ɕi˨˩ i˥ fu", "syllable_count": 3, "sentences": [{"text": "洗衣服时，也不要浪费水。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我用洗衣液洗衣服，衣服很香。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每个周末都在家洗衣服。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把脏衣服放进盆里，开始洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣粉用完了，我不能洗衣服了。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先用洗衣粉洗衣服，再用清水冲干净。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会洗衣服，只好请妈妈帮忙。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末天气很好，我在家洗衣服、晒被子。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣服要用温水，冷水洗不干净。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐，一边洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗洗衣服", "label": "重叠"}, {"form": "洗过衣服", "label": "体标"}], "register": "中性", "sense_fingerprint": "用洗衣液或洗衣粉加水清洁衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：指用洗衣液或洗衣粉加水清洁衣服，与“浪费水”的句意相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与用水无关，“唱歌时，也不要浪费水”读来不通。"}, {"text": "下棋", "is_correct": false, "explanation": "搭配：下棋不涉及用水，“浪费水”与“下棋”没有搭配关系。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：写作业与用水无关，句子的意思说不通。"}], "explanations": {"洗衣服": "洗衣服：指用洗衣液或洗衣粉加水清洁衣服，与“浪费水”的句意相符。", "唱歌": "语义：唱歌与用水无关，“唱歌时，也不要浪费水”读来不通。", "下棋": "搭配：下棋不涉及用水，“浪费水”与“下棋”没有搭配关系。", "写作业": "语义：写作业与用水无关，句子的意思说不通。"}, "sentence_index": 0, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗放进水池，开始洗衣服。", "explanation": "这里应该用〈洗碗〉。洗衣服是洗衣物，碗要用洗碗。"}, {"text": "他拿起扫帚，开始洗衣服。", "explanation": "这里应该用〈扫地〉。扫帚用于扫地，洗衣服不用扫帚。"}, {"text": "他拿起一个苹果，开始洗衣服。", "explanation": "这里应该用〈洗水果〉。洗衣服针对衣物，苹果要用洗水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：指用洗衣液或洗衣粉清洁衣服，与“不会”“请妈妈帮忙”的句意相符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是本能动作，不需要别人帮忙，句子读来荒谬。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：微笑是不及物动词，不能带“衣服”一类的宾语。"}, {"text": "眨眼", "is_correct": false, "explanation": "语义：眨眼是本能动作，不需要请妈妈帮忙，句意不通。"}], "explanations": {"洗衣服": "洗衣服：指用洗衣液或洗衣粉清洁衣服，与“不会”“请妈妈帮忙”的句意相符。", "呼吸": "语义：呼吸是本能动作，不需要别人帮忙，句子读来荒谬。", "微笑": "配价：微笑是不及物动词，不能带“衣服”一类的宾语。", "眨眼": "语义：眨眼是本能动作，不需要请妈妈帮忙，句意不通。"}, "sentence_index": 6, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把青菜放进水池，开始洗衣服。", "explanation": "这里应该用〈洗菜〉。洗衣服针对衣物，青菜要用洗菜。"}, {"text": "他拿起菜刀，开始洗衣服。", "explanation": "这里应该用〈切菜〉。菜刀用于切菜，洗衣服不用刀。"}, {"text": "他把鞋子放进盆里，开始洗衣服。", "explanation": "这里应该用〈洗鞋〉。洗衣服针对衣物，鞋子要用洗鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他洗衣服洗地很干净。", "corrected_sentence": "他洗衣服洗得很干净。", "error_description": "错误：“洗地”，应为“洗得”。动词后面引出补语要用“得”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗衣服地时候，别忘了关窗户。", "corrected_sentence": "洗衣服的时候，别忘了关窗户。", "error_description": "错误：“地时候”，应为“的时候”。“洗衣服”修饰名词“时候”，要用“的”，“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
