INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时尚指在一定时期内社会上流行的风气、习惯或样式，也指符合这种潮流的事物。", "primary_collocate": null, "pronunciation": "shí shàng", "ipa": "ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在当代全球化经济图景中，时尚产业的崛起不仅重塑了消费者的穿衣模式，更对地球脆弱的水资源系统施加了前所未有的压力。", "target_word": "时尚", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "时尚", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "时尚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年冬天的时尚是长款大衣。", "target_word": "时尚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "追逐时尚让服装公司生产越来越多的纺织品。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时尚的背后是强烈的消费主义文化。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人总是喜欢追求时尚。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂时尚，总是穿同一件衣服。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时尚每年都在变，去年的颜色今年没人穿了。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种帽子是十年前的时尚，现在没人戴了。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快时尚", "label": "复合"}, {"form": "時尚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时尚·一段时期内流行的风气或样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49c86a1a-5204-4936-87bc-89eede9ea748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时尚", "is_correct": true, "explanation": "时尚指一段时期内社会上流行的风气或样式。"}, {"text": "史上", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，史上指历史上。"}, {"text": "世上", "is_correct": false, "explanation": "声调混淆：shì（第四声）与 shí（第二声），世上指世界上。"}, {"text": "时常", "is_correct": false, "explanation": "ch 与 sh 声母不同，且声调也不同，时常指经常。"}], "explanations": {"时尚": "时尚指一段时期内社会上流行的风气或样式。", "史上": "shǐ（第三声）与 shí（第二声）声调不同，史上指历史上。", "世上": "声调混淆：shì（第四声）与 shí（第二声），世上指世界上。", "时常": "ch 与 sh 声母不同，且声调也不同，时常指经常。"}, "sentence_index": null, "correct_answer": "时尚"}, "level_3": {"options": [{"text": "工具", "is_correct": false, "explanation": "语义：“工具”是器具，“这种帽子是十年前的工具”句子不通。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：“时尚”指一段时期内流行的样式，“十年前的时尚”指当时流行、现已过时的款式，与句意相符。"}, {"text": "药品", "is_correct": false, "explanation": "语义：“药品”不是帽子，“这种帽子是十年前的药品”句子不通。"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”指头发的样式，帽子不能是发型，句子不通。"}], "explanations": {"工具": "语义：“工具”是器具，“这种帽子是十年前的工具”句子不通。", "时尚": "正确：“时尚”指一段时期内流行的样式，“十年前的时尚”指当时流行、现已过时的款式，与句意相符。", "药品": "语义：“药品”不是帽子，“这种帽子是十年前的药品”句子不通。", "发型": "语义：“发型”指头发的样式，帽子不能是发型，句子不通。"}, "sentence_index": 0, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台时尚今年很流行。", "explanation": "这里应该用〈种〉。〈台〉用于机器，时尚指潮流，应该用〈种〉。"}, {"text": "这个村子的时尚代代相传。", "explanation": "这里应该用〈风尚〉。风尚指长期形成的风气，可以代代相传；时尚变化快，不能代代相传。"}, {"text": "我每天都在时尚里上班。", "explanation": "这里应该用〈时尚行业〉。时尚指流行的风气或样式，不是场所，“在……里”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失败", "is_correct": false, "explanation": "语义：年轻人一般不会去追求失败，句子读起来自相矛盾。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：“追求时尚”是常见搭配，指追求流行的风气或样式。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“追求”后接理想、时尚、名利等，不搭配疾病。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得追求的东西，句子不通。"}], "explanations": {"失败": "语义：年轻人一般不会去追求失败，句子读起来自相矛盾。", "时尚": "正确：“追求时尚”是常见搭配，指追求流行的风气或样式。", "疾病": "搭配：“追求”后接理想、时尚、名利等，不搭配疾病。", "垃圾": "语义：垃圾不是值得追求的东西，句子不通。"}, "sentence_index": 6, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了早睡的时尚。", "explanation": "这里应该用〈习惯〉。习惯是个人长期养成的行为，时尚是社会上一段时期流行的样式或风气，不能说“养成……的时尚”。"}, {"text": "这项古老的仪式已经流行了两千年，是一种时尚。", "explanation": "这里应该用〈传统〉。时尚指一段时期内流行的风气，不能用来描述延续两千年的仪式。"}, {"text": "这道菜的时尚太咸了。", "explanation": "这里应该用〈味道〉。时尚指一段时期流行的风气或样式，不能用来形容菜的咸淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条时尚今年很流行。", "corrected_sentence": "这种时尚今年很流行。", "error_description": "错误：量词“条”用错，应为“这种时尚”。“条”用于细长的东西，时尚指潮流，应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是喜欢追求时尚们。", "corrected_sentence": "她总是喜欢追求时尚。", "error_description": "错误：“时尚”后多加了“们”。“们”只用于指人的名词之后，“时尚”是抽象事物，应为“喜欢追求时尚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
