INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示不止前面说的那样，还有更进一步的意思。", "primary_collocate": null, "pronunciation": "bù jǐn rú cǐ", "ipa": "pu˥˩ tɕin˨˩˦ ɻu˧˥ tsʰɨ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这家工厂很有名。不仅如此，生产过程中排出的废水常常含有化学物质。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很好吃。不仅如此，价格也不贵。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说英语，不仅如此，还会说日语。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王学习很努力。不仅如此，他还常常帮助同学。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市风景很美，不仅如此，生活也很方便。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思。不仅如此，它还很便宜。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁很快。不仅如此，坐地铁还很便宜。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，不仅如此，跳得也很高。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果很甜。不仅如此，对身体也很好。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会做饭，不仅如此，做得还特别好吃。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "递进连接，表示除前面所说之外还有更进一步的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fd9d1-c648-40bc-8ba1-18290f6f76e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：表示在前面所说之外再补充进一步的情况，这里引出废水的补充问题。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”后接好的结果，不接“常常含有化学物质”这类负面情况。"}, {"text": "因此", "is_correct": false, "explanation": "语义：这句前面没有原因，“因此”引出的结果无从谈起。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出假设不成立时的后果，这句只是陈述事实。"}], "explanations": {"不仅如此": "不仅如此：表示在前面所说之外再补充进一步的情况，这里引出废水的补充问题。", "幸好": "搭配：“幸好”后接好的结果，不接“常常含有化学物质”这类负面情况。", "因此": "语义：这句前面没有原因，“因此”引出的结果无从谈起。", "否则": "语义：“否则”引出假设不成立时的后果，这句只是陈述事实。"}, "sentence_index": 0, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想去公园，不仅如此，没有时间。", "explanation": "这里应该用〈但是〉。不仅如此表示在前文基础上再补充，这里前后是转折关系，要用但是。"}, {"text": "这次考试我很努力，不仅如此，没考好。", "explanation": "这里应该用〈不过〉。不仅如此表示递进补充，这里前后是转折关系，要用不过。"}, {"text": "他不是老师，不仅如此，是医生。", "explanation": "这里应该用〈而是〉。不仅如此是在肯定的基础上再补充，否定之后的纠正要用而是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：在“地铁很快”之外再补充一层，这里说坐地铁也便宜。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“很快”不是“便宜”的原因，“所以”引出的因果关系不成立。"}, {"text": "相反", "is_correct": false, "explanation": "语义：“还很便宜”是补充而不是相反，“相反”与语境矛盾。"}, {"text": "尤其是", "is_correct": false, "explanation": "搭配：“尤其是”后接名词，不接“坐地铁还很便宜”这样的完整小句。"}], "explanations": {"不仅如此": "不仅如此：在“地铁很快”之外再补充一层，这里说坐地铁也便宜。", "所以": "语义：“很快”不是“便宜”的原因，“所以”引出的因果关系不成立。", "相反": "语义：“还很便宜”是补充而不是相反，“相反”与语境矛盾。", "尤其是": "搭配：“尤其是”后接名词，不接“坐地铁还很便宜”这样的完整小句。"}, "sentence_index": 6, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如果明天下雨，不仅如此，我们就不去了。", "explanation": "这里应该用〈那么〉。不仅如此表示在前文基础上补充，不能用来连接条件和结论，条件之后的结论要用那么。"}, {"text": "我吃完饭，不仅如此，去散步。", "explanation": "这里应该用〈然后〉。不仅如此表示补充，不表示动作的先后，吃完饭再去散步要用然后。"}, {"text": "他现在很有钱，不仅如此，以前很穷。", "explanation": "这里应该用〈相反〉。不仅如此表示补充递进，现在与以前的情况形成对比，要用相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一名医生，不仅如此，而是一位作家。", "corrected_sentence": "他是一名医生，不仅如此，还是一位作家。", "error_description": "“不仅如此”之后递进补充要用“还”，不能用“而是”；“而是”只用于否定之后的更正（如“不是A，而是B”），这里前面没有否定。应说“不仅如此，还是一位作家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会弹钢琴，不仅如此，但是会唱歌。", "corrected_sentence": "他会弹钢琴，不仅如此，还会唱歌。", "error_description": "“不仅如此”要与“还”搭配表示递进，这里用“但是”表示转折，与前面的递进语境冲突，应说“还会唱歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
