INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被污染的水，通常含有有害物质，不适合饮用或使用。", "primary_collocate": null, "pronunciation": "wū shuǐ", "ipa": "u˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多工厂为了省钱，不处理污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "河边的工厂把污水排进了河里。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水里有很多有害的东西，不能直接喝。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在清理地上的污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水流进了田里，庄稼都死了。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排放污水要先经过处理。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的污水发出一股难闻的味道。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求公司不能乱排污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些污水含有很多化学物质。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨后，街上积了不少污水。", "target_word": "污水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一滩污水", "label": "量词"}, {"form": "工业污水", "label": "复合"}, {"form": "污水处理", "label": "复合"}], "register": "中性", "sense_fingerprint": "被污染、含有害物质、不能饮用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa49fc73-7be4-4cc3-904b-3ea617b1144c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污水", "is_correct": true, "explanation": "正确。“不处理污水”指不处理被污染的水，与“为了省钱”的语境一致。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水是干净的饮用水，不需要处理，不会因为省钱而不处理。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水是可以直接饮用的水，不是需要处理的对象。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“处理”一般不用来说“工资”，“不处理工资”不成词组，句意不通。"}], "explanations": {"污水": "正确。“不处理污水”指不处理被污染的水，与“为了省钱”的语境一致。", "矿泉水": "语义：矿泉水是干净的饮用水，不需要处理，不会因为省钱而不处理。", "饮用水": "语义：饮用水是可以直接饮用的水，不是需要处理的对象。", "工资": "搭配：“处理”一般不用来说“工资”，“不处理工资”不成词组，句意不通。"}, "sentence_index": 0, "correct_answer": "污水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们正在清理地上的一块污水。", "explanation": "这里应该用量词〈滩〉。污水是液体，积在地上要说“一滩”，不说“一块”。"}, {"text": "我们喝的是污水，觉得很解渴。", "explanation": "这里应该用〈矿泉水〉。污水不能饮用，说喝的水要用“矿泉水”等可以饮用的水。"}, {"text": "妈妈用污水做了一顿饭。", "explanation": "这里应该用〈清水〉。污水含有有害物质，不能用来做饭，做饭要用“清水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污水", "is_correct": true, "explanation": "正确。“河里的污水发出一股难闻的味道”符合被污染的水的特点。"}, {"text": "清水", "is_correct": false, "explanation": "语义：清水干净，不会发出难闻的味道，与“难闻”矛盾。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花的气味通常是好闻的，与“难闻”矛盾，而且不会出现在河里。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不会“发出味道”，“发出一股味道”只能搭配有气味的东西。"}], "explanations": {"污水": "正确。“河里的污水发出一股难闻的味道”符合被污染的水的特点。", "清水": "语义：清水干净，不会发出难闻的味道，与“难闻”矛盾。", "鲜花": "语义：鲜花的气味通常是好闻的，与“难闻”矛盾，而且不会出现在河里。", "石头": "搭配：石头不会“发出味道”，“发出一股味道”只能搭配有气味的东西。"}, "sentence_index": 6, "correct_answer": "污水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的污水很干净，可以直接用来洗菜。", "explanation": "这里应该用〈自来水〉。污水含有有害物质，不能说“很干净”，洗菜要用干净的水。"}, {"text": "他跑完步，全身出的是污水，湿透了衣服。", "explanation": "这里应该用〈汗水〉。污水是脏水，人跑步后出的是汗，要说“汗水”。"}, {"text": "今天的污水下得很大，我们只好待在家里。", "explanation": "这里应该用〈雨〉。“污水”指脏水，天上落下来的水要说“雨”，不说“污水下得很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上积了一块污水，工人正在清理。", "corrected_sentence": "地上积了一滩污水，工人正在清理。", "error_description": "错误：“一块污水”，正确：“一滩污水”。积在地面上的液体常用量词“滩”，不能用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小路上积不少污水，车都开不过去。", "corrected_sentence": "小路上积了不少污水，车都开不过去。", "error_description": "错误：“积不少”，正确：“积了不少”。表示已经发生的动作要用动态助词“了”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "正确。“微弱”与“强烈”是反义关系，指程度很低。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“强烈”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”与“强烈”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”与“强烈”没有反义关系。"}], "correct_answer": "微弱", "explanations": {"微弱": "正确。“微弱”与“强烈”是反义关系，指程度很低。", "清楚": "“清楚”与“强烈”没有反义关系。", "干净": "“干净”与“强烈”没有反义关系。", "整齐": "“整齐”与“强烈”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "正确。“微弱”与“强烈”是反义关系，指程度很低。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”的反义词是“吵闹”，与“强烈”没有反义关系。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”形容运动或状态平和，与“强烈”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”形容事物不复杂，与“强烈”没有反义关系。"}], "correct_answer": "微弱", "explanations": {"微弱": "正确。“微弱”与“强烈”是反义关系，指程度很低。", "安静": "“安静”的反义词是“吵闹”，与“强烈”没有反义关系。", "平稳": "“平稳”形容运动或状态平和，与“强烈”没有反义关系。", "简单": "“简单”形容事物不复杂，与“强烈”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容力量、程度、意志等非常强，超出一般水平。", "primary_collocate": null, "pronunciation": "qiáng liè", "ipa": "tɕʰjɑŋ˧˥ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "快时尚的背后是强烈的消费主义文化。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他对这个决定表示强烈反对。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对世界有强烈的好奇心。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的阳光非常强烈，出门要戴帽子。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影给我留下了强烈的印象。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两支球队形成了强烈的对比。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一种强烈的愿望，想去国外读书。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，他的反应很强烈。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民强烈要求政府解决问题。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强烈的地震让房子都摇了起来。", "target_word": "强烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强烈地", "label": "副词形式"}, {"form": "强烈反对", "label": "复合"}], "register": "中性", "sense_fingerprint": "力量、程度、意志等非常强，超出一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa49fc73-7be4-4cc3-904b-3ea617b1144c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强烈", "is_correct": true, "explanation": "正确。“强烈的消费主义文化”指影响很大、程度很高的文化现象，符合语境。"}, {"text": "微弱", "is_correct": false, "explanation": "搭配：“微弱”形容声音、光线等很弱，不用来修饰“文化”。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气、土地等含水分多，不用来修饰“文化”。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：“清淡”形容味道或颜色淡，不用来修饰“文化”。"}], "explanations": {"强烈": "正确。“强烈的消费主义文化”指影响很大、程度很高的文化现象，符合语境。", "微弱": "搭配：“微弱”形容声音、光线等很弱，不用来修饰“文化”。", "潮湿": "搭配：“潮湿”形容空气、土地等含水分多，不用来修饰“文化”。", "清淡": "搭配：“清淡”形容味道或颜色淡，不用来修饰“文化”。"}, "sentence_index": 0, "correct_answer": "强烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的经济越来越强烈。", "explanation": "这里应该用〈强大〉。“强烈”形容感受、光线、力量等程度很高，国家或经济的实力要说“强大”。"}, {"text": "她的身体很强烈，每天都能跑十公里。", "explanation": "这里应该用〈强壮〉。“强烈”不用来形容人的身体素质。"}, {"text": "我的数学成绩很强烈，老师很满意。", "explanation": "这里应该用〈好〉或〈优秀〉。“强烈”不用来描述成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强烈", "is_correct": true, "explanation": "正确。“她有一种强烈的愿望”指愿望很强，符合“想去国外读书”的语境。"}, {"text": "平整", "is_correct": false, "explanation": "搭配：“平整”形容表面，不能修饰“愿望”。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或气氛没有人气，与“愿望”不搭，也与“想去国外读书”的积极语境矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气或物体缺少水分，不能修饰“愿望”。"}], "explanations": {"强烈": "正确。“她有一种强烈的愿望”指愿望很强，符合“想去国外读书”的语境。", "平整": "搭配：“平整”形容表面，不能修饰“愿望”。", "冷清": "语义：“冷清”形容场所或气氛没有人气，与“愿望”不搭，也与“想去国外读书”的积极语境矛盾。", "干燥": "搭配：“干燥”形容空气或物体缺少水分，不能修饰“愿望”。"}, "sentence_index": 6, "correct_answer": "强烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的价格很强烈，我们都买不起。", "explanation": "这里应该用〈高〉。“强烈”形容感受或力量的程度，价格要说“高”。"}, {"text": "这袋米的分量很强烈，我一只手就能拎起来。", "explanation": "这里应该用〈轻〉。“强烈”说力量或程度，袋子的分量不大要说“轻”。"}, {"text": "这个学生的记性很强烈，一次就能记住。", "explanation": "这里应该用〈好〉。“强烈”不用来形容记性，记性要说“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光强烈地让人睁不开眼。", "corrected_sentence": "阳光强烈得让人睁不开眼。", "error_description": "错误：“强烈地”，正确：“强烈得”。“得”引出程度补语，表示“强烈到让人睁不开眼”；“地”修饰动作，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到消息后，她的情绪很很强烈。", "corrected_sentence": "听到消息后，她的情绪很强烈。", "error_description": "错误：“很很强烈”，正确：“很强烈”。程度副词“很”只用一次修饰形容词，重复使用不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
