INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物品的外形、样式或设计的类型。", "primary_collocate": null, "pronunciation": "kuǎn shì", "ipa": "kʰwan˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "广告鼓励人们不断购买新的款式。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家店的衣服款式很多，我看花了眼。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的颜色我喜欢，可是款式太旧了。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说这种款式的裙子现在不流行了。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你更喜欢哪种款式的手机？", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款沙发的款式简单，放在小房间里很好看。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都买不同款式的外套。", "target_word": "款式", "complexity_tier": "T3", "furigana": "tā měi nián dōu mǎi bùtóng kuǎnshì de wàitào", "sentence_source": "generated"}, {"text": "店员给我看了三种不同的款式。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的质量好，款式也很好看。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当设计师，每天都画新的款式。", "target_word": "款式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "新款式", "label": "复合"}], "register": "中性", "sense_fingerprint": "物品外形、设计的类型，常指服装、鞋包等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "款式", "is_correct": true, "explanation": "款式指物品的外形、样式，“新的款式”符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：购买的是商品，价格不能被购买，与“购买”不合。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“购买”不能支配“感情”，不能说“购买新的感情”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以购买的东西，与“购买”不合。"}], "explanations": {"款式": "款式指物品的外形、样式，“新的款式”符合句意。", "价格": "语义：购买的是商品，价格不能被购买，与“购买”不合。", "感情": "搭配：“购买”不能支配“感情”，不能说“购买新的感情”。", "天气": "语义：天气不是可以购买的东西，与“购买”不合。"}, "sentence_index": 0, "correct_answer": "款式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家的款式很独特，别人一看就认得出来。", "explanation": "这里应该用〈风格〉。款式指物品的外形或样式，画家作品的特点要用〈风格〉。"}, {"text": "他的款式很像他爸爸，大家一眼就能看出来。", "explanation": "这里应该用〈样子〉。款式只用于物品，说人的外貌要用〈样子〉。"}, {"text": "她的款式很温和，大家都喜欢和她相处。", "explanation": "这里应该用〈性格〉。款式指物品的样式，形容人的性情要用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "款式", "is_correct": true, "explanation": "款式指物品的样式，“不同款式的外套”符合句意。"}, {"text": "方言", "is_correct": false, "explanation": "搭配：“买”的对象是商品，不能说“买方言”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：外套不是按声音区分的，“不同声音的外套”说不通。"}, {"text": "人数", "is_correct": false, "explanation": "语义：外套不按人数分类，“不同人数的外套”不成立。"}], "explanations": {"款式": "款式指物品的样式，“不同款式的外套”符合句意。", "方言": "搭配：“买”的对象是商品，不能说“买方言”。", "声音": "语义：外套不是按声音区分的，“不同声音的外套”说不通。", "人数": "语义：外套不按人数分类，“不同人数的外套”不成立。"}, "sentence_index": 6, "correct_answer": "款式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想当设计师，每天都画一只新的款式。", "explanation": "这里应该用〈种〉。“只”用于动物或成对物中的一个，款式应用“种”。"}, {"text": "她想当设计师，每天都设计一张新的款式。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子等平面物，款式不用“张”。"}, {"text": "她想当设计师，每天都给客人看一本新的款式。", "explanation": "这里应该用〈种〉。“本”用于书册等，款式不用“本”，应说“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢这只款式的裙子，很适合上班。", "corrected_sentence": "我喜欢这种款式的裙子，很适合上班。", "error_description": "量词错误：款式前应用“种”，“只”用于动物或成对物中的一个。应把“这只款式”改为“这种款式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的款式多很，我们慢慢选吧。", "corrected_sentence": "这家店的款式很多，我们慢慢选吧。", "error_description": "词序错误：“很多”是程度副词加形容词，不能倒成“多很”。应改为“款式很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
