INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指已经被人穿过、不再崭新的衣物。", "primary_collocate": null, "pronunciation": "jiù yī fu", "ipa": "tɕjoʊ˥˩ i˥ fu", "syllable_count": 3, "sentences": [{"text": "社交媒体也让大家觉得旧衣服不好看。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "旧衣服大部分不会被回收，而是被烧掉或埋在地下。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把旧衣服送给了山区的孩子。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柜子里放着很多旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧衣服太小了，我不能穿了。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家里整理旧衣服，把不要的拿去捐。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服洗干净以后，还可以再穿。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常穿哥哥的旧衣服，一点也不在意。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口有一个箱子，专门收旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买新衣服以前，先看看家里有没有旧衣服。", "target_word": "旧衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "旧衣物", "label": "复合"}], "register": "中性", "sense_fingerprint": "已经穿过、不再崭新的衣物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧衣服", "is_correct": true, "explanation": "旧衣服指穿过、不再崭新的衣物，“觉得旧衣服不好看”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：说外观“不好看”，声音应说“好听”，不能说“声音不好看”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间没有“好看”的外观，与句意不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格没有外观可以“好看”，与句意不合。"}], "explanations": {"旧衣服": "旧衣服指穿过、不再崭新的衣物，“觉得旧衣服不好看”符合句意。", "声音": "搭配：说外观“不好看”，声音应说“好听”，不能说“声音不好看”。", "时间": "语义：时间没有“好看”的外观，与句意不合。", "价格": "语义：价格没有外观可以“好看”，与句意不合。"}, "sentence_index": 0, "correct_answer": "旧衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "柜子里放着一只旧衣服。", "explanation": "这里应该用〈件〉。“只”用于动物或成对物中的一个，衣服应用“件”。"}, {"text": "柜子里放着一张旧衣服。", "explanation": "这里应该用〈件〉。“张”用于纸、桌子等平面物，衣服不用“张”。"}, {"text": "柜子里放着一本旧衣服。", "explanation": "这里应该用〈件〉。“本”用于书册等，衣服应用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧衣服", "is_correct": true, "explanation": "旧衣服指穿过的衣物，“洗干净以后还可以再穿”符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是可以穿的东西，与“再穿”不合。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，不能说“穿米饭”。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不能穿，“洗干净以后还可以再穿”说不通。"}], "explanations": {"旧衣服": "旧衣服指穿过的衣物，“洗干净以后还可以再穿”符合句意。", "食物": "语义：食物不是可以穿的东西，与“再穿”不合。", "米饭": "搭配：“穿”的宾语应是衣物，不能说“穿米饭”。", "书本": "语义：书本不能穿，“洗干净以后还可以再穿”说不通。"}, "sentence_index": 6, "correct_answer": "旧衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔是我小时候的旧衣服，一直陪着我。", "explanation": "这里把〈旧衣服〉用来指人。“旧衣服”只指已被人穿过、不再崭新的衣物，不能用来指人。"}, {"text": "那只小猫是我家的旧衣服，每天陪我玩。", "explanation": "这里把〈旧衣服〉用来指动物。“旧衣服”只指衣物，不能用来指小猫这样的动物。"}, {"text": "他是我们班的旧衣服，大家都很喜欢他。", "explanation": "这里把〈旧衣服〉用来指人。“旧衣服”只指衣物，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一双旧衣服送给了弟弟。", "corrected_sentence": "我把一件旧衣服送给了弟弟。", "error_description": "量词错误：旧衣服应用“件”，“双”用于成对的东西。应把“一双旧衣服”改为“一件旧衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家阳台上晾着一张旧衣服。", "corrected_sentence": "我家阳台上晾着一件旧衣服。", "error_description": "量词错误：旧衣服应用“件”，“张”用于纸、桌子等平面物。应把“一张旧衣服”改为“一件旧衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
