INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13331, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对人力、财力、物资、时间等没有进行有效的利用，造成了不必要的消耗或损失。", "primary_collocate": null, "pronunciation": "làng fèi zī yuán", "ipa": "lɑŋ˥˩ feɪ˥˩ tsɹ̩˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "这不仅浪费资源，还伤害环境。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "工厂开着机器却没人用，这是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重复做同样的工作会浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司买了很多没用的设备，浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人才找不到工作，这也是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人能做的事，派三个人去做，就是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新楼盖好了却一直空着，真是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，别让工人白白等着，那是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在抢着做同一件事，会浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不想让工厂继续浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪費資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "浪费资源：人力、财力、物资、时间等没有被有效利用，造成不必要的消耗或损失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费资源", "is_correct": true, "explanation": "正确：“这不仅浪费资源，还伤害环境”，两项都是负面后果，并列合理。"}, {"text": "节约资源", "is_correct": false, "explanation": "语义：“节约资源”是正面的做法，与后句“还伤害环境”的负面评价相反，不能用“不仅…还”并列。"}, {"text": "保护环境", "is_correct": false, "explanation": "语义：“保护环境”与“伤害环境”直接矛盾。"}, {"text": "珍惜资源", "is_correct": false, "explanation": "搭配：“珍惜”爱惜的是资源，但与后句“伤害环境”形成正负矛盾，不能用“不仅…还”连接。"}], "explanations": {"浪费资源": "正确：“这不仅浪费资源，还伤害环境”，两项都是负面后果，并列合理。", "节约资源": "语义：“节约资源”是正面的做法，与后句“还伤害环境”的负面评价相反，不能用“不仅…还”并列。", "保护环境": "语义：“保护环境”与“伤害环境”直接矛盾。", "珍惜资源": "搭配：“珍惜”爱惜的是资源，但与后句“伤害环境”形成正负矛盾，不能用“不仅…还”连接。"}, "sentence_index": 0, "correct_answer": "浪费资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要合理浪费资源，保护环境。", "explanation": "这里应该用〈利用〉。浪费资源指白白耗用、造成损失，不能与“合理”搭配，要用合理利用。"}, {"text": "我们要浪费资源，不能随便用完。", "explanation": "这里应该用〈珍惜〉。浪费资源指白白耗用，表示爱惜时要用珍惜。"}, {"text": "这个地区正在浪费新资源，发展经济。", "explanation": "这里应该用〈开发〉。浪费资源指白白耗用，开发新资源是有效利用的意思，要用开发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费资源", "is_correct": true, "explanation": "正确：“新楼盖好了却一直空着，真是浪费资源”，是对空置情况的批评。"}, {"text": "明智之举", "is_correct": false, "explanation": "语义：“明智之举”是褒义评价，与“一直空着”的批评语气相反。"}, {"text": "物尽其用", "is_correct": false, "explanation": "语义：“物尽其用”表示充分利用，与“一直空着”的情况相反。"}, {"text": "有益的投资", "is_correct": false, "explanation": "搭配：“有益的投资”指值得做的投入，不能用来评价空置的楼房。"}], "explanations": {"浪费资源": "正确：“新楼盖好了却一直空着，真是浪费资源”，是对空置情况的批评。", "明智之举": "语义：“明智之举”是褒义评价，与“一直空着”的批评语气相反。", "物尽其用": "语义：“物尽其用”表示充分利用，与“一直空着”的情况相反。", "有益的投资": "搭配：“有益的投资”指值得做的投入，不能用来评价空置的楼房。"}, "sentence_index": 6, "correct_answer": "浪费资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法可以浪费资源，降低成本。", "explanation": "这里应该用〈节省〉。浪费资源指白白耗用、造成损失，与“节省”的意思相反，也和“降低成本”矛盾。"}, {"text": "这家工厂把闲置设备全部用上，真是浪费资源。", "explanation": "这里应该用〈节约〉。浪费资源指白白耗用，与“把闲置设备全部用上”的做法相反，说成“真是浪费资源”就自相矛盾。"}, {"text": "这些旧零件修好以后还能浪费资源，不必扔掉。", "explanation": "这里应该用〈循环使用〉。浪费资源指白白耗用，与“修好以后还能用、不必扔掉”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种浪费资源做法很常见。", "corrected_sentence": "这种浪费资源的做法很常见。", "error_description": "的字漏用：“浪费资源”作定语修饰名词“做法”时，中间要加“的”。应说“浪费资源的做法”，不能说“浪费资源做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法不应该继续被浪费资源。", "corrected_sentence": "这种做法不应该继续浪费资源。", "error_description": "被字误用：“浪费资源”是动宾结构，“资源”是宾语，不能在它前面直接加“被”。应去掉“被”，说“继续浪费资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
