INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指衣物等经久耐用，不容易穿坏。", "primary_collocate": null, "pronunciation": "nài chuān", "ipa": "naɪ˥˩ tʂʰwan˥", "syllable_count": 2, "sentences": [{"text": "要解决这个问题，消费者可以买质量好、耐穿的衣服，减少购买次数。", "target_word": "耐穿", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这双鞋很耐穿，我穿了三年。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛仔裤比较耐穿，所以很多人喜欢。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件外套又好看又耐穿。", "target_word": "耐穿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子爱玩，最好给他买耐穿的鞋。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布很厚，做出来的衣服特别耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贵的衣服不一定耐穿。", "target_word": "耐穿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢买耐穿的衣服，不常换新的。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸的皮鞋穿了十年，真耐穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作服要耐穿，因为天天都要穿。", "target_word": "耐穿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "耐穿：衣物、鞋子等质量好，经久耐用，不容易穿坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐穿", "is_correct": true, "explanation": "耐穿：衣物经穿、不易穿坏，与“质量好”相合，句意通顺。"}, {"text": "易破", "is_correct": false, "explanation": "语义：“易破”说明衣服容易破，与前面的“质量好”相矛盾。"}, {"text": "劣质", "is_correct": false, "explanation": "语义：“劣质”指质量差，与“质量好”直接冲突。"}, {"text": "脆弱", "is_correct": false, "explanation": "搭配：“脆弱”多用于人或心理等方面，一般不用来形容衣服。"}], "explanations": {"耐穿": "耐穿：衣物经穿、不易穿坏，与“质量好”相合，句意通顺。", "易破": "语义：“易破”说明衣服容易破，与前面的“质量好”相矛盾。", "劣质": "语义：“劣质”指质量差，与“质量好”直接冲突。", "脆弱": "搭配：“脆弱”多用于人或心理等方面，一般不用来形容衣服。"}, "sentence_index": 0, "correct_answer": "耐穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画很耐穿。", "explanation": "这里应该用〈耐看〉。耐穿只用于衣物、鞋袜等穿在身上或脚上的东西，画作要说耐看。"}, {"text": "这台机器很耐穿。", "explanation": "这里应该用〈耐用〉。耐穿只说衣物鞋袜经穿，长期使用的机器要说耐用。"}, {"text": "这座桥修得很耐穿。", "explanation": "这里应该用〈结实〉。耐穿只用于衣物鞋袜，桥梁等建筑要说结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐穿", "is_correct": true, "explanation": "耐穿：衣服经穿不易坏，与“贵的衣服不一定……”的语境相合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”只用于味道，不能用来形容衣服。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”指味道刺激，衣服不能是辣的，与句意无关。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”多用于食物或水，不用来形容衣服。"}], "explanations": {"耐穿": "耐穿：衣服经穿不易坏，与“贵的衣服不一定……”的语境相合。", "甜": "搭配：“甜”只用于味道，不能用来形容衣服。", "辣": "语义：“辣”指味道刺激，衣服不能是辣的，与句意无关。", "咸": "搭配：“咸”多用于食物或水，不用来形容衣服。"}, "sentence_index": 6, "correct_answer": "耐穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地板很耐穿。", "explanation": "这里应该用〈耐磨〉。耐穿指衣物鞋袜经穿，地板耐磨损要说耐磨。"}, {"text": "这口锅很耐穿。", "explanation": "这里应该用〈耐热〉。耐穿只用于衣物鞋袜，锅具耐高温要说耐热。"}, {"text": "这棵树很耐穿。", "explanation": "这里应该用〈耐寒〉。耐穿只用于衣物鞋袜，植物耐低温要说耐寒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套很很耐穿，穿了三年都没坏。", "corrected_sentence": "这件外套很耐穿，穿了三年都没坏。", "error_description": "重复错误：“很”只能用一次修饰“耐穿”，不能说“很很耐穿”。应说“很耐穿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一件耐穿得外套，冬天每天都穿。", "corrected_sentence": "我想买一件耐穿的外套，冬天每天都穿。", "error_description": "的字误用：修饰名词“外套”要用“的”，“得”只用于补语，应说“耐穿的外套”，不能说“耐穿得外套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
