INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事件发生的回数。", "primary_collocate": null, "pronunciation": "cì shù", "ipa": "tsʰɹ̩˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "要解决这个问题，消费者可以买质量好、耐穿的衣服，减少购买次数。", "target_word": "次数", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他每周去健身房的次数很多。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我你去过北京的次数。", "target_word": "次数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个月里，他迟到的次数越来越多。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师记下了每个学生发言的次数。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用手机的次数太多，对眼睛不好。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器可以使用的次数有限。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "练习的次数多了，你就会越来越熟练。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们比较一下两个人跑步的次数吧。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让他减少喝咖啡的次数。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次数：某个事件或动作发生的回数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数（cì shù）：指事情发生的回数，是本题要听辨的正确词。"}, {"text": "字数", "is_correct": false, "explanation": "字数（zì shù）：字的数目。zì 与 cì 声母不同（z 与 c），声调相同，意思是字数。"}, {"text": "词数", "is_correct": false, "explanation": "词数（cí shù）：词的数目。cí（第二声）与 cì（第四声）声调不同，意思是词数。"}, {"text": "质数", "is_correct": false, "explanation": "质数（zhì shù）：即素数。zhì 与 cì 声母不同（zh 与 c），声调相同，意思是质数。"}, {"text": "齿数", "is_correct": false, "explanation": "齿数（chǐ shù）：齿轮的齿的数目。chǐ（第三声）与 cì（第四声）声母不同（ch 与 c），声调也不同。"}], "explanations": {"次数": "次数（cì shù）：指事情发生的回数，是本题要听辨的正确词。", "字数": "字数（zì shù）：字的数目。zì 与 cì 声母不同（z 与 c），声调相同，意思是字数。", "词数": "词数（cí shù）：词的数目。cí（第二声）与 cì（第四声）声调不同，意思是词数。", "质数": "质数（zhì shù）：即素数。zhì 与 cì 声母不同（zh 与 c），声调相同，意思是质数。", "齿数": "齿数（chǐ shù）：齿轮的齿的数目。chǐ（第三声）与 cì（第四声）声母不同（ch 与 c），声调也不同。"}, "sentence_index": null, "correct_answer": "次数"}, "level_3": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数：指买东西的回数，与“减少购买”搭配，表示购买的频率降低。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“购买”的对象是东西，不能说“减少购买价格”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以“减少购买”的数量，句意不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“减少购买”说的是次数或数量，不能搭配“尺寸”。"}], "explanations": {"次数": "次数：指买东西的回数，与“减少购买”搭配，表示购买的频率降低。", "价格": "搭配：“购买”的对象是东西，不能说“减少购买价格”。", "颜色": "语义：颜色不是可以“减少购买”的数量，句意不通。", "尺寸": "搭配：“减少购买”说的是次数或数量，不能搭配“尺寸”。"}, "sentence_index": 0, "correct_answer": "次数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的次数越来越重。", "explanation": "这里应该用〈体重〉。次数指事情发生的回数，不能用来说人的轻重。"}, {"text": "这辆车的次数越来越快。", "explanation": "这里应该用〈速度〉。次数指回数，不能用来形容车的快慢。"}, {"text": "这个城市的次数越来越多。", "explanation": "这里应该用〈人口〉。次数指回数，不能用来指城市里的人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数：指使用机器的回数，可以有上限，与“有限”搭配，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“使用”的对象不能是价格，“使用的价格有限”不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：机器没有可以被“使用”的味道，与句意不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能被“使用”，“使用的体重有限”说不通。"}], "explanations": {"次数": "次数：指使用机器的回数，可以有上限，与“有限”搭配，句意通顺。", "价格": "搭配：“使用”的对象不能是价格，“使用的价格有限”不成立。", "味道": "语义：机器没有可以被“使用”的味道，与句意不合。", "体重": "搭配：“体重”不能被“使用”，“使用的体重有限”说不通。"}, "sentence_index": 6, "correct_answer": "次数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的次数太大了，穿不下。", "explanation": "这里应该用〈尺码〉。次数指回数，不能用来说衣服的大小。"}, {"text": "这一条次数很多。", "explanation": "这里应该用〈个〉，说“这个次数很多”。次数是抽象的回数，不能用“条”计量。"}, {"text": "他的一份次数很多。", "explanation": "这里应该用〈个〉。次数是抽象名词，不能用“份”计量，“份”用于食物、文件等分量或套装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月的迟到次数比上个月多一条。", "corrected_sentence": "他这个月的迟到次数比上个月多一次。", "error_description": "量词错误：次数的增加量应用量词“次”，“条”只用于条状事物，不能计量次数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他决定减少打游戏得次数。", "corrected_sentence": "他决定减少打游戏的次数。", "error_description": "的字误用：修饰名词“次数”要用“的”，“得”只用于补语，应说“打游戏的次数”，不能说“打游戏得次数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
