INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担负某项工作、系统或流程的责任，确保其正常运作，或对结果承担责任。", "primary_collocate": null, "pronunciation": "fù zé", "ipa": "fu˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "一些国家已经开始推动环保法规，要求企业对供应链负责。", "target_word": "负责", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小王负责公司的网络系统。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条生产线由老李负责，出了问题要找他。", "target_word": "负责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机房的设备一直由张工程师负责检查。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁负责今天的报销流程？", "target_word": "负责", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理要对整个项目的质量负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果系统出了问题，就找负责的工程师。", "target_word": "负责", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "仓库的出货流程由我们组负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他负责每天检查机器是不是正常。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套软件出错了，开发团队必须负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "负责了", "label": "体标"}, {"form": "负责过", "label": "体标"}, {"form": "负责人", "label": "复合"}, {"form": "負責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "担负某项工作或系统的责任，确保其正常运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负责", "is_correct": true, "explanation": "正确答案。负责 fù zé：对某项工作或事务承担责任。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂 fù zá 与 负责 fù zé 只有第二音节韵母不同（zá 与 zé），意思是不简单、繁复。"}, {"text": "父子", "is_correct": false, "explanation": "父子 fù zǐ 与 负责 fù zé 第二音节声调不同（zǐ 第三声，zé 第二声），意思是父亲和儿子。"}, {"text": "负载", "is_correct": false, "explanation": "负载 fù zài 与 负责 fù zé 第二音节的韵母和声调都不同（zài 第四声，zé 第二声），意思是承受的重量。"}], "explanations": {"负责": "正确答案。负责 fù zé：对某项工作或事务承担责任。", "复杂": "复杂 fù zá 与 负责 fù zé 只有第二音节韵母不同（zá 与 zé），意思是不简单、繁复。", "父子": "父子 fù zǐ 与 负责 fù zé 第二音节声调不同（zǐ 第三声，zé 第二声），意思是父亲和儿子。", "负载": "负载 fù zài 与 负责 fù zé 第二音节的韵母和声调都不同（zài 第四声，zé 第二声），意思是承受的重量。"}, "sentence_index": null, "correct_answer": "负责"}, "level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印行书刊，不能用来说企业对供应链的责任，句子不通。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“要求企业对供应链负责”指企业对供应链承担责任，与环保法规的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与环保法规和供应链的语境无关。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“对＋供应链”这样的对象。"}], "explanations": {"出版": "语义：“出版”指印行书刊，不能用来说企业对供应链的责任，句子不通。", "负责": "正确：“要求企业对供应链负责”指企业对供应链承担责任，与环保法规的语境相符。", "唱": "语义：“唱”指发出歌声，与环保法规和供应链的语境无关。", "游泳": "配价：“游泳”是不及物动词，不能带“对＋供应链”这样的对象。"}, "sentence_index": 0, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "张工程师一直负责机房的主任。", "explanation": "这里应该用〈担任〉。“负责”针对具体工作或事务，职务名词要用“担任”，不能说“负责”加职务。"}, {"text": "张工程师一直负责机房的压力。", "explanation": "这里应该用〈承受〉。“负责”针对工作和事务，压力是一种感受，应说“承受压力”。"}, {"text": "张工程师一直负责这座城市的心情。", "explanation": "这里应该用〈关注〉。“负责”针对具体工作或事务，心情不是可以负责的对象，应说“关注心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉的工程师”与“系统出了问题，就找……”的求助语境相悖。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“负责的工程师”指负责该系统的工程师，与“出了问题就找”前后呼应。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要带食物作宾语，“吃的”不能直接指代工程师。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与解决系统问题无关，句子语义荒谬。"}], "explanations": {"睡觉": "语义：“睡觉的工程师”与“系统出了问题，就找……”的求助语境相悖。", "负责": "正确：“负责的工程师”指负责该系统的工程师，与“出了问题就找”前后呼应。", "吃": "配价：“吃”需要带食物作宾语，“吃的”不能直接指代工程师。", "结婚": "语义：“结婚”与解决系统问题无关，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开发团队负责了歉意。", "explanation": "这里应该用〈表达〉。“负责”针对工作和事务，歉意是情感，应说“表达歉意”。"}, {"text": "开发团队负责了责任。", "explanation": "这里应该用〈承担〉。固定搭配是“承担责任”，“负责”后面要接工作或事务，不能直接接“责任”。"}, {"text": "开发团队向用户负责感谢。", "explanation": "这里应该用〈表示〉。“负责”只能以工作或事务作宾语，“感谢”是动作，不能作“负责”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司要产品的安全负责。", "corrected_sentence": "我们公司要对产品的安全负责。", "error_description": "“要……负责”中，负责的对象要用介词“对”引出。漏掉“对”，“要产品的安全负责”不成立；正确形式为“要对产品的安全负责”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这名工程师负责很认真。", "corrected_sentence": "这名工程师负责得很认真。", "error_description": "动词后带程度补语时，需要用结构助词“得”。漏掉“得”，“负责很认真”不成立；正确形式为“负责得很认真”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业是指国民经济中生产同类产品或提供同类服务的企业的集合，如工业、农业等。", "primary_collocate": null, "pronunciation": "chǎn yè", "ipa": "ʈʂʰan˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "产业", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农业是国家最重要的产业之一。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的主要产业是旅游。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想发展新的产业，帮助年轻人找工作。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统产业需要新技术，才能继续发展。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车产业给这座城市带来了很多工作机会。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，互联网产业发展得非常快。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司想进入电影产业。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护环境，这个产业必须减少污染。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在服装产业工作了十年。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "产业链", "label": "复合"}, {"form": "产业园", "label": "复合"}, {"form": "產業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国民经济中生产同类产品或提供同类服务的企业的集合，如工业、农业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指国民经济中同类企业的集合，符合“时尚产业的生态逻辑”的语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人体的状态，“时尚体温的生态逻辑”搭配不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是个人情绪，不是可以被“重构”的生态系统。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是产业或系统，不存在“生态逻辑”。"}], "explanations": {"产业": "产业指国民经济中同类企业的集合，符合“时尚产业的生态逻辑”的语境。", "体温": "语义：“体温”是人体的状态，“时尚体温的生态逻辑”搭配不通。", "心情": "语义：“心情”是个人情绪，不是可以被“重构”的生态系统。", "天气": "语义：“天气”不是产业或系统，不存在“生态逻辑”。"}, "sentence_index": 0, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司是一个大产业。", "explanation": "这里应该用〈企业〉。产业指同类企业的总和，不能指一家公司。"}, {"text": "他的产业是医生。", "explanation": "这里应该用〈职业〉。产业指一类企业或行业的整体，不指个人从事的工作。"}, {"text": "这个产业有两千名学生。", "explanation": "这里应该用〈学校〉。产业是企业的集合，不能指拥有学生的学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指同类企业的集合，可以“发展得很快”，符合“互联网产业”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是空间，不是可以“发展得非常快”的领域。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：“心脏”是器官，不能作为“互联网”的发展对象。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”通常说上涨或增长，不说“互联网学费发展得很快”。"}], "explanations": {"产业": "产业指同类企业的集合，可以“发展得很快”，符合“互联网产业”的语境。", "厨房": "语义：“厨房”是空间，不是可以“发展得非常快”的领域。", "心脏": "语义：“心脏”是器官，不能作为“互联网”的发展对象。", "学费": "搭配：“学费”通常说上涨或增长，不说“互联网学费发展得很快”。"}, "sentence_index": 6, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去产业看电影。", "explanation": "这里应该用〈影院〉。产业指同类企业的集合，不是可以去看电影的场所。"}, {"text": "他每天在产业里做饭，饭菜很香。", "explanation": "这里应该用〈厨房〉。产业指同类企业的集合，不是做饭的地方。"}, {"text": "他很喜欢这个产业，每天都去那里买书。", "explanation": "这里应该用〈书店〉。产业指同类企业的集合，不是买书的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一件重要的产业。", "corrected_sentence": "这个城市有一个重要的产业。", "error_description": "量词错误：“产业”应搭配量词“个”或“种”，不能用“件”。正确说法是“一个重要的产业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想找一份汽车产业地工作。", "corrected_sentence": "他们想找一份汽车产业的工作。", "error_description": "「汽车产业」修饰名词「工作」时应用「的」，不能用「地」。「地」用于修饰动词，所以应说「汽车产业的工作」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰落", "is_correct": true, "explanation": "“衰落”与“崛起”意义相反，指国家或力量由强变弱。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是体育动作，与“崛起”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”是心理活动，与“崛起”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常动作，与“崛起”没有反义关系。"}], "correct_answer": "衰落", "explanations": {"衰落": "“衰落”与“崛起”意义相反，指国家或力量由强变弱。", "游泳": "“游泳”是体育动作，与“崛起”没有反义关系。", "思考": "“思考”是心理活动，与“崛起”没有反义关系。", "睡觉": "“睡觉”是日常动作，与“崛起”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
