INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物兴起、上升或发展壮大，如国家、力量等从弱到强。", "primary_collocate": null, "pronunciation": "jué qǐ", "ipa": "tɕyɛ˧˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "在当代人工智能发展的宏大叙事中，开源自主AI代理的崛起正重新定义技术演进的边界。", "target_word": "崛起", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代全球化经济图景中，快时尚产业的崛起不仅重塑了消费者的穿衣模式，更对地球脆弱的水资源系统施加了前所未有的压力。", "target_word": "崛起", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个国家在短短几十年里迅速崛起了。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国的崛起让世界看到了新的机会。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多新能源企业在这几年崛起了。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们希望国家和平崛起，不想和别人打仗。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着经济发展，南方的一些小城市也崛起了。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司靠新技术在行业中崛起。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个强大的新对手正在崛起，我们要小心。", "target_word": "崛起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，很多国家都是在战争后崛起的。", "target_word": "崛起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "崛起了", "label": "体标"}, {"form": "崛起过", "label": "体标"}], "register": "书面", "sense_fingerprint": "国家、产业或力量从弱到强，迅速兴起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f95e5d-4e87-424f-8121-0527036d276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崛起", "is_correct": true, "explanation": "“的崛起”把“崛起”名词化，指开源AI代理的兴起，与“宏大叙事”“重新定义边界”的语境相符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不能“重新定义技术演进的边界”，句意荒谬。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语词，与这句书面语的学术语境不合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不能作“重新定义边界”的主语。"}], "explanations": {"崛起": "“的崛起”把“崛起”名词化，指开源AI代理的兴起，与“宏大叙事”“重新定义边界”的语境相符。", "早餐": "语义：早餐不能“重新定义技术演进的边界”，句意荒谬。", "饭碗": "语域：“饭碗”是口语词，与这句书面语的学术语境不合。", "体重": "语义：体重是身体的数值，不能作“重新定义边界”的主语。"}, "sentence_index": 0, "correct_answer": "崛起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物价在一个月里崛起了两成。", "explanation": "这里应该用〈上升〉。崛起指由弱变强、迅速兴起，物价等数值的增加要用“上升”。"}, {"text": "他每天早上七点就崛起了，然后去跑步。", "explanation": "这里应该用〈起床〉。崛起指国家、力量由弱变强，人早上起床要用“起床”，不能用“崛起”。"}, {"text": "这个城市的人口崛起很快。", "explanation": "这里应该用〈增长〉。崛起强调由弱到强的兴起，人口数量的增加要用“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崛起", "is_correct": true, "explanation": "“也崛起了”说明这些小城市也由弱变强，与“随着经济发展”的语境相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：小城市不会“融化”，与“随着经济发展”的积极语境冲突。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，不能指城市由弱变强，与语境相反。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是人的动作，不能以小城市作主语。"}], "explanations": {"崛起": "“也崛起了”说明这些小城市也由弱变强，与“随着经济发展”的语境相符。", "融化": "语义：小城市不会“融化”，与“随着经济发展”的积极语境冲突。", "熄灭": "语义：“熄灭”指火或光灭掉，不能指城市由弱变强，与语境相反。", "咳嗽": "配价：“咳嗽”是人的动作，不能以小城市作主语。"}, "sentence_index": 6, "correct_answer": "崛起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款手机的系统今年崛起了。", "explanation": "这里应该用〈升级〉。崛起用于国家、产业或力量由弱变强，软件版本的提高要用“升级”。"}, {"text": "这个地区的工厂数量崛起了。", "explanation": "这里应该用〈增加〉。崛起指国家、力量由弱到强的发展壮大，工厂数量的增多要用“增加”，不能用“崛起”。"}, {"text": "这个孩子的个子今年崛起了不少。", "explanation": "这里应该用〈长高〉。崛起指国家、力量由弱变强，人个子增高要用“长高”，不能用“崛起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小国在这几年里迅速崛起。", "corrected_sentence": "那个小国在这几年里迅速崛起了。", "error_description": "漏掉表示完成的“了”：叙述已经发生的变化要在动词后加“了”，应说“迅速崛起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市崛起的很快。", "corrected_sentence": "这座城市崛起得很快。", "error_description": "补语错误：表示程度的补语要用“得”引出，“崛起的很快”误用“的”，应说“崛起得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱衣", "is_correct": true, "explanation": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与穿衣都是日常动作，二者并无反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是步行活动，与穿衣没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是休息动作，与穿衣不构成反义。"}], "correct_answer": "脱衣", "explanations": {"脱衣": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。", "吃饭": "吃饭与穿衣都是日常动作，二者并无反义关系。", "散步": "散步是步行活动，与穿衣没有反义关系。", "睡觉": "睡觉是休息动作，与穿衣不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
