INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "棉花是锦葵科棉属植物的种籽纤维，可用于纺织、制作衣物等。", "primary_collocate": null, "pronunciation": "mián huā", "ipa": "mjɛn˧˥ xwa˥", "syllable_count": 2, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "棉花", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "棉花的纤维很长，可以纺成细线。", "target_word": "棉花", "complexity_tier": "T3", "furigana": "mián hua de xiān wéi hěn cháng, kě yǐ fǎng chéng xì xiàn", "sentence_source": "generated"}, {"text": "新疆出产的棉花又白又软。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民秋天在地里摘棉花。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是用棉花做的，穿着很舒服。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "棉花吸水很好，所以毛巾常用它做。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把棉花纺成线，再织成布。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天穿棉花做的衣服，既透气又凉快。", "target_word": "棉花", "complexity_tier": "T3", "furigana": "xià tiān chuān mián hua zuò de yī fu, jì tòu qì yòu liáng kuai", "sentence_source": "generated"}, {"text": "这家工厂每年要买几万吨棉花。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "棉花的价格今年涨了。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一团棉花", "label": "量词"}, {"form": "一包棉花", "label": "量词"}], "register": "中性", "sense_fingerprint": "棉属植物的种籽纤维，纺织原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d983af5-8a29-4125-88b7-ed3ab525497b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棉花", "is_correct": true, "explanation": "正确：“棉花”是种植作物，有种植阶段，需要大量灌溉。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不是植物，不能种植，也没有种植阶段。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是矿物，不能种植，不存在种植阶段。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“种植阶段”要求可种植的作物，不能说“天气种植阶段”。"}], "explanations": {"棉花": "正确：“棉花”是种植作物，有种植阶段，需要大量灌溉。", "钢铁": "语义：钢铁不是植物，不能种植，也没有种植阶段。", "石油": "语义：石油是矿物，不能种植，不存在种植阶段。", "天气": "搭配：“种植阶段”要求可种植的作物，不能说“天气种植阶段”。"}, "sentence_index": 0, "correct_answer": "棉花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用棉花缝了一颗扣子。", "explanation": "这里应该用〈棉线〉。棉花是松散的纤维，不能用来缝扣子，缝扣子要用线。"}, {"text": "工厂用棉花榨油，油色很淡。", "explanation": "这里应该用〈棉籽〉。榨油用的是棉籽，棉花是纤维，不能榨油。"}, {"text": "妈妈买了棉花，准备裁成窗帘。", "explanation": "这里应该用〈棉布〉。棉布是布料，可以裁剪；棉花是松散的纤维，不能裁成窗帘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棉花", "is_correct": true, "explanation": "正确：“棉花”可以纺成线，再织成布。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头坚硬且不是纤维，纺不成线。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食品原料，不是纤维，不能纺线。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：纺线要求纤维材料，不能说把木头纺成线。"}], "explanations": {"棉花": "正确：“棉花”可以纺成线，再织成布。", "石头": "语义：石头坚硬且不是纤维，纺不成线。", "面粉": "语义：面粉是食品原料，不是纤维，不能纺线。", "木头": "搭配：纺线要求纤维材料，不能说把木头纺成线。"}, "sentence_index": 6, "correct_answer": "棉花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一只棉花。", "explanation": "这里应该用〈包〉或〈团〉。“只”多用于动物或成对的东西，棉花不能用“只”来数。"}, {"text": "工厂里堆着几座棉花。", "explanation": "这里应该用〈包〉或〈团〉。“座”用于山、房屋、桥梁等大型固定物，棉花不能用“座”来数。"}, {"text": "仓库里有两匹棉花。", "explanation": "这里应该用〈包〉或〈团〉。“匹”用于马、骡以及成卷的布，棉花不能用“匹”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场收获地棉花很干净。", "corrected_sentence": "农场收获的棉花很干净。", "error_description": "修饰语错误：动词短语“收获”修饰名词“棉花”，应用“的”，不能用“地”。正确形式是“收获的棉花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农场运来了一头棉花。", "corrected_sentence": "农场运来了一包棉花。", "error_description": "量词错误：“棉花”应配“包”或“团”，“头”用于牲畜，不能用于棉花。正确形式是“一包棉花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
