INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13341, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对纺织品进行印花和染色的加工，使其带上图案或颜色。", "primary_collocate": null, "pronunciation": "yìn rǎn", "ipa": "in˥˩ ʐan˨˩˦", "syllable_count": 2, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "印染", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "印染", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂专门印染棉布和丝绸。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布要先洗干净，然后再印染。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用红色染料印染了这批布。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印染后的布颜色很鲜艳。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布印染过两次，颜色很深。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在印染一批给学校做校服的布。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印染时要控制好水温和时间。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布不好印染，颜色总是不均匀。", "target_word": "印染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "印染了", "label": "体标"}, {"form": "印染过", "label": "体标"}, {"form": "印染厂", "label": "复合"}], "register": "中性", "sense_fingerprint": "对纺织品印花、染色，使其带上图案或颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d983af5-8a29-4125-88b7-ed3ab525497b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印染", "is_correct": true, "explanation": "正确：“印染”指把织物浸入染料使其着色，属于后处理环节，符合句意。"}, {"text": "纺织", "is_correct": false, "explanation": "语义：纺织是前面的生产工序，不属于“后处理环节”，与句中的“后处理”相矛盾。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植发生在棉花生长阶段，与“后处理环节”不符，句中已有“棉花种植阶段”。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、毛发等，不用于布料的后处理环节。"}], "explanations": {"印染": "正确：“印染”指把织物浸入染料使其着色，属于后处理环节，符合句意。", "纺织": "语义：纺织是前面的生产工序，不属于“后处理环节”，与句中的“后处理”相矛盾。", "种植": "语义：种植发生在棉花生长阶段，与“后处理环节”不符，句中已有“棉花种植阶段”。", "修剪": "搭配：“修剪”用于枝叶、毛发等，不用于布料的后处理环节。"}, "sentence_index": 0, "correct_answer": "印染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂专门印染书籍。", "explanation": "这里应该用〈印刷〉。印染是把织物浸入染料使其着色，书籍的文字和图案要用印刷。"}, {"text": "我想把头发印染成金色。", "explanation": "这里应该用〈染〉。印染只用于织物，给头发着色要用“染”。"}, {"text": "我想把白纸印染成蓝色。", "explanation": "这里应该用〈上色〉。纸张不是织物，给白纸着色要用“上色”，不能说印染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印染", "is_correct": true, "explanation": "正确：“印染过两次”使布着色，“颜色很深”正是印染的结果，符合句意。"}, {"text": "漂白", "is_correct": false, "explanation": "语义：漂白会使布变浅，与“颜色很深”的结果相矛盾。"}, {"text": "缝制", "is_correct": false, "explanation": "搭配：“缝制”的对象是衣物等成品，“这块布缝制过两次”不成立，与句意不合。"}, {"text": "脱色", "is_correct": false, "explanation": "语义：脱色即除去颜色，与“颜色很深”的结果相矛盾。"}], "explanations": {"印染": "正确：“印染过两次”使布着色，“颜色很深”正是印染的结果，符合句意。", "漂白": "语义：漂白会使布变浅，与“颜色很深”的结果相矛盾。", "缝制": "搭配：“缝制”的对象是衣物等成品，“这块布缝制过两次”不成立，与句意不合。", "脱色": "语义：脱色即除去颜色，与“颜色很深”的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "印染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用彩灯印染房间，让屋子变得很亮。", "explanation": "这里应该用〈装饰〉。印染只用于布料着色，布置房间要用“装饰”。"}, {"text": "她花了一个下午印染那卷胶卷。", "explanation": "这里应该用〈冲洗〉。印染是把布料浸入染料使其着色，冲洗胶卷要用“冲洗”。"}, {"text": "他用抹布印染桌子。", "explanation": "这里应该用〈擦〉。印染是布料着色的工艺，擦桌子要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批布印染的很均匀。", "corrected_sentence": "这批布印染得很均匀。", "error_description": "错误：“印染的很均匀”。“印染”后接表示程度的补语时要用助词“得”，不能用“的”。正确形式是“印染得很均匀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人正在印染过一块棉布。", "corrected_sentence": "工人正在印染一块棉布。", "error_description": "错误：“正在印染过”。“正在”表示动作正在进行，“过”表示曾经经历，二者矛盾。正确形式是“正在印染一块棉布”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
