INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对事物发展起决定性作用的要素或条件。", "primary_collocate": null, "pronunciation": "guān jiàn yīn sù", "ipa": "kwan˥˥ tɕjɛn˥˩ in˥˥ su˥˩", "syllable_count": 4, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "关键因素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "价格是顾客买东西时的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气是这次比赛的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找出关键因素，问题就容易解决了。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力是他成功的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认为学习方法是关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影响产量的关键因素是水和阳光。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司最看重的关键因素是质量。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，是这次失败的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "位置好不好，是开店的关键因素。", "target_word": "关键因素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "關鍵因素", "label": "繁体"}], "register": "书面", "sense_fingerprint": "关键因素：对事物发展起决定作用的要素或条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关键因素", "is_correct": true, "explanation": "正确：“关键因素”指对事物发展起决定作用的要素，与“加剧水资源短缺”的语境相符。"}, {"text": "生态系统", "is_correct": false, "explanation": "语义：生态系统是被挤占水量的对象，不能成为加剧水资源短缺的原因。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水本身是被挤占的资源，不是加剧短缺的因素。"}, {"text": "措施", "is_correct": false, "explanation": "语义：纺织工业是产业部门，不能“成为”一项措施，句意不通。"}], "explanations": {"关键因素": "正确：“关键因素”指对事物发展起决定作用的要素，与“加剧水资源短缺”的语境相符。", "生态系统": "语义：生态系统是被挤占水量的对象，不能成为加剧水资源短缺的原因。", "饮用水": "语义：饮用水本身是被挤占的资源，不是加剧短缺的因素。", "措施": "语义：纺织工业是产业部门，不能“成为”一项措施，句意不通。"}, "sentence_index": 0, "correct_answer": "关键因素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的天气只是关键因素，最后还要看选手的水平。", "explanation": "这里应该用〈次要因素〉。“关键因素”指决定性的要素，与“只是”和“最后还要看选手”的语气相矛盾。"}, {"text": "下雨只是关键因素，并没有影响比赛的结果。", "explanation": "这里应该用〈偶然因素〉。“关键因素”必须对结果起决定作用，下雨既然没有影响结果，就不能称为关键因素。"}, {"text": "搜索时输入关键因素，就能找到需要的资料。", "explanation": "这里应该用〈关键词〉。“关键因素”指对事物发展起决定作用的要素，搜索时要输入的是“关键词”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关键因素", "is_correct": true, "explanation": "正确：“关键因素”指决定性的要素，符合“影响产量”的语境。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是人用来干活的器具，不是“水和阳光”这类影响产量的因素。"}, {"text": "产量", "is_correct": false, "explanation": "语义：“产量”本身是被“影响”的结果，不能作为影响产量的因素。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“影响产量”后接的应是能起作用的因素，“颜色”与之不搭配。"}], "explanations": {"关键因素": "正确：“关键因素”指决定性的要素，符合“影响产量”的语境。", "工具": "语义：工具是人用来干活的器具，不是“水和阳光”这类影响产量的因素。", "产量": "语义：“产量”本身是被“影响”的结果，不能作为影响产量的因素。", "颜色": "搭配：“影响产量”后接的应是能起作用的因素，“颜色”与之不搭配。"}, "sentence_index": 6, "correct_answer": "关键因素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最喜欢吃关键因素。", "explanation": "这里应该用〈食物〉。“吃”的对象是食物，“关键因素”指对事物发展起决定作用的要素或条件，不能吃。"}, {"text": "他把关键因素放进了抽屉。", "explanation": "这里应该用〈钥匙〉。“放进抽屉”的对象是实物，“关键因素”指决定性的要素或条件，不是可以放进抽屉的东西。"}, {"text": "他躲在关键因素后面。", "explanation": "这里应该用〈墙〉。“躲在…后面”需要可以遮挡的实物，“关键因素”是抽象概念，不能用来遮挡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告里漏掉了一只关键因素。", "corrected_sentence": "这份报告里漏掉了一个关键因素。", "error_description": "错误在于“关键因素”前的量词。应说“一个关键因素”，不能用“只”；“只”多用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "资金是这次项目的一只关键因素。", "corrected_sentence": "资金是这次项目的一项关键因素。", "error_description": "错误在于“关键因素”前的量词。应说“一项关键因素”，不能用“只”；“只”多用于动物或成对的物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
