INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强行挤入并占据（空间、时间、位置等）。", "primary_collocate": null, "pronunciation": "jǐ zhàn", "ipa": "tɕi˨˩˦ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "挤占", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "手机游戏挤占了孩子的学习时间。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的摊位挤占了人行道的空间。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的工厂挤占了农民的耕地。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加班太多，会挤占我们休息的时间。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车停在路上，挤占了自行车道。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络广告挤占了页面的大部分位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作挤占了他陪家人的时间。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼越建越多，挤占了公园的绿地。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货架上的新产品挤占了旧产品的位置。", "target_word": "挤占", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挤占了", "label": "体标：了"}, {"form": "挤占着", "label": "体标：着"}, {"form": "挤占过", "label": "体标：过"}, {"form": "擠佔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "强行挤入并占去时间、空间、资源等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挤占", "is_correct": true, "explanation": "正确：“挤占”指强行占去所需的水量，与句中“加剧水资源短缺”的语境一致。"}, {"text": "补充", "is_correct": false, "explanation": "语义：“补充”是增加供应，与“加剧短缺”的语境相反。"}, {"text": "灌溉", "is_correct": false, "explanation": "配价：“灌溉”的宾语应是田地或庄稼，不能以“水量”作宾语。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”表示省下，与“加剧水资源短缺”的语境相反。"}], "explanations": {"挤占": "正确：“挤占”指强行占去所需的水量，与句中“加剧水资源短缺”的语境一致。", "补充": "语义：“补充”是增加供应，与“加剧短缺”的语境相反。", "灌溉": "配价：“灌溉”的宾语应是田地或庄稼，不能以“水量”作宾语。", "节约": "语义：“节约”表示省下，与“加剧水资源短缺”的语境相反。"}, "sentence_index": 0, "correct_answer": "挤占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事挤占了我的感情。", "explanation": "这里应该用〈伤害〉。“挤占”指强行占去空间、时间或资源，不能用于感情。"}, {"text": "这次失败挤占了他的自信心。", "explanation": "这里应该用〈打击〉。“挤占”针对可以被占去的空间或资源，“自信心”不是可以被挤占的东西。"}, {"text": "噪音挤占了居民的健康。", "explanation": "这里应该用〈损害〉。“挤占”不能用于健康这类抽象的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挤占", "is_correct": true, "explanation": "正确：“挤占”指强行占去页面的位置，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”需要人作主语，“网络广告”不能欣赏页面。"}, {"text": "记录", "is_correct": false, "explanation": "语义：“记录”是把内容写下来，不能指占用页面位置。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉，与“占了大部分位置”的意思相反。"}], "explanations": {"挤占": "正确：“挤占”指强行占去页面的位置，符合句意。", "欣赏": "配价：“欣赏”需要人作主语，“网络广告”不能欣赏页面。", "记录": "语义：“记录”是把内容写下来，不能指占用页面位置。", "删除": "语义：“删除”是去掉，与“占了大部分位置”的意思相反。"}, "sentence_index": 6, "correct_answer": "挤占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天挤占两升水。", "explanation": "这里应该用〈饮用〉。“挤占”指强行占去空间、时间或资源，不能用于日常饮水。"}, {"text": "她在湖边挤占了一个微笑。", "explanation": "这里应该用〈露出〉。“挤占”针对可以被占去的空间、时间或资源，微笑不能被挤占。"}, {"text": "他在音乐会上挤占了一首新曲。", "explanation": "这里应该用〈欣赏〉。“挤占”不能用于欣赏作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的写字楼挤占在附近的绿地。", "corrected_sentence": "新的写字楼挤占了附近的绿地。", "error_description": "错误在于“挤占”后面的助词。应说“挤占了附近的绿地”，不能用“在”；“挤占在”不是规范用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作挤占到了我的周末时间。", "corrected_sentence": "工作挤占了我的周末时间。", "error_description": "错误在于“挤占”后面的补语。应说“挤占了我的周末时间”，不能加“到”；“挤占到”不是规范用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
