INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人们饮用的水。", "primary_collocate": null, "pronunciation": "yǐn yòng shuǐ", "ipa": "in˨˩ yʊŋ˥˩ ʂueɪ˨˩", "syllable_count": 3, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "饮用水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这里的井水不能当饮用水。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾区急需大量饮用水和食物。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里卖的饮用水有很多种。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的饮用水要经过严格检测。", "target_word": "饮用水", "complexity_tier": "T3", "furigana": "yǐn yòng shuǐ", "sentence_source": "generated"}, {"text": "这条河的水已经不是安全的饮用水了。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我会带两瓶饮用水。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把饮用水送到了山上的小学。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用机器把海水变成饮用水。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的饮用水每月都要检查。", "target_word": "饮用水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶饮用水", "label": "量词：瓶"}, {"form": "飲用水", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供人饮用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮用水", "is_correct": true, "explanation": "正确。“饮用水”指供人饮用的水，与“农业”并列，是被挤占的用水对象。"}, {"text": "土地", "is_correct": false, "explanation": "语义：土地本身不需要用水量，句中“所需的水量”的对象应是用水的主体，不能是土地。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不属于用水对象，与“挤占……所需的水量”的语义矛盾。"}, {"text": "道路", "is_correct": false, "explanation": "搭配：“所需的水量”要求前面是用水的主体，“道路”不能与之搭配。"}], "explanations": {"饮用水": "正确。“饮用水”指供人饮用的水，与“农业”并列，是被挤占的用水对象。", "土地": "语义：土地本身不需要用水量，句中“所需的水量”的对象应是用水的主体，不能是土地。", "空气": "语义：空气不属于用水对象，与“挤占……所需的水量”的语义矛盾。", "道路": "搭配：“所需的水量”要求前面是用水的主体，“道路”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "饮用水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台饮用水。", "explanation": "这里应该用〈瓶〉。饮用水是液体，要按容器计量；“台”多用于机器，不能用来量饮用水。"}, {"text": "这杯饮用水是甜的。", "explanation": "这里应该用〈饮料〉。饮用水指可以直接喝的纯净水，没有甜味；有甜味的要说饮料。"}, {"text": "这桶饮用水不能直接喝。", "explanation": "这里应该用〈生水〉。饮用水指可以直接喝的水，说“不能直接喝”自相矛盾；没烧开的水才叫生水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮用水", "is_correct": true, "explanation": "正确。“两瓶”是装液体的容器量词，“饮用水”是旅行时要带的可以喝的水。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是装在瓶里带着的东西，与“带两瓶”的语义不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能用“瓶”计量，句子说的是带的东西要能装进瓶子。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：量词“瓶”不能计量“行李”，应说“件”或“箱”。"}], "explanations": {"饮用水": "正确。“两瓶”是装液体的容器量词，“饮用水”是旅行时要带的可以喝的水。", "手机": "语义：手机不是装在瓶里带着的东西，与“带两瓶”的语义不合。", "电脑": "语义：电脑不能用“瓶”计量，句子说的是带的东西要能装进瓶子。", "行李": "搭配：量词“瓶”不能计量“行李”，应说“件”或“箱”。"}, "sentence_index": 6, "correct_answer": "饮用水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯饮用水很酸。", "explanation": "这里应该用〈果汁〉。饮用水是无味的纯水，不能说“很酸”；有酸味的要说果汁。"}, {"text": "这个箱子里装着两粒饮用水。", "explanation": "这里应该用〈瓶〉。“粒”用于颗粒状的东西，饮用水是液体，要用瓶、桶等量。"}, {"text": "他每天吃一瓶饮用水。", "explanation": "搭配：饮用水是用来喝的，应说“喝”，不能说“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把三个饮用水装进了车里。", "corrected_sentence": "我们把三桶饮用水装进了车里。", "error_description": "错误：“饮用水”是液体，不能用个体量词“个”计量。正确：应说“三桶饮用水”（或“三瓶饮用水”），用容器量词计量液体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人每天给学校送一条饮用水。", "corrected_sentence": "工人每天给学校送饮用水。", "error_description": "错误：“饮用水”是液体，不能用条状量词“条”计量。正确：去掉“一条”，说“工人每天给学校送饮用水。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
