INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指水的体积或质量。", "primary_collocate": null, "pronunciation": "shuǐ liàng", "ipa": "ʂueɪ˨˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "水量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年雨多，河里的水量很大。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天用水多，水库的水量下降了。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做米饭时，水量要合适。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雪化了，江里的水量增加了。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口井的水量很小，只够一家人用。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花不需要太多水量。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请注意控制浇花的水量。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，水量一下子变多了。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的水量每年都不一样。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用水量", "label": "复合词"}, {"form": "降水量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "水的体积或质量，水的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水量", "is_correct": true, "explanation": "正确。“水量”指水的体积或质量，是被挤占的对象，与“所需的”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能被挤占，也不是需要的用水量，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于需要的用水，与“挤占”的语义不合。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“所需的”后面接的应是可被占用的资源，“速度”不能作为资源。"}], "explanations": {"水量": "正确。“水量”指水的体积或质量，是被挤占的对象，与“所需的”搭配。", "温度": "语义：温度不能被挤占，也不是需要的用水量，句意不通。", "颜色": "语义：颜色不属于需要的用水，与“挤占”的语义不合。", "速度": "搭配：“所需的”后面接的应是可被占用的资源，“速度”不能作为资源。"}, "sentence_index": 0, "correct_answer": "水量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的水量很多，很湿润。", "explanation": "这里应该用〈水分〉。“水量”指水的体积或质量，说食物含水多要用“水分”。"}, {"text": "这口井的水量很甜。", "explanation": "语义：这里把〈水量〉当成了味道来用。“水量”指水的多少，不指味道，不能用来描述口感。"}, {"text": "湖边放着一块水量。", "explanation": "量词：“块”用于块状东西，“水量”是抽象名词，不能直接用“块”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水量", "is_correct": true, "explanation": "正确。“太多”修饰可以计量的数量，“水量”指花需要的水的多少。"}, {"text": "书本", "is_correct": false, "explanation": "语义：花不需要书本，句子说的是植物对水的需求。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与花的需求无关，句意不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“太多”修饰的应是植物可以使用的东西，“电视”不能用“太多”限定。"}], "explanations": {"水量": "正确。“太多”修饰可以计量的数量，“水量”指花需要的水的多少。", "书本": "语义：花不需要书本，句子说的是植物对水的需求。", "钢琴": "语义：钢琴与花的需求无关，句意不通。", "电视": "搭配：“太多”修饰的应是植物可以使用的东西，“电视”不能用“太多”限定。"}, "sentence_index": 6, "correct_answer": "水量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖里的水量很高，要注意安全。", "explanation": "这里应该用〈水位〉。“水量”指水的多少，水面的高低要用“水位”。"}, {"text": "湖边堆着两粒水量。", "explanation": "量词：“粒”用于颗粒状东西，“水量”是抽象名词，不能用“粒”计量。"}, {"text": "湖里的水量很好看。", "explanation": "语义：这里把〈水量〉当成了景色来用。“水量”指水的多少，不指水面的景象，所以不能用来评价外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汛期过后，河里的一个水量慢慢减少了。", "corrected_sentence": "汛期过后，河里的水量慢慢减少了。", "error_description": "错误：“水量”是抽象名词，前面不能直接加“一个”。正确：应去掉“一个”，说“河里的水量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井水量的很充足。", "corrected_sentence": "这口井水量很充足。", "error_description": "错误：“水量”后面不能加“的”再接“很”。正确：应说“水量很充足”，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
