INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把纤维纺成纱再织成布的生产活动或行业。", "primary_collocate": null, "pronunciation": "fǎng zhī", "ipa": "faŋ˨˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "更为严峻的是，全球许多纺织生产基地位于环境监管薄弱的发展中国家，其废水处理能力严重滞后。", "target_word": "纺织", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市的纺织很有名。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织需要很多工人和机器。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哥哥多年从事纺织。", "target_word": "纺织", "complexity_tier": "T3", "furigana": "tā gē ge duō nián cóng shì fǎng zhī", "sentence_source": "generated"}, {"text": "我国的纺织发展得很快。", "target_word": "纺织", "complexity_tier": "T3", "furigana": "wǒ guó de fǎng zhī fā zhǎn de hěn kuài", "sentence_source": "generated"}, {"text": "这家公司做了十年纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代纺织用机器，速度很快。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学学的是纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的纺织比北方发展得早。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织是这个地区的重要行业。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去国外学习纺织技术。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纺织品", "label": "复合"}, {"form": "纺织业", "label": "复合"}, {"form": "纺织厂", "label": "复合"}], "register": "书面", "sense_fingerprint": "把纤维纺成纱再织成布的生产活动或行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确答案：纺织（fǎng zhī），指把纤维纺成纱再织成布的生产活动或行业。"}, {"text": "仿制", "is_correct": false, "explanation": "仿制（fǎng zhì）与纺织只有第二个音节声调不同（zhì 第四声，zhī 第一声），意思是照着样子制造。"}, {"text": "放置", "is_correct": false, "explanation": "放置（fàng zhì）与纺织两个音节的声调都不同，意思是摆放、安置。"}, {"text": "防止", "is_correct": false, "explanation": "防止（fáng zhǐ）与纺织两个音节的声调都不同，意思是提前避免某事发生。"}, {"text": "防治", "is_correct": false, "explanation": "防治（fáng zhì）与纺织两个音节的声调都不同，意思是预防并治理（疾病、灾害）。"}, {"text": "反之", "is_correct": false, "explanation": "反之（fǎn zhī）只把第一个音节的韵尾由 ng 换成 n，声调不变，意思是相反地。"}], "explanations": {"纺织": "正确答案：纺织（fǎng zhī），指把纤维纺成纱再织成布的生产活动或行业。", "仿制": "仿制（fǎng zhì）与纺织只有第二个音节声调不同（zhì 第四声，zhī 第一声），意思是照着样子制造。", "放置": "放置（fàng zhì）与纺织两个音节的声调都不同，意思是摆放、安置。", "防止": "防止（fáng zhǐ）与纺织两个音节的声调都不同，意思是提前避免某事发生。", "防治": "防治（fáng zhì）与纺织两个音节的声调都不同，意思是预防并治理（疾病、灾害）。", "反之": "反之（fǎn zhī）只把第一个音节的韵尾由 ng 换成 n，声调不变，意思是相反地。"}, "sentence_index": null, "correct_answer": "纺织"}, "level_3": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确：此处是名词“纺织”修饰“生产基地”，与废水处理、行业规模的语境相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是需要大规模生产并排放废水的产品，与“废水处理能力滞后”的语境不合。"}, {"text": "文学", "is_correct": false, "explanation": "语义：文学作品不属于工业式的生产对象，“文学生产基地”与废水问题无关。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“影视基地”是固定说法，“电影生产基地”在这一语境中不自然。"}], "explanations": {"纺织": "正确：此处是名词“纺织”修饰“生产基地”，与废水处理、行业规模的语境相符。", "歌曲": "语义：歌曲不是需要大规模生产并排放废水的产品，与“废水处理能力滞后”的语境不合。", "文学": "语义：文学作品不属于工业式的生产对象，“文学生产基地”与废水问题无关。", "电影": "搭配：“影视基地”是固定说法，“电影生产基地”在这一语境中不自然。"}, "sentence_index": 0, "correct_answer": "纺织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店的纺织很便宜。", "explanation": "这里应该用〈纺织品〉。“纺织”指生产活动或行业，不能说“便宜”；能标价出售的是纺织品。"}, {"text": "她每天晚上在家纺织袜子。", "explanation": "这里应该用〈织〉。纺织指从纤维到布的生产活动，织袜子要用“织”。"}, {"text": "这床被子是用纺织做的。", "explanation": "这里应该用〈棉絮〉。纺织是活动或行业，不是可以拿来做被子的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确：“纺织”是可以用机器完成的生产活动，与“用机器，速度很快”相符。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法靠手写完成，“现代书法用机器”自相矛盾。"}, {"text": "手工", "is_correct": false, "explanation": "语义：“手工”指用手做，与“用机器，速度很快”直接矛盾。"}, {"text": "茶道", "is_correct": false, "explanation": "搭配：茶道讲究手艺与仪式，“现代茶道用机器”不搭配。"}], "explanations": {"纺织": "正确：“纺织”是可以用机器完成的生产活动，与“用机器，速度很快”相符。", "书法": "语义：书法靠手写完成，“现代书法用机器”自相矛盾。", "手工": "语义：“手工”指用手做，与“用机器，速度很快”直接矛盾。", "茶道": "搭配：茶道讲究手艺与仪式，“现代茶道用机器”不搭配。"}, "sentence_index": 6, "correct_answer": "纺织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区有一条纺织，很有名。", "explanation": "这里应该用〈个〉。“纺织”指行业，“条”用于细长的东西，不能用来计量行业。"}, {"text": "这个地区有一只纺织，很有名。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，不能计量行业。"}, {"text": "这个地区有一把纺织，很有名。", "explanation": "这里应该用〈个〉。“把”用于带柄的器具，不能用来计量行业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们把纤维纺织布。", "corrected_sentence": "工人们把纤维纺织成布。", "error_description": "“把”字句中，“纺织”后要带结果补语“成”，应说“把纤维纺织成布”，不能说“把纤维纺织布”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "纺织发展的很快。", "corrected_sentence": "纺织发展得很快。", "error_description": "“发展”后接程度补语要用“得”，不能用“的”，应说“纺织发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
