INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作为某种活动或组织中心的地方，通常指军事、生产或科研等活动的集中地点。", "primary_collocate": null, "pronunciation": "jī dì", "ipa": "tɕi˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个军事基地在山里。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边建了一个科研基地。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有一个大生产基地。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基地有很多研究人员。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友在基地工作了三年。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基地里有医院和学校。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是国家的重要基地。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们去农业基地参观过。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基地离城市很远。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把新基地建在南方。", "target_word": "基地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "军事基地", "label": "复合"}, {"form": "生产基地", "label": "复合"}], "register": "通用", "sense_fingerprint": "军事、生产或科研等活动集中的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基地", "is_correct": true, "explanation": "正确：“军事基地”是军事活动的集中地点，与“在山里”的语境相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的东西，不是活动的集中场所，“这个军事饮料在山里”不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不是活动的集中场所，“这个军事钢笔在山里”不通。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场供人游玩，与“军事”的语境矛盾。"}], "explanations": {"基地": "正确：“军事基地”是军事活动的集中地点，与“在山里”的语境相符。", "饮料": "语义：饮料是可以喝的东西，不是活动的集中场所，“这个军事饮料在山里”不通。", "钢笔": "语义：钢笔是书写工具，不是活动的集中场所，“这个军事钢笔在山里”不通。", "游乐场": "语义：游乐场供人游玩，与“军事”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "基地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们厂附近新建了一把生产基地。", "explanation": "这里应该用〈个〉。“把”用于带柄的器具，不能用来计量场所。"}, {"text": "山里有一只军事基地，很隐蔽。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，不能计量场所。"}, {"text": "海边有一条科研基地，规模很大。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来计量场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基地", "is_correct": true, "explanation": "正确：“国家的重要基地”指国家重要的活动集中地点，与语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是随身用品，不是国家重要的活动集中地点，“这里是国家的重要雨伞”不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是可以承担“国家重要”功能的场所或机构，语境不合。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“重要”一般修饰场所或机构，“国家的重要乐谱”搭配不当。"}], "explanations": {"基地": "正确：“国家的重要基地”指国家重要的活动集中地点，与语境相符。", "雨伞": "语义：雨伞是随身用品，不是国家重要的活动集中地点，“这里是国家的重要雨伞”不通。", "歌曲": "语义：歌曲不是可以承担“国家重要”功能的场所或机构，语境不合。", "乐谱": "搭配：“重要”一般修饰场所或机构，“国家的重要乐谱”搭配不当。"}, "sentence_index": 6, "correct_answer": "基地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语基地很扎实。", "explanation": "这里应该用〈基础〉。“扎实”修饰基础，基地指活动的集中场所，不能说英语的基地。"}, {"text": "政府设立了一笔新基地。", "explanation": "这里应该用〈基金〉。“设立一笔”搭配的是钱款，应说基金，基地是场所。"}, {"text": "这种病是由基地决定的。", "explanation": "这里应该用〈基因〉。疾病由基因决定，基地是场所，不能决定疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山里建了一只军事基地。", "corrected_sentence": "他们在山里建了一座军事基地。", "error_description": "“基地”是场所，量词应用“座”或“个”，不能用“只”，应说“一座军事基地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个基地建的很快。", "corrected_sentence": "这个基地建得很快。", "error_description": "“建”后接程度补语要用“得”，不能用“的”，应说“这个基地建得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
