INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "处在某个地方或位置。", "primary_collocate": null, "pronunciation": "wèi yú", "ipa": "weɪ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "学校位于城市的东边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园位于河的北面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家位于一座小山下面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的公司位于市中心。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家医院位于哪里？", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆位于二楼。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子位于两座山中间。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京位于中国的北部。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的酒店位于海边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站位于银行对面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "（建筑、地区等）处在某个位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "未雨", "is_correct": false, "explanation": "未雨（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是没有下雨。"}, {"text": "维语", "is_correct": false, "explanation": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。"}, {"text": "位移", "is_correct": false, "explanation": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。"}, {"text": "卫浴", "is_correct": false, "explanation": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "未雨": "未雨（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是没有下雨。", "维语": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。", "位移": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。", "卫浴": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“学校在城市东边”的意思相符。"}, {"text": "生活", "is_correct": false, "explanation": "语义：生活要求有生命的主语，学校不能“生活”。"}, {"text": "驻扎", "is_correct": false, "explanation": "搭配：“驻扎”的主语多为军队，不能说“学校驻扎”。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事件出现，学校是处所，不能作“发生”的主语。"}], "explanations": {"位于": "位于表示处在某个位置，与“学校在城市东边”的意思相符。", "生活": "语义：生活要求有生命的主语，学校不能“生活”。", "驻扎": "搭配：“驻扎”的主语多为军队，不能说“学校驻扎”。", "发生": "语义：“发生”指事件出现，学校是处所，不能作“发生”的主语。"}, "sentence_index": 0, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司位于困境中。", "explanation": "这里应该用〈处于〉。“位于”多指具体位置或地位（如“位于前列”），“困境”是状态，应说处于。"}, {"text": "爷爷位于沙发上看报纸。", "explanation": "这里应该用〈坐〉。位于只用于事物或机构的位置，人坐着的动作要用坐。"}, {"text": "我们位于学生宿舍里。", "explanation": "这里应该用〈住〉。位于说的是事物或机构的位置，人居住要用住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "谓语", "is_correct": false, "explanation": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。"}, {"text": "未愈", "is_correct": false, "explanation": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。"}, {"text": "微雨", "is_correct": false, "explanation": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "谓语": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。", "未愈": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。", "微雨": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“村子在两座山中间”的意思相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”的主语须是人或动物，村子不能游泳，与“两座山中间”的语境不合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”的主语须是人，村子不能散步。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”的主语须是能动的生物，村子不能跳。"}], "explanations": {"位于": "位于表示处在某个位置，与“村子在两座山中间”的意思相符。", "游泳": "语义：“游泳”的主语须是人或动物，村子不能游泳，与“两座山中间”的语境不合。", "散步": "语义：“散步”的主语须是人，村子不能散步。", "跳": "语义：“跳”的主语须是能动的生物，村子不能跳。"}, "sentence_index": 6, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸位于门口。", "explanation": "这里应该用〈站〉。位于只说事物的位置，人站立的动作要用站。"}, {"text": "我位于床上看书。", "explanation": "这里应该用〈躺〉。位于只说事物的位置，人躺卧在床上要用躺。"}, {"text": "这个城市位于很多大学。", "explanation": "这里应该用〈有〉。位于说具体位置，“很多大学”这类存在要用有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的银行位于在火车站旁边。", "corrected_sentence": "我们的银行位于火车站旁边。", "error_description": "错误：“位于”后面又加了“在”，写成“位于在”。“位于”本身已表示处在某处，不能再加“在”，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
