INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量、基础或条件不足，不够强。", "primary_collocate": null, "pronunciation": "báo ruò", "ipa": "pɑʊ˧˥ ʐwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "更为严峻的是，全球许多纺织生产基地位于环境监管薄弱的发展中国家，其废水处理能力严重滞后。", "target_word": "薄弱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个队的防守很薄弱，常常丢球。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的基础薄弱，所以要多练习。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农村的医疗条件还很薄弱。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学校的师资力量比较薄弱。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的数学比较薄弱，每天都要做题。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的管理很薄弱，经常出问题。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的法律意识太薄弱了，才会上当。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的体质薄弱，天冷时容易生病。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小公司实力薄弱，不敢接大项目。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "薄弱：力量、基础或条件不足，不够强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors