INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "助剂是指在化学、工业等过程中，添加到主要材料中起辅助作用、改善性能或促进反应的物质。", "primary_collocate": null, "pronunciation": "zhù jì", "ipa": "ʈʂu˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "助剂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂在塑料里加入了一种助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种助剂能让纸张更结实。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染料里的助剂可以让颜色更牢固。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把少量助剂倒进了搅拌桶。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每个月都要买很多助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加入助剂以后，橡胶变得更软了。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些助剂对人体有害，使用时要小心。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品里不能随便加入化学助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，助剂是帮忙改善材料性能的物质。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "化学助剂", "label": "复合"}], "register": "书面", "sense_fingerprint": "化工中加入材料、改善性能的辅助物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”指加入工业材料中的辅助物质，与“有毒化学”搭配，句意通顺。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“化学”多修饰物质、试剂，“化学食品”不通，且句子讲的是工业废水。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是化学物质，不能混在工业废水的成分里。"}, {"text": "植物", "is_correct": false, "explanation": "语义：工业废水的成分不会是植物，“化学植物”说不通。"}], "explanations": {"助剂": "“助剂”指加入工业材料中的辅助物质，与“有毒化学”搭配，句意通顺。", "食品": "搭配：“化学”多修饰物质、试剂，“化学食品”不通，且句子讲的是工业废水。", "乐器": "语义：乐器不是化学物质，不能混在工业废水的成分里。", "植物": "语义：工业废水的成分不会是植物，“化学植物”说不通。"}, "sentence_index": 0, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师很有助剂，学生都很喜欢他。", "explanation": "这里应该用〈学问〉。助剂指加入材料中的物质，不用来形容人的才学。"}, {"text": "这台电脑的助剂很快，打字特别顺。", "explanation": "这里应该用〈处理器〉。助剂指加入材料中的物质，不指电脑部件。"}, {"text": "这种助剂能杀死田里的害虫。", "explanation": "这里应该用〈农药〉。助剂不能用来杀虫，杀虫要说农药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”指加入橡胶的物质，与“加入……以后，橡胶变软”的语境相符。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不能加入橡胶使其变软，这句话的意思说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是材料，加入橡胶后橡胶变软说不通。"}, {"text": "清风", "is_correct": false, "explanation": "搭配：“加入”后面一般接物质或成分，“清风”不能加入。"}], "explanations": {"助剂": "“助剂”指加入橡胶的物质，与“加入……以后，橡胶变软”的语境相符。", "水果": "语义：水果不能加入橡胶使其变软，这句话的意思说不通。", "歌曲": "语义：歌曲不是材料，加入橡胶后橡胶变软说不通。", "清风": "搭配：“加入”后面一般接物质或成分，“清风”不能加入。"}, "sentence_index": 6, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种助剂能检验出水里的重金属。", "explanation": "这里应该用〈试剂〉。助剂是加入材料中起辅助作用的物质，检验成分要用试剂。"}, {"text": "我家的小狗助剂很多，每天陪我们散步。", "explanation": "这里应该用〈伙伴〉。助剂指加入材料中的物质，不用来形容动物。"}, {"text": "这把助剂很顺手，能帮我把木头削得更光滑。", "explanation": "“助剂”指加入材料中的物质，不指工具，这里说的是削木头的工具，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂在橡胶里加入了一条助剂。", "corrected_sentence": "工厂在橡胶里加入了一种助剂。", "error_description": "错误：量词“条”。正确：“种”。“助剂”的量词用“种”，“条”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们工厂每个月都要买一批助剂们。", "corrected_sentence": "我们工厂每个月都要买一批助剂。", "error_description": "错误：“助剂”后面加了“们”。正确：“一批助剂”。“们”不能加在物质名词后面，“助剂”是物质，不能说复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
