INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "未曾经过；没有经过。", "primary_collocate": null, "pronunciation": "wèi jīng", "ipa": "ueɪ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "未经允许，不能进入实验室。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经老师同意，学生不能离开教室。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水未经处理，不能直接喝。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经检查的食品不能卖给客人。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未经考虑就答应了朋友。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经本人同意，不得查看他的信。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药未经试验，不能给病人用。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经父母允许，孩子不要出远门。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂未经批准，不能建新的车间。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章未经作者同意，不能转发。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动词前，表示没有经过某个步骤或手续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经允许”表示没有取得许可，与“不能进入实验室”的限制相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示许可已取得，与后面“不能进入”的限制前提矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是允许”与“不能进入”相矛盾，句意不通。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即允许”说明马上批准，与“未经允许就不能进入”的前提结构不搭配。"}], "explanations": {"未经": "正确。“未经允许”表示没有取得许可，与“不能进入实验室”的限制相符。", "已经": "语义：“已经”表示许可已取得，与后面“不能进入”的限制前提矛盾。", "总是": "语义：“总是允许”与“不能进入”相矛盾，句意不通。", "立即": "搭配：“立即允许”说明马上批准，与“未经允许就不能进入”的前提结构不搭配。"}, "sentence_index": 0, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他未经去过北京。", "explanation": "这里应该用〈未曾〉。“未经”后接的是需要先经过的手续或同意，描述经历时应说“未曾去过”。"}, {"text": "我未经吃饭，就去上班了。", "explanation": "这里应该用〈还没〉。“未经”不用于日常行为的完成，表示还没做某事时应说“还没吃饭”。"}, {"text": "这位作家未经出版过三本书。", "explanation": "这里应该用〈已经〉。描述已经发生的经历要说“已经出版过”，“未经”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经试验”表示没有经过试验，与“不能给病人用”的结论相符。"}, {"text": "随意", "is_correct": false, "explanation": "语域：“随意试验”口语化，不符合药品试验的严肃语境。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，“从来试验”不成立。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带去做，药品试验不能是附带的事，与句意冲突。"}], "explanations": {"未经": "正确。“未经试验”表示没有经过试验，与“不能给病人用”的结论相符。", "随意": "语域：“随意试验”口语化，不符合药品试验的严肃语境。", "从来": "搭配：“从来”通常与否定词连用，“从来试验”不成立。", "顺便": "语义：“顺便”表示附带去做，药品试验不能是附带的事，与句意冲突。"}, "sentence_index": 6, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他未经按时到达公司。", "explanation": "这里应该用〈未能〉。“未经”表示没有经过某个手续，不能用来说明没有达到某个结果，应说“未能按时到达”。"}, {"text": "这次比赛他未经获胜。", "explanation": "这里应该用〈没有〉。获胜是结果，不是需要先经过的手续，应说“没有获胜”。"}, {"text": "他未经做过老师。", "explanation": "这里应该用〈曾经〉。描述经历时要说“曾经做过老师”，“未经”不能接已发生的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "未经了许可，不能在这里停车。", "corrected_sentence": "未经许可，不能在这里停车。", "error_description": "体标错误：“未经”是副词，后面不能加“了”，应说“未经许可，不能在这里停车。”，不说“未经了许可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他未经同意过就用了他的照片。", "corrected_sentence": "他未经同意就用了他的照片。", "error_description": "体标错误：“未经”后面接的动词“同意”不能带“过”，应说“未经同意就用了他的照片”，不说“未经同意过就用了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。"}, {"text": "紧张", "is_correct": false, "explanation": "紧张：指心情不安或局面吃紧，与“充分”的义项没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指清晰明白，与“充分”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：指速度快，与“充分”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。", "紧张": "紧张：指心情不安或局面吃紧，与“充分”的义项没有反义关系。", "清楚": "清楚：指清晰明白，与“充分”没有反义关系。", "迅速": "迅速：指速度快，与“充分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓：指动作或反应慢，与“充分”没有反义关系。"}, {"text": "高明", "is_correct": false, "explanation": "高明：指水平高、有见识，与“充分”没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "陌生：指不熟悉，与“充分”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。", "迟缓": "迟缓：指动作或反应慢，与“充分”没有反义关系。", "高明": "高明：指水平高、有见识，与“充分”没有反义关系。", "陌生": "陌生：指不熟悉，与“充分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
